        window.formatVNTime = function(date) {
            if (!date) return 'Chưa xác định';
            const d = (date instanceof Date) ? date : new Date(date);
            if (isNaN(d.getTime())) return 'N/A';
            
            // Use Intl.DateTimeFormat for robust control
            const timeFormatter = new Intl.DateTimeFormat('vi-VN', {
                timeZone: 'Asia/Ho_Chi_Minh',
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false
            });
            const dateFormatter = new Intl.DateTimeFormat('vi-VN', {
                timeZone: 'Asia/Ho_Chi_Minh',
                day: '2-digit',
                month: '2-digit',
                year: 'numeric'
            });
            
            return `${timeFormatter.format(d)} - ${dateFormatter.format(d)}`;
        };

        async function getInternetTime() {
            const servers = [
                { url: 'https://api.binance.com/api/v3/time', parser: data => new Date(data.serverTime) },
                { url: 'https://timeapi.io/api/Time/current/zone?timeZone=Asia/Ho_Chi_Minh', parser: data => new Date(data.dateTime) },
                { url: 'https://worldtimeapi.org/api/timezone/Asia/Ho_Chi_Minh', parser: data => new Date(data.datetime) }
            ];

            const fetchWithTimeout = async (server, timeout = 3000) => {
                const controller = new AbortController();
                const id = setTimeout(() => controller.abort(), timeout);
                try {
                    const response = await fetch(server.url, { signal: controller.signal });
                    clearTimeout(id);
                    if (response.ok) {
                        const data = await response.json();
                        return server.parser(data);
                    }
                } catch (e) {
                    clearTimeout(id);
                }
                return null;
            };

            for (const server of servers) {
                const time = await fetchWithTimeout(server);
                if (time && !isNaN(time.getTime())) return time;
            }

            return new Date();
        }

