        window.showChangePasswordModal = function showChangePasswordModal() {
            const currentUsername = currentUser ? currentUser.username : '';
            const isReadOnly = currentUser ? 'readonly' : '';
            const inputBg = currentUser ? 'bg-gray-100 cursor-not-allowed' : '';
            
            const modalContent = `
                <div class="p-8 text-center max-w-md mx-auto">
                    <div class="text-5xl mb-4">🔑</div>
                    <h3 class="text-2xl font-bold text-gray-800 mb-2">Đổi mật khẩu</h3>
                    <p class="text-gray-600 mb-6">Vui lòng nhập thông tin để đổi mật khẩu</p>
                    
                    <div class="space-y-4 text-left">
                        <div>
                            <label class="block text-sm font-medium text-gray-700 mb-1">Tên đăng nhập *</label>
                            <input type="text" id="change-username" value="${currentUsername}" ${isReadOnly} placeholder="Tên đăng nhập" class="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-purple-500 focus:outline-none ${inputBg}">
                        </div>
                        <div class="relative">
                            <label class="block text-sm font-medium text-gray-700 mb-1">Mật khẩu cũ *</label>
                            <input type="text" id="change-old-password" style="-webkit-text-security: disc;" autocomplete="off" data-lpignore="true" placeholder="Mật khẩu cũ" class="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-purple-500 focus:outline-none pr-12">
                            <button type="button" onclick="togglePasswordVisibility('change-old-password', this)" class="absolute bottom-0 right-0 mb-2 mr-3 flex items-center text-gray-500 hover:text-gray-700">
                                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                            </button>
                        </div>
                        <div class="relative">
                            <label class="block text-sm font-medium text-gray-700 mb-1">Mật khẩu mới *</label>
                            <input type="text" id="change-new-password" style="-webkit-text-security: disc;" autocomplete="off" data-lpignore="true" placeholder="Mật khẩu mới" class="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-purple-500 focus:outline-none pr-12">
                            <button type="button" onclick="togglePasswordVisibility('change-new-password', this)" class="absolute bottom-0 right-0 mb-2 mr-3 flex items-center text-gray-500 hover:text-gray-700">
                                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                            </button>
                        </div>
                        <div class="relative">
                            <label class="block text-sm font-medium text-gray-700 mb-1">Xác nhận mật khẩu mới *</label>
                            <input type="text" id="change-confirm-password" style="-webkit-text-security: disc;" autocomplete="off" data-lpignore="true" placeholder="Xác nhận mật khẩu mới" class="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-purple-500 focus:outline-none pr-12">
                            <button type="button" onclick="togglePasswordVisibility('change-confirm-password', this)" class="absolute bottom-0 right-0 mb-2 mr-3 flex items-center text-gray-500 hover:text-gray-700">
                                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                            </button>
                        </div>
                    </div>
                    
                    <div class="mt-8 flex justify-end gap-3">
                        <button onclick="${currentUser ? 'closeModal()' : 'showAdminLoginModal()'}" class="px-4 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 transition font-semibold">Quay lại</button>
                        <button onclick="changePassword()" class="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition font-semibold">Đổi mật khẩu</button>
                    </div>
                </div>
            `;
            showModal(modalContent);
        }

        window.changePassword = async function changePassword() {
            const username = document.getElementById('change-username')?.value?.trim() || '';
            const oldPassword = document.getElementById('change-old-password')?.value || '';
            const newPassword = document.getElementById('change-new-password')?.value || '';
            const confirmPassword = document.getElementById('change-confirm-password')?.value || '';

            if (!username || !oldPassword || !newPassword || !confirmPassword) {
                showToast('Vui lòng nhập đầy đủ thông tin!', 'error');
                return;
            }

            if (newPassword !== confirmPassword) {
                showToast('Mật khẩu mới và xác nhận mật khẩu không khớp!', 'error');
                return;
            }

            if (newPassword.length < 6) {
                showToast('Mật khẩu mới phải có ít nhất 6 ký tự!', 'error');
                return;
            }

            try {
                const response = await fetch('/api/auth/change-password', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ username, oldPassword, newPassword })
                });
                const resJson = await response.json();

                if (!response.ok || resJson.error) {
                    showToast('❌ ' + (resJson.error || 'Lỗi khi đổi mật khẩu!'), 'error');
                    return;
                }

                showToast('✅ Đổi mật khẩu thành công!', 'success');
                if (currentUser) {
                    closeModal();
                } else {
                    showAdminLoginModal();
                }
            } catch (err) {
                
if (err && err.message && err.message.includes("is not valid JSON")) {
    // Ignore HTML proxy errors from console
} else {
    console.error(err);
}
                showToast('❌ Lỗi kết nối!', 'error');
            }
        }

        window.showRegisterModal = function showRegisterModal() {
            showToast('Tính năng đăng ký đã bị khóa tuyệt đối. Chỉ Admin mới có quyền tạo tài khoản.', 'error');
            return;
        }

        async function userRegister() {
            showToast('Tính năng đăng ký đã bị khóa tuyệt đối. Chỉ Admin mới có quyền tạo tài khoản.', 'error');
            return;
        }

        window.togglePasswordVisibility = function togglePasswordVisibility(inputId, btn) {
            const input = document.getElementById(inputId);
            const isCustomPassword = input.hasAttribute('style') && input.getAttribute('style').includes('-webkit-text-security');
            const isHidden = input.type === 'password' || (isCustomPassword && input.style.webkitTextSecurity === 'disc');
            
            if (isHidden) {
                if (isCustomPassword) {
                    input.style.webkitTextSecurity = 'none';
                } else {
                    input.type = 'text';
                }
                btn.innerHTML = '<svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21"></path></svg>';
            } else {
                if (isCustomPassword) {
                    input.style.webkitTextSecurity = 'disc';
                } else {
                    input.type = 'password';
                }
                btn.innerHTML = '<svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>';
            }
        }

        window.adminLogin = async function adminLogin(isAutoLogin = false) {
            const usernameInput = document.getElementById('login-username');
            const passwordInput = document.getElementById('global-admin-password');
            const rememberCheckbox = document.getElementById('login-remember');
            const submitBtn = document.getElementById('login-submit-btn');

            const username = usernameInput ? usernameInput.value.trim() : (isAutoLogin ? localStorage.getItem('remember_username') : '');
            const password = passwordInput ? passwordInput.value : (isAutoLogin ? localStorage.getItem('remember_password') : '');
            
            if (!username || !password) {
                if (!isAutoLogin) showToast('Vui lòng nhập đầy đủ tên đăng nhập và mật khẩu!', 'error');
                document.getElementById('login-btn')?.classList.remove('hidden');
                return;
            }

            if (submitBtn && !isAutoLogin) {
                submitBtn.disabled = true;
                submitBtn.innerHTML = '<svg class="animate-spin h-4 w-4 mr-1 text-white" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4" fill="none"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg> Đang đăng nhập...';
            }

            try {
                const response = await fetch('/api/auth/login', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ username, password })
                });

                let data, error, token;
                
                if (!response.ok) {
                    const errRes = await response.json().catch(() => ({}));
                    error = errRes.error || "Tên đăng nhập hoặc mật khẩu không đúng";
                    data = null;
                } else {
                    const resJson = await response.json();
                    data = resJson.data;
                    error = resJson.error;
                    token = resJson.token;
                }

                if (error || !data) {
                    if (submitBtn) {
                        submitBtn.disabled = false;
                        submitBtn.innerHTML = 'Đăng nhập';
                    }
                    if (!isAutoLogin) {
                        const errMsg = error && error.includes('hạn mức') ? error : '❌ Tên đăng nhập hoặc mật khẩu không đúng!';
                        showToast(errMsg, 'error');
                    }
                    document.getElementById('login-btn')?.classList.remove('hidden');
                    return;
                }

                if (data.expiry_date && new Date(data.expiry_date) < new Date()) {
                    if (submitBtn) {
                        submitBtn.disabled = false;
                        submitBtn.innerHTML = 'Đăng nhập';
                    }
                    if (!isAutoLogin) showToast('❌ Tài khoản đã hết hạn sử dụng!', 'error');
                    return;
                }

                if (data.is_active === false) {
                    if (submitBtn) {
                        submitBtn.disabled = false;
                        submitBtn.innerHTML = 'Đăng nhập';
                    }
                    if (!isAutoLogin) showToast('❌ Tài khoản của bạn chưa được kích hoạt hoặc đã bị khóa!', 'error');
                    return;
                }

                // Luôn lưu lại thông tin đăng nhập thành công vào localStorage để tự động login lần sau
                localStorage.setItem('remember_username', username);
                localStorage.setItem('remember_password', password);
                localStorage.setItem('is_auto_login', 'true');

                if (token) localStorage.setItem('auth_token', token);
                currentUser = data;
                window.currentUser = currentUser;
                const roleLower = String(data.role || '').toLowerCase();
                const audienceLower = String(data.target_audience || '').toLowerCase();
                isAdminLoggedIn = (roleLower === 'admin' || audienceLower === 'admin' || audienceLower === 'quản trị viên');
                isTeacherLoggedIn = !isAdminLoggedIn && (audienceLower === 'giáo viên' || roleLower === 'teacher' || roleLower === 'giáo viên');
                window.isAdminLoggedIn = isAdminLoggedIn;
                window.isTeacherLoggedIn = isTeacherLoggedIn;
                
                await handleSuccessfulLogin();
            } catch (err) {
                if (submitBtn) {
                    submitBtn.disabled = false;
                    submitBtn.innerHTML = 'Đăng nhập';
                }
                if (err && err.message && err.message.includes("is not valid JSON")) {
                    // Ignore HTML proxy errors from console
                } else {
                    console.error(err);
                }
                if (!isAutoLogin) showToast('❌ Lỗi kết nối máy chủ!', 'error');
            }
        }

        async function handleSuccessfulLogin() {
            closeModal();
            
            // Cập nhật trạng thái hiển thị nút đăng nhập / đăng xuất
            document.getElementById('auth-status')?.classList.remove('hidden');
            document.getElementById('login-btn')?.classList.add('hidden');
            
            // XÓA SẠCH DẤU VẾT & DỮ LIỆU CŨ ĐỂ KHÔNG BỊ ẢNH HƯỞNG LẪN NHAU KHI ĐỔI TÀI KHOẢN
            questions = [];
            questionsLoaded = false;
            results = [];
            resultsLoaded = false;
            accountsLoaded = false;
            examsLoaded = false;

            if (typeof examToCreatorMap !== 'undefined') {
                for (let key in examToCreatorMap) delete examToCreatorMap[key];
            }
            if (typeof examIdToCreatorMap !== 'undefined') {
                for (let key in examIdToCreatorMap) delete examIdToCreatorMap[key];
            }
            if (window.unlockedExamIds) window.unlockedExamIds.clear();
            if (window.examNameToIdMap) {
                for (let key in window.examNameToIdMap) delete window.examNameToIdMap[key];
            }
            if (window.examToSharedResultsMap) {
                for (let key in window.examToSharedResultsMap) delete window.examToSharedResultsMap[key];
            }

            // Xóa sạch các bộ lọc của phiên làm việc trước
            const elStudentTeacher = document.getElementById('student-teacher-filter');
            if (elStudentTeacher) elStudentTeacher.value = '';
            const examSelect = document.getElementById('student-exam-name-filter');
            if (examSelect) examSelect.innerHTML = '<option value="">Chọn Bộ Câu hỏi/Đề thi</option>';
            const examTeacherFilter = document.getElementById('exam-teacher-filter');
            if (examTeacherFilter) examTeacherFilter.value = '';
            const qLessonFilter = document.getElementById('question-lesson-filter');
            if (qLessonFilter) qLessonFilter.value = '';
            const qSearch = document.getElementById('question-search');
            if (qSearch) qSearch.value = '';

            // Cập nhật Theme & Menu hiển thị ngay lập tức theo vai trò để giao diện đổi mượt mà
            updateThemeForRole();
            applyDoiTuongConfig();
            updateSidebarVisibility();

            // Nạp lại dữ liệu theo quyền hạn tài khoản đăng nhập đồng thời (Song song, không tuần tự)
            const loadTasks = [loadData()];
            if (isAdminLoggedIn || isTeacherLoggedIn) {
                loadTasks.push(loadQuestions(true));
            }
            await Promise.all(loadTasks);

            if (isAdminLoggedIn || isTeacherLoggedIn) {
                if (typeof updateQuestionStats === 'function') updateQuestionStats();
                if (typeof renderQuestionsList === 'function') renderQuestionsList();
                if (typeof updateLessonFilter === 'function') updateLessonFilter();
            }

            // Tự động điền thông tin học sinh nếu là học sinh đăng nhập
            if (currentUser.target_audience === 'Học sinh' || (!isAdminLoggedIn && !isTeacherLoggedIn)) {
                const nameInput = document.getElementById('guest_data_1');
                const lopInput = document.getElementById('guest_data_lop') || document.getElementById('guest_data_2');
                const donviInput = document.getElementById('guest_data_donvi');
                if (nameInput) {
                    nameInput.value = currentUser.full_name || '';
                    if (currentUser.full_name) {
                        nameInput.readOnly = true;
                        nameInput.classList.add('bg-gray-100', 'cursor-not-allowed');
                    }
                }
                if (lopInput) {
                    lopInput.value = currentUser.lop || '';
                    if (currentUser.lop) {
                        lopInput.readOnly = true;
                        lopInput.classList.add('bg-gray-100', 'cursor-not-allowed');
                    } else {
                        lopInput.readOnly = false;
                        lopInput.classList.remove('bg-gray-100', 'cursor-not-allowed');
                    }
                }
                if (donviInput) {
                    donviInput.value = currentUser.donvi || currentUser.address || '';
                    if (currentUser.donvi || currentUser.address) {
                        donviInput.readOnly = true;
                        donviInput.classList.add('bg-gray-100', 'cursor-not-allowed');
                    } else {
                        donviInput.readOnly = false;
                        donviInput.classList.remove('bg-gray-100', 'cursor-not-allowed');
                    }
                }
                updateStudentTeacherFilter();
            }
            
            // Tự động cập nhật thông tin người tạo trong cấu hình đề thi (chỉ cho giáo viên/admin)
            if (isAdminLoggedIn || isTeacherLoggedIn) {
                examConfig.creatorName = currentUser.full_name;
                examConfig.creatorId = currentUser.id;
                const elCreator = document.getElementById('exam-config-creator');
                if (elCreator) elCreator.value = currentUser.full_name;

                // Load danh sách tên đề thi của giáo viên này (Admin không nạp trước)
                if (!isAdminLoggedIn) {
                    await updateExamNamesList(false);
                }

                // KHÔNG TỰ ĐỘNG LOAD ĐỀ THI MỚI NHẤT TRONG TAB QUẢN LÝ
                // Luôn để ô chọn câu hỏi hoặc đề thi mặc định là "Chọn đề thi có sẵn" để giáo viên tự chọn
                resetExamPanelToDefault();
            }

            if (isAdminLoggedIn || isTeacherLoggedIn) {
                document.querySelector('[data-tab="questions"]')?.classList.remove('hidden');
                document.querySelector('[data-tab="exams"]')?.classList.remove('hidden');
                document.querySelector('[data-tab="ranking"]')?.classList.remove('hidden');
                
                // Ẩn tab Làm bài đối với Admin/Giáo viên
                document.getElementById('tab-exam')?.classList.remove('active');
                document.getElementById('tab-exam')?.classList.add('hidden');
                
                // Nếu là Admin hoặc Giáo viên, mặc định chuyển sang tab Trợ giúp khi đăng nhập thành công
                switchTab('help');
                
                // Cập nhật lại bộ lọc giáo viên (sẽ bị giới hạn nếu là giáo viên)
                updateExamTeacherFilter();
                
                // Mặc định lọc câu hỏi theo giáo viên vừa đăng nhập
                const teacherFilter = document.getElementById('exam-teacher-filter');
                if (teacherFilter && isTeacherLoggedIn && !isAdminLoggedIn) {
                    if (teacherFilter) teacherFilter.value = currentUser.id;
                    onExamTeacherFilterChange();
                }
            }
            if (isAdminLoggedIn || isTeacherLoggedIn) {
                document.querySelector('[data-tab="users"]')?.classList.remove('hidden');
                if (isAdminLoggedIn) {
                    document.querySelector('[data-tab="accounts"]')?.classList.remove('hidden');
                    document.querySelector('[data-tab="settings"]')?.classList.remove('hidden');
                    document.querySelector('[data-tab="teacher-assignment"]')?.classList.remove('hidden');
                } else {
                    document.querySelector('[data-tab="accounts"]')?.classList.add('hidden');
                    document.querySelector('[data-tab="settings"]')?.classList.add('hidden');
                    document.querySelector('[data-tab="teacher-assignment"]')?.classList.add('hidden');
                }
            } else {
                // If not admin and not teacher, hide protected tabs
                document.querySelector('[data-tab="accounts"]')?.classList.add('hidden');
                document.querySelector('[data-tab="users"]')?.classList.add('hidden');
                document.querySelector('[data-tab="teacher-assignment"]')?.classList.add('hidden');
                document.querySelector('[data-tab="settings"]')?.classList.add('hidden');
                
                if (!isTeacherLoggedIn) {
                    document.querySelector('[data-tab="questions"]')?.classList.add('hidden');
                    document.querySelector('[data-tab="exams"]')?.classList.add('hidden');
                    document.querySelector('[data-tab="ranking"]')?.classList.add('hidden');
                }
            }
            
            updateThemeForRole();
            applyDoiTuongConfig();
            updateSidebarVisibility();
        }

        function updateThemeForRole() {
            const body = document.body;
            const sidebar = document.getElementById('app-sidebar');
            const header = document.querySelector('header.sticky');
            const footer = document.querySelector('footer');

            body.classList.remove('bg-[#15803d]', 'bg-blue-900', 'bg-purple-900', 'bg-slate-900');

            if (sidebar) {
                sidebar.classList.remove(
                    'from-emerald-950', 'via-green-950', 'to-emerald-900', 'border-emerald-800/40',
                    'from-blue-950', 'via-indigo-950', 'to-blue-900', 'border-blue-800/40',
                    'from-purple-950', 'via-fuchsia-950', 'to-purple-900', 'border-purple-800/40',
                    'from-indigo-950', 'via-blue-950', 'to-indigo-900', 'border-indigo-800/40'
                );
            }

            if (header) {
                header.classList.remove(
                    'from-emerald-950', 'via-green-900', 'to-emerald-950', 'border-emerald-800/40',
                    'from-blue-950', 'via-slate-900', 'to-blue-900', 'border-blue-800/40',
                    'from-purple-950', 'via-slate-900', 'to-purple-900', 'border-purple-800/40',
                    'from-indigo-950', 'via-blue-950', 'to-indigo-900', 'border-indigo-800/40'
                );
            }

            if (footer) {
                footer.classList.remove(
                    'bg-slate-800', 'bg-emerald-950/80', 'bg-blue-950/80', 'bg-purple-950/80',
                    'border-slate-700/50', 'border-emerald-800/40', 'border-blue-800/40', 'border-purple-800/40', 'border-t'
                );
                footer.classList.add('bg-transparent');
            }

            if (isAdminLoggedIn) {
                body.classList.add('bg-purple-900');
                if (sidebar) sidebar.classList.add('from-purple-950', 'via-fuchsia-950', 'to-purple-900', 'border-purple-800/40');
                if (header) header.classList.add('from-purple-950', 'via-slate-900', 'to-purple-900', 'border-purple-800/40');
            } else if (isTeacherLoggedIn) {
                body.classList.add('bg-blue-900');
                if (sidebar) sidebar.classList.add('from-blue-950', 'via-indigo-950', 'to-blue-900', 'border-blue-800/40');
                if (header) header.classList.add('from-blue-950', 'via-slate-900', 'to-blue-900', 'border-blue-800/40');
            } else {
                body.classList.add('bg-[#15803d]');
                if (sidebar) sidebar.classList.add('from-emerald-950', 'via-green-950', 'to-emerald-900', 'border-emerald-800/40');
                if (header) header.classList.add('from-emerald-950', 'via-green-900', 'to-emerald-950', 'border-emerald-800/40');
            }
        }

        function updateSidebarVisibility() {
            // Xác định chính xác vai trò hiện tại
            const isAdmin = Boolean(isAdminLoggedIn);
            const isTeacher = Boolean(isTeacherLoggedIn) && !isAdmin;
            const isStudentOrGuest = !isAdmin && !isTeacher;

            document.querySelectorAll('[data-sidebar-tab]').forEach(btn => {
                const tab = btn.dataset.sidebarTab;
                let visible = false;

                if (tab === 'exam') {
                    // TAB LÀM BÀI: Chỉ hiển thị cho Học sinh / Khách. TUYỆT ĐỐI KHÔNG hiển thị cho Giáo viên và Admin
                    visible = isStudentOrGuest;
                } else if (tab === 'help') {
                    // Trợ giúp: Hiển thị cho tất cả
                    visible = true;
                } else if (tab === 'ranking') {
                    // QL Kết quả: Hiển thị cho Giáo viên và Admin (ẩn đối với Học sinh)
                    visible = isTeacher || isAdmin;
                } else if (tab === 'questions' || tab === 'exams') {
                    // QL Câu hỏi, QL Đề thi: Dành cho Giáo viên và Admin
                    visible = isTeacher || isAdmin;
                } else if (tab === 'users') {
                    // QL Người dùng: Dành cho Giáo viên (chế độ xem danh sách) và Admin
                    visible = isTeacher || isAdmin;
                } else if (tab === 'teacher-assignment' || tab === 'accounts' || tab === 'settings') {
                    // Phân công GV, QL Tài khoản, Cấu hình: TUYỆT ĐỐI chỉ Quản trị viên (Admin)
                    visible = isAdmin;
                }

                if (visible) {
                    btn.classList.remove('hidden');
                } else {
                    btn.classList.add('hidden');
                }
            });

            // Đồng bộ hiển thị các nhóm menu (Sidebar Groups)
            document.querySelectorAll('.sidebar-group').forEach(group => {
                const groupName = group.dataset.group;
                // Nhóm Hỗ trợ và Tiện ích luôn hiển thị
                if (groupName === 'utilities' || groupName === 'support') {
                    group.classList.remove('hidden');
                    return;
                }
                // Các nhóm danh mục khác chỉ hiển thị nếu có ít nhất 1 tab bên trong hiển thị
                const hasVisibleItem = Array.from(group.querySelectorAll('[data-sidebar-tab]')).some(b => !b.classList.contains('hidden'));
                if (hasVisibleItem) {
                    group.classList.remove('hidden');
                } else {
                    group.classList.add('hidden');
                }
            });

            // Cập nhật thông tin tài khoản hiển thị trên Header của Menu dọc
            const userNameEl = document.getElementById('sidebar-user-name');
            const userRoleEl = document.getElementById('sidebar-user-role');
            if (userNameEl && userRoleEl) {
                if (currentUser && (isAdmin || isTeacher)) {
                    userNameEl.textContent = currentUser.full_name || currentUser.ho_ten || currentUser.username || 'Tài khoản';
                    userRoleEl.textContent = isAdmin ? 'Quản trị viên (Admin)' : 'Giáo viên';
                } else if (currentUser && currentUser.target_audience === 'Học sinh') {
                    userNameEl.textContent = currentUser.full_name || currentUser.ho_ten || currentUser.username || 'Học sinh';
                    userRoleEl.textContent = 'Học sinh';
                } else {
                    userNameEl.textContent = 'Thí sinh / Khách';
                    userRoleEl.textContent = 'Thí sinh / Khách';
                }
            }
        }
        window.updateSidebarVisibility = updateSidebarVisibility;

        window.toggleSidebar = function toggleSidebar() {
            const sidebar = document.getElementById('app-sidebar');
            const icon = document.getElementById('sidebar-toggle-icon');
            if (!sidebar) return;

            if (window.innerWidth < 768) {
                window.toggleMobileSidebar();
                return;
            }

            sidebar.classList.toggle('collapsed');
            if (sidebar.classList.contains('collapsed')) {
                if (icon) icon.style.transform = 'rotate(180deg)';
            } else {
                if (icon) icon.style.transform = 'rotate(0deg)';
            }
        };

        window.toggleMobileSidebar = function toggleMobileSidebar() {
            const sidebar = document.getElementById('app-sidebar');
            const backdrop = document.getElementById('sidebar-backdrop');
            if (!sidebar) return;

            const isClosed = sidebar.classList.contains('-translate-x-full');
            if (isClosed) {
                sidebar.classList.remove('-translate-x-full');
                sidebar.classList.add('translate-x-0');
                if (backdrop) backdrop.classList.remove('hidden');
            } else {
                window.closeMobileSidebar();
            }
        };

        window.closeMobileSidebar = function closeMobileSidebar() {
            const sidebar = document.getElementById('app-sidebar');
            const backdrop = document.getElementById('sidebar-backdrop');
            if (sidebar && window.innerWidth < 768) {
                sidebar.classList.add('-translate-x-full');
                sidebar.classList.remove('translate-x-0');
            }
            if (backdrop) backdrop.classList.add('hidden');
        };

        window.adminLogout = adminLogout;
        async function adminLogout() {
            closeModal();
            localStorage.removeItem('auth_token');
            isAdminLoggedIn = false;
            isTeacherLoggedIn = false;
            currentUser = null;
            window.isAdminLoggedIn = false;
            window.isTeacherLoggedIn = false;
            window.currentUser = null;
            
            // Xóa sạch dữ liệu trong bộ nhớ để bảo mật tuyệt đối
            if (typeof questions !== 'undefined') questions.length = 0;
            if (typeof exams !== 'undefined') exams.length = 0;
            if (typeof results !== 'undefined') results.length = 0;
            if (typeof accounts !== 'undefined') accounts.length = 0;
            questionsLoaded = false;
            resultsLoaded = false;
            accountsLoaded = false;
            examsLoaded = false;
            
            // Xóa sạch các bản đồ ánh xạ metadata và phân quyền
            if (typeof examToCreatorMap !== 'undefined') {
                for (let key in examToCreatorMap) delete examToCreatorMap[key];
            }
            if (typeof examIdToCreatorMap !== 'undefined') {
                for (let key in examIdToCreatorMap) delete examIdToCreatorMap[key];
            }
            if (window.unlockedExamIds) window.unlockedExamIds.clear();
            if (window.examNameToIdMap) {
                for (let key in window.examNameToIdMap) delete window.examNameToIdMap[key];
            }
            if (window.examToSharedResultsMap) {
                for (let key in window.examToSharedResultsMap) delete window.examToSharedResultsMap[key];
            }

            // Xóa sạch các bộ lọc của người dùng cũ
            const elStudentTeacher = document.getElementById('student-teacher-filter');
            if (elStudentTeacher) elStudentTeacher.value = '';
            const examSelect = document.getElementById('student-exam-name-filter');
            if (examSelect) examSelect.innerHTML = '<option value="">Chọn Bộ Câu hỏi/Đề thi</option>';
            const examTeacherFilter = document.getElementById('exam-teacher-filter');
            if (examTeacherFilter) examTeacherFilter.value = '';
            const qLessonFilter = document.getElementById('question-lesson-filter');
            if (qLessonFilter) qLessonFilter.value = '';
            const qSearch = document.getElementById('question-search');
            if (qSearch) qSearch.value = '';

            // Xóa thông tin học sinh khi đăng xuất
            const nameInput = document.getElementById('guest_data_1');
            const lopInput = document.getElementById('guest_data_lop') || document.getElementById('guest_data_2');
            const donviInput = document.getElementById('guest_data_donvi');
            if (nameInput) {
                nameInput.value = '';
                nameInput.readOnly = false;
                nameInput.classList.remove('bg-gray-100', 'cursor-not-allowed');
            }
            if (lopInput) {
                lopInput.value = '';
                lopInput.readOnly = false;
                lopInput.classList.remove('bg-gray-100', 'cursor-not-allowed');
            }
            if (donviInput) {
                donviInput.value = '';
                donviInput.readOnly = false;
                donviInput.classList.remove('bg-gray-100', 'cursor-not-allowed');
            }

            // Revert background color & theme ngay lập tức
            updateThemeForRole();
            
            // Chỉ xóa cờ tự động đăng nhập khi người dùng chủ động đăng xuất
            localStorage.setItem('is_auto_login', 'false');
            
            // Ẩn auth status, hiện nút login
            document.getElementById('auth-status')?.classList.add('hidden');
            document.getElementById('login-btn')?.classList.remove('hidden');

            // Cập nhật thẻ người dùng ở menu dọc
            const userNameEl = document.getElementById('sidebar-user-name');
            const userRoleEl = document.getElementById('sidebar-user-role');
            if (userNameEl) userNameEl.textContent = 'Thí sinh / Khách';
            if (userRoleEl) userRoleEl.textContent = 'Thí sinh / Khách';
            
            // Show guest tabs (like exam)
            document.querySelector('[data-tab="exam"]')?.classList.remove('hidden');
            
            // Hide protected tabs
            document.querySelector('[data-tab="questions"]')?.classList.add('hidden');
            document.querySelector('[data-tab="exams"]')?.classList.add('hidden');
            document.querySelector('[data-tab="teacher-assignment"]')?.classList.add('hidden');
            document.querySelector('[data-tab="accounts"]')?.classList.add('hidden');
            document.querySelector('[data-tab="users"]')?.classList.add('hidden');
            document.querySelector('[data-tab="ranking"]')?.classList.add('hidden');
            document.querySelector('[data-tab="settings"]')?.classList.add('hidden');
            
            // Đóng các tab bảo mật
            if(document.getElementById('questions-panel')) document.getElementById('questions-panel').classList.add('hidden');
            if(document.getElementById('exams-panel')) document.getElementById('exams-panel').classList.add('hidden');
            if (document.getElementById('questions-login')) document.getElementById('questions-login').classList.remove('hidden');
            if (document.getElementById('exams-login')) document.getElementById('exams-login').classList.remove('hidden');
            
            // Cập nhật menu dọc và chuyển ngay về tab làm bài
            updateSidebarVisibility();
            switchTab('exam');
            applyDoiTuongConfig();

            // Nạp lại cấu hình đề thi cho thí sinh/khách vãng lai một cách êm ái
            await loadData();
            updateStudentTeacherFilter();
        }

        function initProtectedTabs() {
            // Nếu người dùng ở các tab bảo mật, mở chúng
            const currentActiveTab = document.querySelector('.tab-content.active');
            if (!currentActiveTab) return;
            
            if (currentActiveTab.id === 'tab-questions') {
                const p = document.getElementById('questions-panel');
                if (p && !p.classList.contains('hidden')) return;
            }
            if (currentActiveTab.id === 'tab-exams') {
                const p = document.getElementById('exams-panel');
                if (p && !p.classList.contains('hidden')) return;
            }
            if (currentActiveTab.id === 'tab-settings') {
                const p = document.getElementById('settings-panel');
                if (p && !p.classList.contains('hidden')) return;
            }
        }

        function requireAdminAuth(tabName) {
            const adminOnlyTabs = ['accounts', 'settings', 'teacher-assignment'];
            const isAuthorized = isAdminLoggedIn || (isTeacherLoggedIn && !adminOnlyTabs.includes(tabName));
            if (isAuthorized) {
                switchTab(tabName);
            } else {
                showAdminLoginModal();
                // Sau khi đăng nhập thành công, mở tab
                const checkLogin = setInterval(() => {
                    const isAuthorizedNow = isAdminLoggedIn || (isTeacherLoggedIn && !adminOnlyTabs.includes(tabName));
                    if (isAuthorizedNow) {
                        clearInterval(checkLogin);
                        switchTab(tabName);
                    }
                }, 500);
            }
        }

        async function openProtectedTab(tabName) {
            const loginEl = document.getElementById(`${tabName}-login`);
            const panelEl = document.getElementById(`${tabName}-panel`);
            
            if (loginEl) loginEl.classList.add('hidden');
            if (panelEl) panelEl.classList.remove('hidden');

            if (tabName === 'questions') {
                updateQuestionStats();
                renderQuestionsList();
                updateLessonFilter();
            } else if (tabName === 'exams') {
                await initExamPanel();
                // Check sufficiency when opening tab
                checkExamConfigSufficiency();
            } else if (tabName === 'settings') {
                loadSettings();
            } else if (tabName === 'accounts') {
                renderAccounts();
            } else if (tabName === 'users') {
                renderUsers();
            } else if (tabName === 'teacher-assignment') {
                if (typeof window.initTeacherAssignmentApp === 'function') {
                    window.initTeacherAssignmentApp();
                }
            }
        }

        // ==================== SETTINGS ====================

        window.updateFontSizeDisplay = function updateFontSizeDisplay(type, value) {
            console.log('updateFontSizeDisplay called');
            if (type === 'question') {
                const el = document.getElementById('display-question-font-size');
                if (el) el.textContent = `${value}px`;
                // Live preview
                document.querySelectorAll('.responsive-q-text').forEach(item => {
                    item.style.setProperty('--base-q-size', `${value}px`);
                });
            } else if (type === 'answer') {
                const el = document.getElementById('display-answer-font-size');
                if (el) el.textContent = `${value}px`;
                // Live preview
                document.querySelectorAll('.responsive-a-text').forEach(item => {
                    item.style.setProperty('--base-a-size', `${value}px`);
                });
            }
        }

        function loadSettings() {
            const settingsAppTitle = document.getElementById('settings-app-title');
            if (settingsAppTitle) settingsAppTitle.value = appSettings.appTitle || "HỆ THỐNG KIỂM TRA TRỰC TUYẾN";
            
            // Load Font Size
            const qSize = appSettings.questionFontSize || 24;
            const aSize = appSettings.answerFontSize || 20;
            
            const elQInput = document.getElementById('settings-question-font-size');
            const elQDisplay = document.getElementById('display-question-font-size');
            const elAInput = document.getElementById('settings-answer-font-size');
            const elADisplay = document.getElementById('display-answer-font-size');

            if (elQInput) elQInput.value = qSize;
            if (elQDisplay) elQDisplay.textContent = `${qSize}px`;
            
            if (elAInput) elAInput.value = aSize;
            if (elADisplay) elADisplay.textContent = `${aSize}px`;
            


            // Load AI Prompt
            const elAIPrompt = document.getElementById('settings-ai-prompt');
            if (elAIPrompt) elAIPrompt.value = appSettings.aiPrompt || DEFAULT_AI_PROMPT;

            // Load AI Appraise Prompt
            const elAIAppraisePrompt = document.getElementById('settings-ai-appraise-prompt');
            if (elAIAppraisePrompt) elAIAppraisePrompt.value = appSettings.aiAppraisePrompt || DEFAULT_AI_APPRAISE_PROMPT;

            // Load AI Grading Key
            const elAIGradingKey = document.getElementById('settings-ai-grading-key');
            if (elAIGradingKey) {
                elAIGradingKey.disabled = false;
                elAIGradingKey.value = appSettings.aiGradingKey || '';
            }

            // Load Display Mode
            const displayMode = appSettings.displayMode || 'single';
            const displayModeRadios = document.getElementsByName('settings-display-mode');
            for (let radio of displayModeRadios) {
                if (radio.value === displayMode) {
                    radio.checked = true;
                }
            }
            
            // Sync to student settings modal
            const stQInput = document.getElementById('student-settings-question-font-size');
            const stQDisplay = document.getElementById('student-display-question-font-size');
            const stAInput = document.getElementById('student-settings-answer-font-size');
            const stADisplay = document.getElementById('student-display-answer-font-size');
            
            if (stQInput) stQInput.value = qSize;
            if (stQDisplay) stQDisplay.textContent = `${qSize}px`;
            if (stAInput) stAInput.value = aSize;
            if (stADisplay) stADisplay.textContent = `${aSize}px`;
            
            const stModeRadios = document.getElementsByName('student-settings-display-mode');
            if (stModeRadios) {
                for (let radio of stModeRadios) {
                    if (radio.value === displayMode) {
                        radio.checked = true;
                    }
                }
            }
            
            // Load UI Config
            const appTitle = appSettings.appTitle || "HỆ THỐNG KIỂM TRA TRỰC TUYẾN";
            
            const elAppTitle = document.getElementById('app-title');
            
            if (elAppTitle) elAppTitle.textContent = appTitle;

            const elAppAuthor = document.getElementById('app-author');
            if (elAppAuthor) {
                let authorText = appSettings.authorInfo || "";
                if (!authorText || authorText.includes("Ban Quản Trị") || authorText.includes("Được tạo bởi") || authorText.includes("0935.078.895") || !authorText.includes("Hồ Hữu Thế")) {
                    authorText = "Phát triển bởi: Hồ Hữu Thế - 0935 078 895";
                    appSettings.authorInfo = authorText;
                }
                elAppAuthor.textContent = authorText;
            }
        }

        window.updateStudentSettings = function updateStudentSettings() {
            // First ensure modal elements exist to avoid classList errors on null elements
            const modal = document.getElementById('student-settings-modal');
            if (!modal) return;
            const qInput = document.getElementById('student-settings-question-font-size');
            const aInput = document.getElementById('student-settings-answer-font-size');
            if (!qInput || !aInput) return;

            const qSize = parseInt(qInput.value) || 24;
            const aSize = parseInt(aInput.value) || 20;
            
            let displayMode = 'single';
            const radios = document.getElementsByName('student-settings-display-mode');
            for (let r of radios) {
                if (r.checked) {
                    displayMode = r.value;
                    break;
                }
            }

            // Update live preview in modal
            const pQ = document.getElementById('student-preview-q-text');
            if (pQ) pQ.style.fontSize = `${qSize}px`;
            const pA = document.getElementById('student-preview-a-text');
            if (pA) pA.style.fontSize = `${aSize}px`;

            const qDisplay = document.getElementById('student-display-question-font-size');
            if (qDisplay) qDisplay.textContent = `${qSize}px`;
            const aDisplay = document.getElementById('student-display-answer-font-size');
            if (aDisplay) aDisplay.textContent = `${aSize}px`;
            
            // Immediate CSS variable update for live preview
            document.querySelectorAll('.responsive-q-text').forEach(el => {
                el.style.setProperty('--base-q-size', `${qSize}px`);
            });
            document.querySelectorAll('.responsive-a-text').forEach(el => {
                el.style.setProperty('--base-a-size', `${aSize}px`);
            });
            
            const modeChanged = appSettings.displayMode !== displayMode;
            
            appSettings.questionFontSize = qSize;
            appSettings.answerFontSize = aSize;
            appSettings.displayMode = displayMode;
            
            // Save to userPreferences
            let prefs = {};
            try {
                prefs = JSON.parse(localStorage.getItem('userPreferences')) || {};
            } catch (e) {}
            
            prefs.questionFontSize = qSize;
            prefs.answerFontSize = aSize;
            prefs.displayMode = displayMode;
            localStorage.setItem('userPreferences', JSON.stringify(prefs));
            
            if (currentExam && currentExam.questions && currentExam.questions.length > 0) {
                if (modeChanged) {
                    renderCurrentQuestion(false); 
                }
            }
        };

        window.resetStudentSettingsToDefault = function resetStudentSettingsToDefault() {
            const qInput = document.getElementById('student-settings-question-font-size');
            const aInput = document.getElementById('student-settings-answer-font-size');
            if (qInput) qInput.value = 24;
            if (aInput) aInput.value = 20;

            const radios = document.getElementsByName('student-settings-display-mode');
            for (let r of radios) {
                r.checked = (r.value === 'single');
            }

            updateStudentSettings();
            showToast('Đã khôi phục cài đặt hiển thị mặc định (24px / 20px / Từng câu).', 'success');
        };

        window.saveSettings = function saveSettings(showNotification = false) {
            console.log('saveSettings called, notification:', showNotification);
            
            // if showNotification is an event object, default to false for auto-saves
            if (typeof showNotification !== 'boolean') {
                showNotification = false;
            }
            
            const elTitle = document.getElementById('settings-app-title');
            if (elTitle) appSettings.appTitle = elTitle.value;
            
            const elQInput = document.getElementById('settings-question-font-size');
            const elAInput = document.getElementById('settings-answer-font-size');
            
            if (elQInput) appSettings.questionFontSize = parseInt(elQInput.value);
            if (elAInput) appSettings.answerFontSize = parseInt(elAInput.value);

            const elAIGradingKey = document.getElementById('settings-ai-grading-key');
            if (elAIGradingKey) {
                const val = elAIGradingKey.value.trim();
                if (val !== "••••••••••••••••") {
                    appSettings.aiGradingKey = val;
                }
            }
            
            const displayModeRadios = document.getElementsByName('settings-display-mode');
            for (let radio of displayModeRadios) {
                if (radio.checked) {
                    appSettings.displayMode = radio.value;
                    break;
                }
            }

            saveSettingsToDB();
            renderRanking();
            if (currentExam && currentExam.questions && currentExam.questions.length > 0) {
                renderCurrentQuestion();
            }
            
            if (showNotification) {
                showToast('✅ Cài đặt đã được lưu!', 'success');
            }
        }

        function updateAppTitle(title) {
            document.getElementById('app-title').innerText = title;
        }

        function saveAIPrompt() {
            const elAIPrompt = document.getElementById('settings-ai-prompt');
            if (elAIPrompt) {
                appSettings.aiPrompt = elAIPrompt.value;
                saveSettingsToDB();
                showToast('✅ Đã lưu Prompt AI mới!', 'success');
            }
        }

        window.togglePassword = function togglePassword(inputId, buttonEl) {
            const input = document.getElementById(inputId);
            const icon = buttonEl.querySelector('svg');
            if (!input || !icon) return;

            if (input.type === 'password' || input.style.webkitTextSecurity === 'disc') {
                input.type = 'text'; input.style.webkitTextSecurity = 'none';
                icon.innerHTML = `<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268-2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21" />`;
            } else {
                input.type = 'text'; input.style.webkitTextSecurity = 'disc';
                icon.innerHTML = `<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268-2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />`;
            }
        };

        window.saveAIGradingKey = function saveAIGradingKey() {
            const elAIGradingKey = document.getElementById('settings-ai-grading-key');
            if (elAIGradingKey) {
                const val = elAIGradingKey.value.trim();
                appSettings.aiGradingKey = val;
                saveSettingsToDB();
                const keys = val.split(/\s+/).filter(k => k.length > 5);
                if (keys.length > 1) {
                    showToast(`✅ Đã lưu danh sách ${keys.length} AI Grading Key vào cơ sở dữ liệu!`, 'success');
                } else if (keys.length === 1) {
                    showToast('✅ Đã lưu AI Grading Key vào cơ sở dữ liệu!', 'success');
                } else {
                    showToast('ℹ️ Đã xóa AI Grading Key.', 'success');
                }
            }
        };

