        let questionsLoaded = false;

        function checkExamQuestionsAvailability(examConfig, getCount) {
            let isEnough = true;
            const checkType = (type, count, nb, th, vd) => {
                const sum = (nb || 0) + (th || 0) + (vd || 0);
                if (sum > 0) {
                    if (getCount(type, 'NB') < (nb || 0)) isEnough = false;
                    if (getCount(type, 'TH') < (th || 0)) isEnough = false;
                    if (getCount(type, 'VD') < (vd || 0)) isEnough = false;
                } else if ((count || 0) > 0) {
                    const totalAvailable = getCount(type, 'NB') + getCount(type, 'TH') + getCount(type, 'VD');
                    if (totalAvailable < count) isEnough = false;
                }
            };
            checkType('4-1', examConfig.count41, examConfig.count41NB, examConfig.count41TH, examConfig.count41VD);
            checkType('TF4', examConfig.countTF4, examConfig.countTF4NB, examConfig.countTF4TH, examConfig.countTF4VD);
            checkType('SQ', examConfig.countSQ, examConfig.countSQNB, examConfig.countSQTH, examConfig.countSQVD);
            checkType('TL', examConfig.countTL, examConfig.countTLNB, examConfig.countTLTH, examConfig.countTLVD);
            return isEnough;
        }

