        // ==================== TAB NAVIGATION ====================
        window.switchTab = switchTab;
        function switchTab(tabName) {
            console.log('switchTab called:', tabName);
            
            const tabExam = document.getElementById('tab-exam');
            const examInterface = document.getElementById('exam-interface');
            const questionNav = document.getElementById('question-nav');
            const examForm = document.getElementById('exam-form');
            const examResults = document.getElementById('exam-results');
            
            // Kiểm tra trạng thái đang làm bài: 
            // 1. Dựa vào class hidden của giao diện thi
            // 2. Dựa vào biến currentExam đã khởi tạo (có câu hỏi và có thời gian bắt đầu)
            const isExamVisible = examInterface && !examInterface.classList.contains('hidden');
            const isExamStateActive = currentExam && currentExam.questions && currentExam.questions.length > 0 && currentExam.startTime;
            let isExamInProgress = isExamVisible || isExamStateActive;

            const isShowingResults = examResults && !examResults.classList.contains('hidden');

            // TRƯỜNG HỢP: Đang trong quá trình làm bài và bấm sang tab khác (Quản lý, Thống kê, Trợ giúp...)
            if (tabName !== 'exam' && isExamInProgress && !isShowingResults) {
                showConfirmModal('Bạn đang trong quá trình làm bài thi. Nếu chuyển sang tab khác, bài làm của bạn sẽ bị hủy. Bạn có chắc chắn muốn chuyển không?', () => {
                    resetExam();
                    switchTab(tabName);
                });
                return;
            }

            // TRƯỜNG HỢP: Quay lại tab Làm bài
            if (tabName === 'exam') {
                // Nếu đang hiển thị kết quả hoặc bài thi đã bị hủy/chưa bắt đầu
                if (isShowingResults || !isExamInProgress) {
                    resetExam();
                    
                    const elTeacher = document.getElementById('student-teacher-filter');
                    if (elTeacher) {
                        elTeacher.value = ''; // Luôn trả về giá trị mặc định
                        if (elTeacher.options.length <= 1) {
                            try { updateStudentTeacherFilter(); } catch(e) {}
                        }
                        const examSelect = document.getElementById('student-exam-name-filter');
                        if (examSelect) examSelect.innerHTML = '<option value="">Chọn Bộ Câu hỏi/Đề thi</option>';
                        questions = [];
                        questionsLoaded = false; 
                    }
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                } else {
                    // Nếu vẫn còn trong trạng thái đang thi, đảm bảo giao diện thi hiển thị
                    if (examInterface) examInterface.classList.remove('hidden');
                    if (examForm) examForm.classList.add('hidden');
                    if (examResults) examResults.classList.add('hidden');
                    
                    // CUỘN TỚI BẢNG ĐIỀU HƯỚNG (Cho nút Bảng C/H hoạt động)
                    if (questionNav) {
                        setTimeout(() => {
                            questionNav.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        }, 100);
                    }
                }
                updateCurrentExamInfo();
                
                // Vì tab này đặc biệt (có thể cuộn thay vì chuyển tab hẳn hoi nếu đang thi)
                // Ta vẫn cần thực hiện active nút tab và tab-content bên dưới
            }

            // Tuyệt đối không cho phép Giáo viên hoặc Admin truy cập tab Làm bài thi (exam)
            if (tabName === 'exam' && (isAdminLoggedIn || isTeacherLoggedIn)) {
                tabName = 'exams';
            }

            // Các tab bảo mật
            const protectedTabs = ['questions', 'exams', 'accounts', 'users', 'settings', 'ranking', 'teacher-assignment'];
            
            // Nếu là tab bảo mật và chưa đăng nhập, yêu cầu xác thực
            if (protectedTabs.includes(tabName)) {
                // Các tab chỉ dành riêng cho Admin: accounts, settings, teacher-assignment
                const adminOnlyTabs = ['accounts', 'settings', 'teacher-assignment'];
                const isAuthorized = isAdminLoggedIn || (isTeacherLoggedIn && !adminOnlyTabs.includes(tabName));
                
                if (!isAuthorized) {
                    requireAdminAuth(tabName);
                    return;
                } else {
                    // Nếu đã đăng nhập, đảm bảo nội dung tab được hiển thị đúng
                    openProtectedTab(tabName);
                }
            }

            document.querySelectorAll('.tab-content').forEach(tab => tab.classList.remove('active'));
            document.querySelectorAll('.tab-btn').forEach(btn => {
                btn.classList.remove('active', 'bg-emerald-500', 'bg-emerald-400');
                btn.classList.add('bg-emerald-800/40', 'text-emerald-50');
            });

            // Cập nhật trạng thái Active trên Menu dọc (Vertical Sidebar) mà không làm mất class hidden
            document.querySelectorAll('[data-sidebar-tab]').forEach(btn => {
                const tab = btn.dataset.sidebarTab;
                if (tab === tabName) {
                    btn.classList.add('font-black', 'text-indigo-950', 'bg-white', 'shadow-sm', 'scale-[1.01]');
                    btn.classList.remove('font-bold', 'text-white/95', 'hover:bg-white/10', 'hover:text-white');
                } else {
                    btn.classList.remove('font-black', 'text-indigo-950', 'bg-white', 'shadow-sm', 'scale-[1.01]');
                    btn.classList.add('font-bold', 'text-white/95', 'hover:bg-white/10', 'hover:text-white');
                }
            });

            // Luôn đảm bảo phân quyền hiển thị chính xác 100% các tab cho từng đối tượng
            updateSidebarVisibility();

            const tabEl = document.getElementById(`tab-${tabName}`);
            if (tabEl) tabEl.classList.add('active');
            
            // Cập nhật trạng thái backend khi vào tab cài đặt
            if (tabName === 'settings' && typeof window.updateBackendStatusUI === 'function') {
                window.updateBackendStatusUI();
            }
            
            // Cập nhật danh sách đề thi khi chuyển sang tab exams
            if (tabName === 'exams') {
                if (!examsLoaded) {
                    updateExamNamesList();
                }
            }

            if (tabName === 'questions' || tabName === 'exams') {
                if (!questionsLoaded) {
                    showLoadingProgress('Đang tải Ngân hàng Câu hỏi', async () => {
                        await loadQuestions();
                        if (tabName === 'questions') {
                            updateQuestionStats();
                            renderQuestionsList();
                            updateLessonFilter();
                        } else if (tabName === 'exams') {
                            await initExamPanel();
                            checkExamConfigSufficiency();
                        }
                    });
                }
            }

            if (tabName === 'ranking') {
                let loadPromise = null;
                if (isAdminLoggedIn && Object.keys(examToCreatorMap).length === 0) {
                    // Tải danh sách đề thi để định vị người tạo & phục vụ bộ lọc
                    loadPromise = (async () => {
                        try {
                            const token = localStorage.getItem('auth_token') || '';
                            const res = await fetch('/api/exams', { headers: { 'Authorization': 'Bearer ' + token } });
                            let resJson;
const contentType = res.headers.get("content-type");
if (contentType && contentType.includes("application/json")) {
    resJson = await res.json();
} else {
    throw new Error("Server returned non-JSON response (likely 502/504 during restart). Status: " + res.status);
}
                            const data = resJson.data;
                            if (data) {
                                data.forEach(e => {
                                    if (e.name) {
                                        if (e.creator_id) {
                                            examToCreatorMap[e.name] = e.creator_id;
                                            if (e.id) {
                                                examIdToCreatorMap[String(e.id)] = e.creator_id;
                                            }
                                        }
                                        if (e.id) {
                                            window.examNameToIdMap[e.name] = e.id;
                                        }
                                        window.examToSharedResultsMap[e.name] = (e.is_shared_results === true || e.is_shared_results === 1 || e.is_shared_results === 'true');
                                    }
                                });
                                populateRankingExamFilter();
                            }
                        } catch (e) {
                            console.error('Error fetching exam configs for ranking:', e);
                        }
                    })();
                }
                
                if (!resultsLoaded) {
                    showLoadingProgress('Đang tải Danh sách Thống kê & Kết quả', async () => {
                        if (loadPromise) await loadPromise;
                        await loadAllResults();
                        renderRanking();
                    });
                } else {
                    if (loadPromise) {
                        loadPromise.then(() => {
                            renderRanking();
                        });
                    } else {
                        renderRanking();
                    }
                }
                renderRanking();
                const btnDelete = document.getElementById('btn-delete-selected-ranking');
                if (btnDelete) {
                    if (appSettings.showDeleteSelectedRanking && selectedRankingResults.size > 0) {
                        btnDelete.classList.remove('hidden');
                    } else {
                        btnDelete.classList.add('hidden');
                    }
                }
            }

            if (tabName === 'accounts') {
                if ((isAdminLoggedIn || isTeacherLoggedIn) && !accountsLoaded) {
                    showLoadingProgress('Đang tải danh sách Tài khoản', async () => {
                        await renderAccounts();
                    });
                } else {
                    renderAccounts();
                }
            }

            if (tabName === 'users') {
                if ((isAdminLoggedIn || isTeacherLoggedIn) && !usersLoaded) {
                    showLoadingProgress('Đang tải danh sách Người dùng', async () => {
                        await renderUsers();
                    });
                } else {
                    renderUsers();
                }
            }


            const activeBtn = document.querySelector(`.tab-btn[data-tab="${tabName}"]`);
            if (activeBtn) {
                activeBtn.classList.add('active');
                activeBtn.classList.remove('bg-emerald-800/40', 'text-emerald-50');
            }
            if (tabName === 'exams') {
                // Khởi tạo exam panel khi chuyển sang tab
                setTimeout(() => {
                    initExamPanel();
                    checkExamConfigSufficiency();
                }, 100);
            }
            if (tabName === 'ranking') {
                populateRankingFilters();
            }
        }

        function populateRankingFilters() {
            populateRankingExamFilter();
            populateRankingUnitFilter();
            populateRankingClassFilter();
        }

        function populateRankingExamFilter() {
            const select = document.getElementById('ranking-exam-filter');
            if (!select) return;
            
            const currentSelection = select.value;
            
            // QUY TẮC SỐNG CÒN: Chỉ load các đề của mình tạo HOẶC các đề được chia sẻ kết quả (is_shared_results = true)
            const isAdmin = isAdminLoggedIn;
            const isTeacher = isTeacherLoggedIn && !isAdmin;

            let examNames = [];
            
            if (isAdmin) {
                examNames = Object.keys(examToCreatorMap);
            } else if (isTeacher && currentUser) {
                // Lọc theo creator_id hoặc status is_unlocked
                examNames = Object.keys(examToCreatorMap).filter(name => {
                    const examId = window.examNameToIdMap && window.examNameToIdMap[name];
                    const isCreator = String(examIdToCreatorMap[String(examId)] || examToCreatorMap[name] || '') === String(currentUser.id);
                    const isUnlocked = examId && window.unlockedExamIds && window.unlockedExamIds.has(String(examId));
                    return isCreator || isUnlocked;
                });
            } else {
                examNames = [...new Set(results.map(r => r.examName))].filter(Boolean);
            }
            
            // Bổ sung đề thi từ kết quả hiện có (vẫn tuân thủ quy tắc sống còn)
            let availableResults = [...results];
            if (isTeacher && currentUser) {
                availableResults = availableResults.filter(r => {
                    const isCreator = String(examToCreatorMap[r.examName]) === String(currentUser.id);
                    const isUnlocked = r.examId && window.unlockedExamIds && window.unlockedExamIds.has(String(r.examId));
                    return isCreator || isUnlocked;
                });
            }
            const resultExamNames = [...new Set(availableResults.map(r => r.examName))].filter(Boolean);
            examNames = [...new Set([...examNames, ...resultExamNames])].sort();
            
            // Only update if the number of options (excluding default) has changed
            // or if the select is empty
            if (select.options.length === examNames.length + 1) {
                // Check if names are the same
                let same = true;
                for (let i = 0; i < examNames.length; i++) {
                    if (select.options[i+1].value !== examNames[i]) {
                        same = false;
                        break;
                    }
                }
                if (same) return;
            }

            select.innerHTML = '<option value="">-- Tất cả đề thi --</option>';
            examNames.forEach(name => {
                const option = document.createElement('option');
                option.value = name;
                option.textContent = name;
                if (name === currentSelection) option.selected = true;
                select.appendChild(option);
            });
        }

        function populateRankingUnitFilter() {
            const select = document.getElementById('ranking-unit-filter');
            if (!select) return;

            const isAdmin = isAdminLoggedIn;
            const isTeacher = isTeacherLoggedIn && !isAdmin;

            if (isTeacher && currentUser && currentUser.donvi) {
                const teacherDonvi = currentUser.donvi.trim();
                select.innerHTML = `<option value="${teacherDonvi}">${teacherDonvi}</option>`;
                select.value = teacherDonvi;
                select.disabled = true;
                return;
            }

            select.disabled = false;
            const currentSelection = select.value;

            const units = new Set();
            results.forEach(r => {
                const u = (r.donvi || r.studentClass || '').trim();
                if (u) units.add(u);
            });
            if (window.usersList && Array.isArray(window.usersList)) {
                window.usersList.forEach(u => {
                    const val = (u.donvi || u.address || '').trim();
                    if (val) units.add(val);
                });
            }

            const sortedUnits = Array.from(units).filter(Boolean).sort();
            if (select.options.length === sortedUnits.length + 1) {
                let same = true;
                for (let i = 0; i < sortedUnits.length; i++) {
                    if (select.options[i+1].value !== sortedUnits[i]) {
                        same = false;
                        break;
                    }
                }
                if (same) return;
            }

            select.innerHTML = '<option value="">-- Tất cả đơn vị --</option>';
            sortedUnits.forEach(u => {
                const option = document.createElement('option');
                option.value = u;
                option.textContent = u;
                if (u === currentSelection) option.selected = true;
                select.appendChild(option);
            });
        }

        async function populateRankingClassFilter() {
            const select = document.getElementById('ranking-class-filter');
            if (!select) return;
            const currentSelection = select.value;

            const token = localStorage.getItem('auth_token') || '';
            const isAdmin = isAdminLoggedIn;
            const isTeacher = isTeacherLoggedIn && !isAdmin;

            if (token && (!window.usersList || window.usersList.length === 0) && !window.usersListLoading) {
                window.usersListLoading = true;
                try {
                    const res = await fetch('/api/users', {
                        headers: { 'Authorization': 'Bearer ' + token }
                    });
                    if (res.ok) {
                        const resJson = await res.json();
                        if (resJson && Array.isArray(resJson.data)) {
                            window.usersList = resJson.data;
                        }
                    }
                } catch (e) {
                    console.error("Failed to fetch users list for class filter:", e);
                } finally {
                    window.usersListLoading = false;
                }
            }

            // Tải danh sách cấu hình đề thi nếu chưa có để lọc chính xác lớp đã cấu hình cho đề thi
            if (token && (!window.allExamConfigsList || window.allExamConfigsList.length === 0) && !window.allExamConfigsListLoading) {
                window.allExamConfigsListLoading = true;
                try {
                    const res = await fetch('/api/exams', {
                        headers: { 'Authorization': 'Bearer ' + token }
                    });
                    if (res.ok) {
                        const resJson = await res.json();
                        if (resJson && Array.isArray(resJson.data)) {
                            window.allExamConfigsList = resJson.data;
                        }
                    }
                } catch (e) {
                    console.error("Failed to fetch exam configs for class filter:", e);
                } finally {
                    window.allExamConfigsListLoading = false;
                }
            }

            const unitFilterEl = document.getElementById('ranking-unit-filter');
            const selectedUnit = unitFilterEl ? (unitFilterEl.value || '').trim().toLowerCase() : '';

            const examFilterEl = document.getElementById('ranking-exam-filter');
            const selectedExam = examFilterEl ? (examFilterEl.value || '').trim() : '';

            // Tải danh sách phân công lớp của giáo viên nếu chưa có
            if (isTeacher && token && currentUser && (!currentUser.assigned_classes || !Array.isArray(currentUser.assigned_classes) || currentUser.assigned_classes.length === 0)) {
                try {
                    const teacherId = currentUser.user_id || currentUser.id || '';
                    const res = await fetch(`/api/teacher-classes?teacher_id=${encodeURIComponent(teacherId)}`, {
                        headers: { 'Authorization': 'Bearer ' + token }
                    });
                    if (res.ok) {
                        const resJson = await res.json();
                        if (resJson && Array.isArray(resJson.data)) {
                            currentUser.assigned_classes = resJson.data;
                        }
                    }
                } catch (e) {
                    console.error("Lỗi khi tải danh sách phân công lớp cho giáo viên:", e);
                }
            }

            // Lấy danh sách lớp được phân công cho giáo viên (nếu là giáo viên)
            const teacherClassSet = new Set();
            if (isTeacher) {
                if (currentUser && Array.isArray(currentUser.assigned_classes)) {
                    currentUser.assigned_classes.forEach(ac => {
                        const clsName = String(ac.class_name || ac.lop || ac || '').trim();
                        if (clsName) teacherClassSet.add(clsName);
                    });
                }
                if (teacherClassSet.size === 0 && window.usersList && Array.isArray(window.usersList) && currentUser) {
                    const teacherId = currentUser.user_id || currentUser.id;
                    const foundMe = window.usersList.find(u => u.id === teacherId || u.user_id === teacherId || u.username === currentUser.username);
                    if (foundMe && Array.isArray(foundMe.assigned_classes)) {
                        foundMe.assigned_classes.forEach(ac => {
                            const clsName = String(ac.class_name || ac.lop || ac || '').trim();
                            if (clsName) teacherClassSet.add(clsName);
                        });
                    }
                }
                if (teacherClassSet.size === 0 && window.taState && Array.isArray(window.taState.assignments) && currentUser) {
                    const teacherId = currentUser.user_id || currentUser.id;
                    window.taState.assignments.forEach(a => {
                        if (String(a.teacher_id) === String(teacherId) && a.class_name) {
                            teacherClassSet.add(String(a.class_name).trim());
                        }
                    });
                }
            }

            const classes = new Set();

            if (selectedExam) {
                // KHI CHỌN ĐỀ THI: Chỉ hiển thị danh sách các lớp đã được cấu hình cho đề thi đó
                let targetExam = (window.allExamConfigsList || []).find(e => 
                    String(e.name || '').trim() === selectedExam ||
                    String(e.id || '').trim() === selectedExam ||
                    (window.examNameToIdMap && String(e.id) === String(window.examNameToIdMap[selectedExam]))
                );

                const targetLopRaw = String(targetExam?.target_lop || targetExam?.targetLop || targetExam?.lop || '').trim();
                const examConfiguredClasses = targetLopRaw
                    ? targetLopRaw.split(/[,;\n]+/).map(s => s.trim()).filter(Boolean)
                    : [];

                if (examConfiguredClasses.length > 0) {
                    // Đề thi có cấu hình lớp cụ thể
                    examConfiguredClasses.forEach(c => {
                        if (!isTeacher || teacherClassSet.size === 0 || teacherClassSet.has(c)) {
                            classes.add(c);
                        }
                    });
                } else {
                    // Nếu đề thi không cấu hình danh sách lớp cụ thể (ví dụ đề công khai), lấy các lớp từ kết quả nộp bài của đề này
                    const examResults = results.filter(r => 
                        String(r.examName || '').trim() === selectedExam || 
                        String(r.examId || '').trim() === selectedExam ||
                        (window.examNameToIdMap && String(r.examId) === String(window.examNameToIdMap[selectedExam]))
                    );
                    examResults.forEach(r => {
                        const u = (r.donvi || r.studentClass || '').trim().toLowerCase();
                        const c = (r.lop || '').trim();
                        if (c) {
                            if (!selectedUnit || u === selectedUnit) {
                                if (!isTeacher || teacherClassSet.size === 0 || teacherClassSet.has(c)) {
                                    classes.add(c);
                                }
                            }
                        }
                    });

                    // Nếu vẫn không có lớp nào trong kết quả nộp bài, hiển thị lớp được phân công của giáo viên (hoặc tất cả nếu admin)
                    if (classes.size === 0) {
                        if (isTeacher) {
                            teacherClassSet.forEach(c => classes.add(c));
                        } else {
                            results.forEach(r => {
                                const u = (r.donvi || r.studentClass || '').trim().toLowerCase();
                                const c = (r.lop || '').trim();
                                if (c && (!selectedUnit || u === selectedUnit)) classes.add(c);
                            });
                        }
                    }
                }
            } else {
                // KHI KHÔNG CHỌN ĐỀ THI:
                if (isTeacher) {
                    // Giáo viên: Hiển thị toàn bộ các lớp được phân công
                    teacherClassSet.forEach(c => classes.add(c));
                } else {
                    // Admin: Hiển thị tất cả các lớp trong toàn hệ thống
                    results.forEach(r => {
                        const u = (r.donvi || r.studentClass || '').trim().toLowerCase();
                        const c = (r.lop || '').trim();
                        if (selectedUnit) {
                            if (u === selectedUnit && c) classes.add(c);
                        } else {
                            if (c) classes.add(c);
                        }
                    });
                    if (window.usersList && Array.isArray(window.usersList)) {
                        window.usersList.forEach(u => {
                            const userUnit = (u.donvi || u.address || '').trim().toLowerCase();
                            const val = (u.lop || '').trim();
                            if (selectedUnit) {
                                if (userUnit === selectedUnit && val) classes.add(val);
                            } else {
                                if (val) classes.add(val);
                            }
                        });
                    }
                    if (window.appSettings && Array.isArray(window.appSettings.class_names)) {
                        window.appSettings.class_names.forEach(c => {
                            if (c && String(c).trim()) classes.add(String(c).trim());
                        });
                    }
                    if (window.taState && Array.isArray(window.taState.classes)) {
                        window.taState.classes.forEach(c => {
                            if (c && String(c).trim()) classes.add(String(c).trim());
                        });
                    }
                }
            }

            const sortedClasses = Array.from(classes).filter(Boolean).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
            if (select.options.length === sortedClasses.length + 1) {
                let same = true;
                for (let i = 0; i < sortedClasses.length; i++) {
                    if (select.options[i+1].value !== sortedClasses[i]) {
                        same = false;
                        break;
                    }
                }
                if (same) return;
            }

            select.innerHTML = '<option value="">-- Tất cả lớp --</option>';
            sortedClasses.forEach(c => {
                const option = document.createElement('option');
                option.value = c;
                option.textContent = c;
                if (c === currentSelection) option.selected = true;
                select.appendChild(option);
            });
        }

        // ==================== TOAST NOTIFICATIONS ====================
        const _recentToasts = new Map();

        function showToast(message, type = 'info', size = 'small') {
            if (!message || typeof message !== 'string') return;
            const trimmedMsg = message.trim();
            if (!trimmedMsg) return;

            // BỘ LỌC THÔNG MINH: Bỏ bớt các thông báo không cần thiết, giảm phiền toái cho người dùng
            // Chỉ giữ lại các thông báo thành công (success), thất bại (error) và cảnh báo quan trọng (warning)
            const lower = trimmedMsg.toLowerCase();
            const isUnnecessaryInfo = type === 'info' && (
                lower.includes('đang tải') ||
                lower.includes('đang tìm') ||
                lower.includes('đang nén') ||
                lower.includes('đang nạp') ||
                lower.includes('đang khởi tạo') ||
                lower.includes('đang xóa') ||
                lower.includes('đang tạo') ||
                lower.includes('đang tiến hành') ||
                lower.includes('đang đọc dữ liệu') ||
                lower.includes('đã hủy bỏ') ||
                lower.includes('đã chuyển sang') ||
                lower.includes('đã đặt lại') ||
                lower.includes('không có thay đổi') ||
                lower.includes('đã chọn toàn bộ')
            );
            if (isUnnecessaryInfo) {
                console.log('🔇 [Muted Toast Info]:', trimmedMsg);
                return;
            }

            // Chống spam thông báo trùng lặp liên tục trong vòng 2 giây
            const now = Date.now();
            const lastShown = _recentToasts.get(trimmedMsg);
            if (lastShown && (now - lastShown < 2000)) {
                return;
            }
            _recentToasts.set(trimmedMsg, now);
            if (_recentToasts.size > 50) {
                for (const [k, v] of _recentToasts.entries()) {
                    if (now - v > 5000) _recentToasts.delete(k);
                }
            }

            const containerId = size === 'large' ? 'toast-container-center' : 'toast-container-right';
            let container = document.getElementById(containerId);
            if (!container) {
                container = document.createElement('div');
                container.id = containerId;
                container.className = size === 'large'
                    ? 'fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[9999999] pointer-events-none'
                    : 'fixed top-4 right-4 z-[9999999] flex flex-col gap-2 max-w-sm pointer-events-none';
                (document.body || document.documentElement).appendChild(container);
            }
            const toast = document.createElement('div');
            const bgColor = {
                'success': 'bg-emerald-600 border border-emerald-500/50',
                'error': 'bg-red-600 border border-red-500/50',
                'warning': 'bg-amber-500 border border-amber-400/50',
                'info': 'bg-sky-600 border border-sky-500/50'
            }[type] || 'bg-sky-600 border border-sky-500/50';

            const sizeClasses = size === 'large' 
                ? 'px-[72px] py-[36px] rounded-2xl shadow-2xl font-bold text-5xl' 
                : 'px-5 py-3 rounded-xl shadow-xl font-semibold text-sm flex items-center justify-between gap-3 backdrop-blur-xs transition-all duration-300';

            if (size === 'large') {
                toast.className = `toast ${sizeClasses} ${bgColor} text-white pointer-events-auto`;
                toast.textContent = trimmedMsg;
            } else {
                toast.className = `toast ${sizeClasses} ${bgColor} text-white pointer-events-auto group relative`;
                
                const textSpan = document.createElement('span');
                textSpan.textContent = trimmedMsg;
                textSpan.className = 'flex-1 break-words max-w-[300px] leading-snug';
                toast.appendChild(textSpan);

                const copyBtn = document.createElement('button');
                copyBtn.innerHTML = `<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"></path></svg>`;
                copyBtn.className = "hover:text-white/80 focus:outline-none flex-shrink-0 cursor-pointer p-1 rounded hover:bg-white/20 transition";
                copyBtn.title = "Sao chép thông báo";
                copyBtn.onclick = () => {
                    navigator.clipboard.writeText(trimmedMsg);
                    const originalHtml = copyBtn.innerHTML;
                    copyBtn.innerHTML = `<svg class="w-4 h-4 text-emerald-200" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg>`;
                    setTimeout(() => { copyBtn.innerHTML = originalHtml; }, 1500);
                };
                toast.appendChild(copyBtn);
            }
            
            container.appendChild(toast);

            let timeoutId;
            const startTimer = () => {
                timeoutId = setTimeout(() => {
                    toast.style.opacity = '0';
                    toast.style.transform = 'translateY(-6px)';
                    toast.style.transition = 'opacity 0.25s, transform 0.25s';
                    setTimeout(() => toast.remove(), 260);
                }, size === 'large' ? 3000 : 4000);
            };

            const clearTimer = () => {
                clearTimeout(timeoutId);
            };

            if (size !== 'large') {
                toast.addEventListener('mouseenter', clearTimer);
                toast.addEventListener('mouseleave', startTimer);
            }

            startTimer();
        }

        let audioCtx = null;
        async function playFeedbackSound(isCorrect) {
            const immediateFeedbackOn = examConfig.immediateFeedback !== undefined ? examConfig.immediateFeedback : appSettings.immediateFeedback;
            if (!immediateFeedbackOn) return;
            
            try {
                if (!audioCtx) {
                    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                }
                
                if (audioCtx.state === 'suspended') {
                    await audioCtx.resume();
                }

                const oscillator = audioCtx.createOscillator();
                const gainNode = audioCtx.createGain();
                
                oscillator.connect(gainNode);
                gainNode.connect(audioCtx.destination);
                
                const now = audioCtx.currentTime;
                
                if (isCorrect) {
                    // Success chime
                    oscillator.type = 'sine';
                    oscillator.frequency.setValueAtTime(523.25, now); // C5
                    oscillator.frequency.setValueAtTime(659.25, now + 0.1); // E5
                    
                    gainNode.gain.setValueAtTime(0, now);
                    gainNode.gain.linearRampToValueAtTime(0.5, now + 0.05);
                    gainNode.gain.linearRampToValueAtTime(0, now + 0.3);
                    
                    oscillator.start(now);
                    oscillator.stop(now + 0.3);
                } else {
                    // Error buzz
                    oscillator.type = 'triangle';
                    oscillator.frequency.setValueAtTime(200, now);
                    oscillator.frequency.exponentialRampToValueAtTime(100, now + 0.2);
                    
                    gainNode.gain.setValueAtTime(0, now);
                    gainNode.gain.linearRampToValueAtTime(0.5, now + 0.05);
                    gainNode.gain.linearRampToValueAtTime(0, now + 0.3);
                    
                    oscillator.start(now);
                    oscillator.stop(now + 0.3);
                }
            } catch (e) {
                console.error('Web Audio API error:', e);
            }
        }

        // ==================== MODAL SYSTEM ====================
        function ensureModalElements() {
            // Tìm tất cả các phần tử có id modal-container (phòng trường hợp trùng do restore HTML)
            const allContainers = document.querySelectorAll('#modal-container');
            let container = allContainers.length > 0 ? allContainers[0] : null;
            
            // Nếu có nhiều hơn 1 container, dọn dẹp các container thừa
            if (allContainers.length > 1) {
                for (let i = 1; i < allContainers.length; i++) {
                    allContainers[i].remove();
                }
            }

            const activeFullscreen = document.fullscreenElement;
            const properParent = activeFullscreen || document.body;

            if (!container) {
                container = document.createElement('div');
                container.id = 'modal-container';
                container.className = 'fixed inset-0 z-[999999] hidden flex items-center justify-center bg-black/60 backdrop-blur-sm p-2 sm:p-4';
                container.innerHTML = `
                    <div class="modal-overlay absolute inset-0" onclick="closeModal()"></div>
                    <div id="modal-content" class="bg-white rounded-2xl sm:rounded-3xl shadow-2xl w-full max-w-2xl max-h-[92vh] sm:max-h-[90vh] overflow-y-auto relative animate-modal-enter z-10"></div>
                `;
                properParent.appendChild(container);
            } else {
                // Kiểm tra xem container có đang bị nhốt trong một phần tử cha bị ẩn (như #exam-interface đang hidden) hoặc sai cha không
                const isInsideHiddenParent = container.closest('.hidden') !== null && container.closest('.hidden') !== container;
                if (isInsideHiddenParent || container.parentElement !== properParent) {
                    properParent.appendChild(container);
                }
                // Đảm bảo z-index cao nhất
                container.style.zIndex = '999999';
            }

            let el = document.getElementById('modal-content');
            if (!el) {
                el = document.createElement('div');
                el.id = 'modal-content';
                el.className = 'bg-white rounded-2xl sm:rounded-3xl shadow-2xl w-full max-w-2xl max-h-[92vh] sm:max-h-[90vh] overflow-y-auto relative animate-modal-enter z-10';
                container.appendChild(el);
            }
            return { container, el };
        }

        function showModal(content, fullScreen = false, alwaysScrollbar = false) {
            const { container, el } = ensureModalElements();
            if (!el || !container) {
                console.error('Critical Error: modal-content element could not be created or found.');
                return;
            }
            // Reset custom style overrides if any
            el.style.width = '';
            el.style.backgroundColor = '';
            el.classList.remove('always-scrollbar-y');
            
            el.innerHTML = content;
            
            // Tự động thêm nút đóng icon X ở góc trên bên phải modal
            const closeBtn = document.createElement('button');
            closeBtn.onclick = closeModal;
            closeBtn.className = 'absolute top-4 right-4 z-55 text-gray-400 hover:text-gray-700 hover:bg-gray-100 p-1.5 rounded-full transition bg-white/60 backdrop-blur-sm shadow-sm';
            closeBtn.title = 'Đóng';
            closeBtn.innerHTML = `
                <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
                </svg>
            `;
            el.style.position = 'relative';
            el.appendChild(closeBtn);

            // Reset size classes
            el.classList.remove(
                'max-w-2xl', 'max-w-3xl', 'max-w-4xl', 'max-w-5xl', 'max-w-6xl', 'max-w-7xl', 'xl:max-w-6xl', '2xl:max-w-7xl',
                'w-[98vw]', 'w-[96vw]', 'w-[92vw]', 'w-full',
                'h-[94vh]', 'max-h-[94vh]', 'max-h-[92vh]', 'max-h-[90vh]', 'sm:max-h-[92vh]', 'sm:max-h-[90vh]', 
                'md:max-w-[98vw]', 'md:h-[95vh]', 'max-w-[98vw]', 'h-[95vh]', 'max-w-sm', 'max-w-md'
            );

            if (fullScreen === true || fullScreen === 'full') {
                el.classList.add('w-[98vw]', 'max-w-6xl', 'max-h-[94vh]', 'overflow-y-auto');
            } else if (fullScreen === 'import-word' || fullScreen === '6xl') {
                el.classList.add('w-[96vw]', 'md:w-full', 'max-w-5xl', 'xl:max-w-6xl', '2xl:max-w-7xl', 'max-h-[94vh]', 'sm:max-h-[92vh]', 'overflow-y-auto');
            } else if (fullScreen === 'wide' || fullScreen === '4xl' || fullScreen === '5xl' || fullScreen === 'large') {
                el.classList.add('w-full', 'max-w-4xl', 'lg:max-w-5xl', 'max-h-[92vh]', 'sm:max-h-[90vh]', 'overflow-y-auto');
            } else if (fullScreen === '3xl' || fullScreen === 'medium') {
                el.classList.add('w-full', 'max-w-3xl', 'max-h-[92vh]', 'sm:max-h-[90vh]', 'overflow-y-auto');
            } else if (fullScreen === 'compact' || fullScreen === 'sm' || fullScreen === 'small') {
                el.classList.add('w-[92vw]', 'sm:w-full', 'max-w-sm', 'max-h-[92vh]', 'sm:max-h-[90vh]', 'overflow-y-auto');
            } else if (fullScreen === 'md' || fullScreen === 'medium-compact') {
                el.classList.add('w-[92vw]', 'sm:w-full', 'max-w-md', 'max-h-[92vh]', 'sm:max-h-[90vh]', 'overflow-y-auto');
            } else {
                el.classList.add('w-full', 'max-w-2xl', 'max-h-[92vh]', 'sm:max-h-[90vh]', 'overflow-y-auto');
            }

            if (alwaysScrollbar) {
                el.classList.add('always-scrollbar-y');
            }

            container.classList.remove('hidden');
            container.style.display = 'flex';
        }

        window.closeModal = closeModal;
        function closeModal() {
            const allContainers = document.querySelectorAll('#modal-container');
            allContainers.forEach(container => {
                container.classList.add('hidden');
                container.style.display = 'none';
            });
            setTimeout(() => {
                const el = document.getElementById('modal-content');
                if (el) {
                    el.innerHTML = '';
                    el.classList.remove('always-scrollbar-y');
                }
            }, 300);
        }

        window.zoomImage = function zoomImage(src) {
            if (!src) return;
            const existingModal = document.getElementById('zoom-modal');
            if (existingModal) existingModal.remove();

            // Tìm container cha thích hợp (nếu đang ở chế độ toàn màn hình thì phải append vào fullscreenElement)
            const activeFs = document.fullscreenElement || document.webkitFullscreenElement || document.mozFullScreenElement || document.msFullscreenElement;
            const targetParent = activeFs || document.body;

            let currentScale = 1;
            let currentRotation = 0;

            const zoomModal = document.createElement('div');
            zoomModal.id = 'zoom-modal';
            zoomModal.className = 'fixed inset-0 z-[9999999] flex flex-col items-center justify-center bg-black/85 backdrop-blur-md p-2 sm:p-4 select-none animate-modal-enter';
            
            zoomModal.innerHTML = `
                <!-- Background Click to Close Overlay -->
                <div class="absolute inset-0 z-0 bg-transparent" id="zoom-overlay-bg"></div>

                <!-- Modal Window / Card -->
                <div class="relative z-10 w-full max-w-5xl max-h-[96vh] flex flex-col bg-slate-900/95 border border-slate-700/80 rounded-2xl shadow-2xl overflow-hidden pointer-events-auto">
                    <!-- Header Bar -->
                    <div class="flex items-center justify-between px-4 py-3 bg-slate-800/90 border-b border-slate-700 text-white shrink-0">
                        <div class="flex items-center gap-2">
                            <span class="p-1.5 bg-emerald-500/20 text-emerald-400 rounded-lg text-sm">🔍</span>
                            <h3 class="font-bold text-sm sm:text-base text-gray-100 m-0">Xem chi tiết hình ảnh</h3>
                        </div>

                        <!-- Action Toolbar -->
                        <div class="flex items-center gap-1.5 sm:gap-2">
                            <button id="btn-zoom-in" class="px-2.5 py-1.5 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-xs sm:text-sm font-semibold transition flex items-center gap-1 active:scale-95" title="Phóng to">
                                <span>➕</span> <span class="hidden md:inline">Phóng to</span>
                            </button>
                            <button id="btn-zoom-out" class="px-2.5 py-1.5 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-xs sm:text-sm font-semibold transition flex items-center gap-1 active:scale-95" title="Thu nhỏ">
                                <span>➖</span> <span class="hidden md:inline">Thu nhỏ</span>
                            </button>
                            <button id="btn-zoom-reset" class="px-2.5 py-1.5 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-xs sm:text-sm font-semibold transition flex items-center gap-1 active:scale-95" title="Kích thước chuẩn">
                                <span>🔄</span> <span class="hidden md:inline">100%</span>
                            </button>
                            <button id="btn-zoom-rotate" class="px-2.5 py-1.5 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-xs sm:text-sm font-semibold transition flex items-center gap-1 active:scale-95" title="Xoay 90 độ">
                                <span>↪️</span> <span class="hidden md:inline">Xoay</span>
                            </button>
                            <button id="btn-zoom-close" class="ml-1 sm:ml-2 px-3 py-1.5 bg-rose-600 hover:bg-rose-700 text-white rounded-lg text-xs sm:text-sm font-bold transition flex items-center gap-1.5 shadow-md active:scale-95" title="Đóng cửa sổ">
                                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                                <span>Đóng</span>
                            </button>
                        </div>
                    </div>

                    <!-- Image Display Area -->
                    <div id="zoom-img-wrapper" class="flex-1 overflow-auto p-3 sm:p-6 flex items-center justify-center bg-slate-950/70 min-h-[300px] max-h-[82vh] cursor-grab active:cursor-grabbing">
                        <img id="zoom-target-image" src="${src}" alt="Hình ảnh phóng to" class="max-w-full max-h-[76vh] object-contain rounded-lg shadow-xl bg-white/5 border border-white/10 p-1 sm:p-2 transition-transform duration-150 ease-out" style="transform: scale(1) rotate(0deg);">
                    </div>

                    <!-- Footer / Hint bar -->
                    <div class="px-4 py-2 bg-slate-800/80 border-t border-slate-700 text-[11px] sm:text-xs text-slate-400 flex items-center justify-between">
                        <span>💡 Nhấp đúp vào ảnh để phóng to/thu nhỏ nhanh • Lăn chuột để phóng to/thu nhỏ</span>
                        <span id="zoom-scale-indicator" class="font-mono text-emerald-400 font-bold">100%</span>
                    </div>
                </div>
            `;

            targetParent.appendChild(zoomModal);

            const imgEl = zoomModal.querySelector('#zoom-target-image');
            const scaleIndicator = zoomModal.querySelector('#zoom-scale-indicator');
            const bgOverlay = zoomModal.querySelector('#zoom-overlay-bg');
            const closeBtn = zoomModal.querySelector('#btn-zoom-close');
            const zoomInBtn = zoomModal.querySelector('#btn-zoom-in');
            const zoomOutBtn = zoomModal.querySelector('#btn-zoom-out');
            const resetBtn = zoomModal.querySelector('#btn-zoom-reset');
            const rotateBtn = zoomModal.querySelector('#btn-zoom-rotate');
            const imgWrapper = zoomModal.querySelector('#zoom-img-wrapper');

            function applyTransform() {
                if (!imgEl) return;
                imgEl.style.transform = `scale(${currentScale}) rotate(${currentRotation}deg)`;
                if (scaleIndicator) {
                    scaleIndicator.textContent = `${Math.round(currentScale * 100)}%`;
                }
            }

            function closeZoomModal() {
                document.removeEventListener('keydown', handleKeyDown);
                zoomModal.remove();
            }

            function handleKeyDown(e) {
                if (e.key === 'Escape') {
                    closeZoomModal();
                } else if (e.key === '+' || e.key === '=') {
                    currentScale = Math.min(4, currentScale + 0.25);
                    applyTransform();
                } else if (e.key === '-' || e.key === '_') {
                    currentScale = Math.max(0.5, currentScale - 0.25);
                    applyTransform();
                } else if (e.key === '0') {
                    currentScale = 1;
                    currentRotation = 0;
                    applyTransform();
                }
            }

            document.addEventListener('keydown', handleKeyDown);

            if (bgOverlay) bgOverlay.onclick = closeZoomModal;
            if (closeBtn) closeBtn.onclick = closeZoomModal;

            if (zoomInBtn) {
                zoomInBtn.onclick = (e) => {
                    e.stopPropagation();
                    currentScale = Math.min(4, currentScale + 0.25);
                    applyTransform();
                };
            }

            if (zoomOutBtn) {
                zoomOutBtn.onclick = (e) => {
                    e.stopPropagation();
                    currentScale = Math.max(0.5, currentScale - 0.25);
                    applyTransform();
                };
            }

            if (resetBtn) {
                resetBtn.onclick = (e) => {
                    e.stopPropagation();
                    currentScale = 1;
                    currentRotation = 0;
                    applyTransform();
                };
            }

            if (rotateBtn) {
                rotateBtn.onclick = (e) => {
                    e.stopPropagation();
                    currentRotation = (currentRotation + 90) % 360;
                    applyTransform();
                };
            }

            // Double click toggle zoom
            if (imgEl) {
                imgEl.ondblclick = (e) => {
                    e.stopPropagation();
                    if (currentScale === 1) {
                        currentScale = 2;
                    } else {
                        currentScale = 1;
                    }
                    applyTransform();
                };
            }

            // Mouse wheel zoom
            if (imgWrapper) {
                imgWrapper.onwheel = (e) => {
                    e.preventDefault();
                    if (e.deltaY < 0) {
                        currentScale = Math.min(4, currentScale + 0.15);
                    } else {
                        currentScale = Math.max(0.5, currentScale - 0.15);
                    }
                    applyTransform();
                };
            }
        };

        window.showConfirmModal = showConfirmModal;
        function showConfirmModal(message, onConfirm, title = '⚠️ Xác nhận', confirmText = 'Xác nhận', cancelText = 'Hủy', isSecondary = false) {
            const modalContent = `
                <div class="p-4 sm:p-5 w-full max-w-sm mx-auto flex flex-col">
                    <h3 class="text-base sm:text-lg font-bold text-gray-800 mb-2 flex items-center gap-2 border-b border-gray-100 pb-2 shrink-0">
                        ${title}
                    </h3>
                    <div class="text-gray-600 mb-4 text-sm sm:text-base leading-snug overflow-x-hidden shrink-0">
                        ${message}
                    </div>
                    <div class="flex flex-row justify-end gap-2 shrink-0 mt-1">
                        ${cancelText ? `<button onclick="${isSecondary ? 'closeSecondaryModal()' : 'closeModal()'}" class="flex-1 sm:flex-none px-3 py-2 sm:px-4 sm:py-2.5 bg-gray-100 text-gray-700 font-semibold rounded-xl hover:bg-gray-200 transition text-sm text-center border border-gray-200 active:scale-95">
                            ${cancelText}
                        </button>` : ''}
                        <button id="confirm-modal-btn" class="flex-1 sm:flex-none px-4 py-2 sm:px-5 sm:py-2.5 bg-gradient-to-r from-emerald-600 to-teal-600 text-white font-bold rounded-xl hover:from-emerald-700 hover:to-teal-700 shadow-md shadow-emerald-200 transition text-sm text-center active:scale-95">
                            ${confirmText}
                        </button>
                    </div>
                </div>
            `;
            
            if (isSecondary) {
                showSecondaryModal(modalContent);
            } else {
                showModal(modalContent);
            }
            
            const modalEl = isSecondary ? document.getElementById('secondary-modal-content') : document.getElementById('modal-content');
            if (modalEl) {
                if (!isSecondary) {
                    modalEl.style.width = '90%';
                    modalEl.style.maxWidth = '360px';
                    modalEl.style.overflowY = 'auto';
                }
                
                // Adjust close button position
                const closeBtn = modalEl.querySelector('button[title="Đóng"]') || modalEl.querySelector('button');
                if (closeBtn && !isSecondary) {
                    closeBtn.style.top = '8px';
                    closeBtn.style.right = '8px';
                }
            }
            const btn = document.getElementById('confirm-modal-btn');
            if (btn) {
                btn.onclick = () => {
                    if (isSecondary) closeSecondaryModal();
                    else closeModal();
                    onConfirm();
                };
            }
        }

        window.showLoadingProgress = showLoadingProgress;
        function showLoadingProgress(title, loadFn) {
            // Hiển thị modal tiến trình
            const progressModalHtml = `
                <div class="p-8 text-center max-w-md mx-auto">
                    <div class="mb-6 flex justify-center">
                        <div class="relative w-16 h-16">
                            <!-- Spinner vòng ngoài -->
                            <div class="absolute inset-0 border-4 border-emerald-100 rounded-full"></div>
                            <div class="absolute inset-0 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                        </div>
                    </div>
                    
                    <h3 class="text-xl font-bold text-gray-800 mb-2">${title}</h3>
                    <p id="progress-status-msg" class="text-gray-500 text-sm mb-4">Đang kết nối máy chủ...</p>
                    
                    <!-- Progress Bar -->
                    <div class="w-full bg-gray-100 rounded-full h-3 mb-4 overflow-hidden">
                        <div id="progress-bar-fill" class="bg-emerald-500 h-full w-0 transition-all duration-300 ease-out" style="width: 5%"></div>
                    </div>
                    
                    <div id="progress-percent" class="text-lg font-bold text-emerald-600">5%</div>
                </div>
            `;
            
            showModal(progressModalHtml);
            const modalEl = document.getElementById('modal-content');
            if (modalEl) {
                modalEl.style.width = '500px';
                modalEl.style.backgroundColor = '#ffffff';
                
                // Tắt nút đóng (Close X) của modal để người dùng không thoát ngang
                const closeBtn = modalEl.querySelector('button[onclick="closeModal()"]');
                if (closeBtn) closeBtn.classList.add('hidden');
                
                const allCloseBtns = modalEl.querySelectorAll('.absolute.top-4.right-4, .close-modal-btn');
                allCloseBtns.forEach(btn => btn.classList.add('hidden'));
            }
            
            let percent = 5;
            
            const pMsg = document.getElementById('progress-status-msg');
            const pBar = document.getElementById('progress-bar-fill');
            const pPercent = document.getElementById('progress-percent');
            
            const updateProgressUI = (p, msg) => {
                percent = p;
                if (pMsg && msg) pMsg.innerText = msg;
                if (pBar) pBar.style.width = `${p}%`;
                if (pPercent) pPercent.innerText = `${p}%`;
            };
            
            // Giả lập tiến trình mượt mà tăng dần trong lúc gọi loadFn
            const timer = setInterval(() => {
                if (percent < 90) {
                    percent += Math.floor(Math.random() * 8) + 3;
                    if (percent > 90) percent = 90;
                    let msg = 'Đang nhận và giải mã dữ liệu...';
                    if (percent < 30) msg = 'Đang thiết lập kênh truyền tải an toàn...';
                    else if (percent < 60) msg = 'Đang truy vấn các bản ghi từ CSDL...';
                    updateProgressUI(percent, msg);
                }
            }, 100);
            
            // Thực thi luồng tải thật
            return (async () => {
                try {
                    await loadFn();
                    clearInterval(timer);
                    updateProgressUI(100, 'Tải và đồng bộ hóa thành công!');
                    setTimeout(() => {
                        closeModal();
                    }, 600);
                } catch (err) {
                    clearInterval(timer);
                    console.error('Lỗi khi tải dữ liệu trong tiến trình:', err);
                    updateProgressUI(100, 'Cảnh báo: Có lỗi xảy ra khi tải dữ liệu!');
                    if (pBar) pBar.classList.replace('bg-emerald-500', 'bg-purple-500');
                    if (pPercent) pPercent.classList.replace('text-emerald-600', 'text-purple-600');
                    setTimeout(() => {
                        closeModal();
                    }, 2000);
                }
            })();
        }

        // ==================== STATISTICS ====================
        function updateStats() {
            const elQuestions = document.getElementById('stat-questions');
            const elStudents = document.getElementById('stat-students');
            const elAvg = document.getElementById('stat-avg');

            let filteredQuestions = questions;
            let filteredResults = results;
            
            const isTeacher = currentUser && currentUser.role !== 'admin' && isTeacherLoggedIn;
            const isStudent = currentUser && (String(currentUser.target_audience || '').toLowerCase() === 'học sinh' || currentUser.target_audience === 'Học sinh') && !isAdminLoggedIn && !isTeacher;

            if (isTeacher) {
                filteredQuestions = questions.filter(q => q.creatorId === currentUser.id);
                // Lọc kết quả thi theo quyền: của mình tạo HOẶC đề đã được mở khóa qua mã chia sẻ
                filteredResults = results.filter(r => {
                    const creatorId = examToCreatorMap[r.examName];
                    const isCreator = String(creatorId) === String(currentUser.id);
                    const isUnlocked = r.examId && window.unlockedExamIds && window.unlockedExamIds.has(String(r.examId));
                    return isCreator || isUnlocked;
                });
            } else if (isStudent) {
                // Học sinh không xem được kết quả
                filteredResults = [];
            }

            if (elQuestions) {
                if (questionsLoaded) {
                    elQuestions.textContent = filteredQuestions.length;
                } else {
                    elQuestions.textContent = window.initialQuestionCount || 0;
                }
            }
            if (elStudents) {
                if (resultsLoaded) {
                    elStudents.textContent = filteredResults.length;
                } else {
                    elStudents.textContent = window.initialResultCount || 0;
                }
            }
            
            const avgScore = filteredResults.length > 0 ? (filteredResults.reduce((sum, r) => sum + r.score, 0) / filteredResults.length).toFixed(1) : '0.0';
            if (elAvg) elAvg.textContent = avgScore;
        }

        function updateStudentTeacherFilter() {
            const select = document.getElementById('student-teacher-filter');
            if (!select) return;
            
            select.disabled = false;
            if (select.options.length > 0) {
                select.options[0].textContent = '-- Chọn giáo viên --';
                select.options[0].value = '';
            } else {
                const defaultOpt = document.createElement('option');
                defaultOpt.value = '';
                defaultOpt.textContent = '-- Chọn giáo viên --';
                select.appendChild(defaultOpt);
            }
            
            // Xóa các option cũ trừ option đầu tiên
            while (select.options.length > 1) {
                select.remove(1);
            }
            
            // Nếu chưa có accounts, nạp ngay danh sách tài khoản từ API
            if (!accounts || accounts.length === 0) {
                const token = localStorage.getItem('auth_token') || '';
                fetch('/api/accounts', { headers: token ? { 'Authorization': 'Bearer ' + token } : {} })
                    .then(r => r.json())
                    .then(res => {
                        if (res && res.data && Array.isArray(res.data) && res.data.length > 0) {
                            accounts = res.data;
                            accounts.forEach(acc => {
                                if (acc.id) accountsMap[acc.id] = acc.full_name || acc.username;
                            });
                            updateStudentTeacherFilter();
                        }
                    })
                    .catch(() => {});
            }
            
            const creatorIds = [...new Set([...(window.allExamCreatorIds || []), ...(examConfigCreatorIds || [])])].map(String);
            
            let teachers = [];
            if (accounts && accounts.length > 0) {
                // Lọc tất cả các tài khoản là Giáo viên hoặc Quản trị viên (Admin)
                const teacherAccounts = accounts.filter(acc => {
                    const aud = String(acc.target_audience || '').toLowerCase();
                    const role = String(acc.role || '').toLowerCase();
                    const isTeacherRole = aud === 'giáo viên' || aud === 'teacher' || role === 'teacher' || role === 'giáo viên';
                    const isAdminRole = aud === 'quản trị viên' || aud === 'admin' || role === 'admin';
                    return isTeacherRole || isAdminRole;
                });
                
                // QUY TẮC: Chỉ hiển thị tài khoản Giáo viên/Admin CÓ ĐỀ THI trong hệ thống
                teachers = teacherAccounts.filter(acc => {
                    const idStr = String(acc.id || '');
                    const userIdStr = String(acc.user_id || '');
                    const hasExamByCount = (acc.exam_count !== undefined && acc.exam_count !== null && Number(acc.exam_count) > 0);
                    const hasExamByCreatorId = creatorIds.includes(idStr) || (userIdStr && creatorIds.includes(userIdStr));
                    return hasExamByCount || hasExamByCreatorId;
                });
                
                // DỰ PHÒNG AN TOÀN TUYỆT ĐỐI: Nếu bộ lọc creatorIds chưa load kịp hoặc danh sách đề thi bị phân quyền lớp/đơn vị khiến creatorIds tạm thời rỗng,
                // hiển thị toàn bộ giáo viên và admin để học sinh không bao giờ bị kẹt ô chọn giáo viên!
                if (teachers.length === 0 && teacherAccounts.length > 0) {
                    teachers = teacherAccounts;
                }
            }
            
            teachers.forEach(t => {
                const opt = document.createElement('option');
                opt.value = t.id;
                const isSystemAdmin = String(t.role || '').toLowerCase() === 'admin' || String(t.target_audience || '').toLowerCase() === 'quản trị viên';
                const unitSuffix = t.donvi ? ` [${t.donvi}]` : (isSystemAdmin ? ' [Quản trị viên]' : '');
                opt.textContent = `${t.full_name || t.username}${unitSuffix}`;
                select.appendChild(opt);
            });
            
            // QUY TẮC: Khi load trang lần đầu hoặc load lại trang, ô chọn giáo viên luôn để giá trị mặc định là "-- Chọn giáo viên --"
            // Tuyệt đối không tự ý chọn giáo viên!
            select.value = '';
            if (typeof onStudentTeacherFilterChange === 'function') {
                onStudentTeacherFilterChange();
            }
        }

        window.resetExamPanelToDefault = resetExamPanelToDefault;
        function resetExamPanelToDefault() {
            const selectEl = document.getElementById('exam-config-name');
            if (selectEl) selectEl.value = '';

            const newExamNameInput = document.getElementById('new-exam-name');
            if (newExamNameInput) newExamNameInput.value = '';

            const elCreator = document.getElementById('exam-config-creator');
            if (elCreator) elCreator.value = currentUser ? currentUser.full_name : (ho_ten_khach_hang || '');

            const cbShared = document.getElementById('exam-config-shared-results');
            if (cbShared) cbShared.checked = false;
            const sharedCodeContainer = document.getElementById('shared-code-container');
            if (sharedCodeContainer) sharedCodeContainer.classList.add('hidden');
            const sharedCode = document.getElementById('exam-shared-code');
            if (sharedCode) sharedCode.value = '';

            const elTime = document.getElementById('exam-config-time');
            if (elTime) elTime.value = '45';

            const elCheat = document.getElementById('exam-config-max-cheat-warnings');
            if (elCheat) elCheat.value = '5';

            const elMode = document.getElementById('exam-config-mode');
            if (elMode) elMode.value = 'Đề công khai';
            const passContainer = document.getElementById('exam-password-container');
            if (passContainer) passContainer.classList.add('hidden');
            const elPass = document.getElementById('exam-config-password');
            if (elPass) elPass.value = '';

            // Reset all counts
            ['41', 'tf4', 'sq', 'tl'].forEach(type => {
                const totalEl = document.getElementById(`exam-count-${type}`);
                if (totalEl) totalEl.value = '0';
                ['nb', 'th', 'vd'].forEach(level => {
                    const el = document.getElementById(`exam-count-${type}-${level}`);
                    if (el) el.value = '0';
                });
            });

            // Reset points
            if (document.getElementById('exam-points-41')) document.getElementById('exam-points-41').value = '1';
            if (document.getElementById('exam-points-tf4')) document.getElementById('exam-points-tf4').value = '1';
            if (document.getElementById('exam-points-sq')) document.getElementById('exam-points-sq').value = '1';
            if (document.getElementById('exam-points-tl')) document.getElementById('exam-points-tl').value = '1';

            // Reset prompts & keys
            if (document.getElementById('exam-config-ai-prompt')) document.getElementById('exam-config-ai-prompt').value = '';
            if (document.getElementById('exam-config-ai-grading-key')) document.getElementById('exam-config-ai-grading-key').value = '';

            // Reset access control
            if (document.getElementById('exam-access-enabled')) document.getElementById('exam-access-enabled').checked = false;
            if (document.getElementById('exam-access-start')) document.getElementById('exam-access-start').value = '';
            if (document.getElementById('exam-access-end')) document.getElementById('exam-access-end').value = '';

            // Reset checkboxes
            if (document.getElementById('exam-config-sq-case-sensitive')) document.getElementById('exam-config-sq-case-sensitive').checked = false;
            if (document.getElementById('exam-config-sq-punctuation-sensitive')) document.getElementById('exam-config-sq-punctuation-sensitive').checked = false;
            if (document.getElementById('exam-config-immediate-feedback')) document.getElementById('exam-config-immediate-feedback').checked = false;
            if (document.getElementById('exam-config-auto-grade-essay')) document.getElementById('exam-config-auto-grade-essay').checked = false;
            if (document.getElementById('exam-config-show-score')) document.getElementById('exam-config-show-score').checked = true;
            if (document.getElementById('exam-config-show-details')) document.getElementById('exam-config-show-details').checked = false;

            // Uncheck all lessons
            const checkboxes = document.querySelectorAll('#exam-lesson-selection input[type="checkbox"]');
            checkboxes.forEach(cb => cb.checked = false);

            // Hide current config display
            const configDisplay = document.getElementById('current-config-display');
            if (configDisplay) configDisplay.classList.add('hidden');

            // Reset global examConfig state
            examConfig = {
                id: '',
                name: '',
                creatorId: currentUser ? currentUser.id : '',
                creatorName: currentUser ? currentUser.full_name : '',
                chedodethi: 'Đề công khai',
                mabaomatdethi: '',
                target_lop: '',
                targetLop: '',
                lop: '',
                target_donvi: '',
                donvi: '',
                timeLimit: 45,
                count41: 0,
                countTF4: 0,
                countSQ: 0,
                countTL: 0,
                count41NB: 0, count41TH: 0, count41VD: 0,
                countTF4NB: 0, countTF4TH: 0, countTF4VD: 0,
                countSQNB: 0, countSQTH: 0, countSQVD: 0,
                countTLNB: 0, countTLTH: 0, countTLVD: 0,
                selectedLessons: [],
                aiPrompt: '',
                aiGradingKey: '',
                points41: 1,
                pointsTF4: 1,
                pointsSQ: 1,
                pointsTL: 1,
                tf4ScoringMode: false,
                tf4Points: { 1: 0.25, 2: 0.50, 3: 0.75, 4: 1.0 },
                immediateFeedback: false,
                sqCaseSensitive: false,
                sqPunctuationSensitive: false,
                autoGradeEssay: false,
                showScore: true,
                showDetails: false,
                isSharedResults: false,
                maxAttempts: 0,
                max_attempts: 0,
                accessControl: { enabled: false, startTime: '', endTime: '' }
            };

            const lopInput = document.getElementById('exam-config-lop');
            if (lopInput) lopInput.value = '';
            const donviInput = document.getElementById('exam-config-donvi');
            if (donviInput) donviInput.value = '';

            toggleExamMode();
            toggleAccessControl();
            updateCurrentExamInfo();
            updateAvailableCounts();
            updateExamCounts();
            updatePointsPreview();
        }

        window.allExamConfigsList = [];
        window.examConfigPageSize = 30;
        window.examConfigCurrentPage = 1;

        window.renderExamConfigsTable = function renderExamConfigsTable() {
            const tbody = document.getElementById('exam-configs-table-body');
            if (!tbody) return;

            const searchKw = (document.getElementById('search-exam-config-table')?.value || '').trim().toLowerCase();
            const list = (window.allExamConfigsList || []).filter(ex => {
                if (!searchKw) return true;
                const name = String(ex.name || '').toLowerCase();
                const mode = String(ex.chedodethi || '').toLowerCase();
                const lop = String(ex.target_lop || ex.lop || '').toLowerCase();
                const id = String(ex.id || '').toLowerCase();
                return name.includes(searchKw) || mode.includes(searchKw) || lop.includes(searchKw) || id.includes(searchKw);
            });

            if (list.length === 0) {
                tbody.innerHTML = `
                    <tr>
                        <td colspan="10" class="text-center py-8 text-gray-400 italic">
                            ${searchKw ? 'Không tìm thấy đề thi nào phù hợp với từ khóa!' : 'Chưa có cấu hình đề thi nào trong danh sách.'}
                        </td>
                    </tr>
                `;
                renderExamConfigsPaginationControls(0, 1, 30, 1);
                return;
            }

            const pageSize = (window.examConfigPageSize === 'all') ? Math.max(1, list.length) : (parseInt(window.examConfigPageSize, 10) || 30);
            const totalPages = Math.max(1, Math.ceil(list.length / pageSize));
            if (!window.examConfigCurrentPage || window.examConfigCurrentPage < 1) window.examConfigCurrentPage = 1;
            if (window.examConfigCurrentPage > totalPages) window.examConfigCurrentPage = totalPages;

            const startIdx = (window.examConfigCurrentPage - 1) * pageSize;
            const pagedList = list.slice(startIdx, startIdx + pageSize);

            tbody.innerHTML = pagedList.map((item, idx) => {
                const globalIdx = startIdx + idx + 1;
                const totalQ = (Number(item.count_41 || item.count41 || 0)) + 
                               (Number(item.count_tf4 || item.countTF4 || 0)) + 
                               (Number(item.count_sq || item.countSQ || 0)) + 
                               (Number(item.count_tl || item.countTL || 0));
                const time = Number(item.time_limit || item.timeLimit || 45);
                const mode = item.chedodethi || 'Đề công khai';
                const isPublicMode = (mode === 'Đề công khai' || !mode);
                const lop = isPublicMode ? '' : String(item.target_lop || item.lop || '').trim();
                const donvi = isPublicMode ? '' : String(item.target_donvi || item.donvi || '').trim();

                let modeBadge = '';
                if (mode === 'Đề cho đơn vị' || mode === 'Đề thi cho đơn vị') {
                    modeBadge = `<span class="px-2.5 py-1 bg-amber-100 text-amber-800 text-xs font-semibold rounded-full border border-amber-200">Đề cho đơn vị</span>`;
                } else if (mode === 'Đề có mã bảo mật') {
                    modeBadge = `<span class="px-2.5 py-1 bg-rose-100 text-rose-800 text-xs font-semibold rounded-full border border-rose-200">🔒 Có mật khẩu</span>`;
                } else {
                    modeBadge = `<span class="px-2.5 py-1 bg-emerald-100 text-emerald-800 text-xs font-semibold rounded-full border border-emerald-200">🌐 Công khai</span>`;
                }

                let lopBadge = '';
                if (mode === 'Đề cho đơn vị' || mode === 'Đề thi cho đơn vị') {
                    if (donvi || lop) {
                        lopBadge = `<div class="flex flex-col gap-1">${donvi ? `<span class="px-2 py-0.5 bg-purple-100 text-purple-800 text-[11px] font-semibold rounded border border-purple-200" title="Đơn vị áp dụng">🏫 ${escapeHTML(donvi)}</span>` : ''}${lop ? `<span class="px-2 py-0.5 bg-blue-100 text-blue-800 text-[11px] font-bold rounded border border-blue-200" title="Lớp áp dụng">🏷️ ${escapeHTML(lop)}</span>` : ''}</div>`;
                    } else {
                        lopBadge = `<span class="text-xs text-gray-400 italic">Tất cả đơn vị & lớp</span>`;
                    }
                } else {
                    lopBadge = `<span class="text-xs text-gray-300">-</span>`;
                }

                const count41 = Number(item.count_41 || item.count41 || 0);
                const countTF4 = Number(item.count_tf4 || item.countTF4 || 0);
                const countSQ = Number(item.count_sq || item.countSQ || 0);
                const countTL = Number(item.count_tl || item.countTL || 0);
                const parts = [];
                if (count41 > 0) parts.push(`<span class="text-blue-700" title="Trắc nghiệm 4 lựa chọn">${count41}TN</span>`);
                if (countTF4 > 0) parts.push(`<span class="text-amber-700" title="Trắc nghiệm Đúng/Sai">${countTF4}ĐS</span>`);
                if (countSQ > 0) parts.push(`<span class="text-teal-700" title="Trả lời ngắn">${countSQ}TLN</span>`);
                if (countTL > 0) parts.push(`<span class="text-red-700" title="Tự luận">${countTL}TL</span>`);
                const detailStr = parts.length > 0 ? parts.join(' | ') : '<span class="text-gray-400">Không có</span>';

                const features = [];
                if (item.is_shared_results) {
                    features.push(`<span class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-teal-50 text-teal-700 text-[10px] font-medium rounded border border-teal-200" title="Đang bật chia sẻ kết quả">🤝 Chia sẻ KQ</span>`);
                }
                if (item.access_control && (item.access_control.enabled || item.tg_bd || item.tg_kt)) {
                    features.push(`<span class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-indigo-50 text-indigo-700 text-[10px] font-medium rounded border border-indigo-200" title="Hạn làm bài thi">🕒 Hẹn giờ</span>`);
                }
                const maxAtt = Number(item.max_attempts || item.maxAttempts || 0);
                if (maxAtt > 0) {
                    features.push(`<span class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-sky-50 text-sky-700 text-[10px] font-medium rounded border border-sky-200" title="Lượt thi tối đa">🔄 Thi ${maxAtt}l</span>`);
                }
                const maxCheat = Number(item.max_cheat_warnings || item.maxCheatWarnings || 5);
                if (maxCheat > 0) {
                    features.push(`<span class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-rose-50 text-rose-700 text-[10px] font-medium rounded border border-rose-200" title="Giám sát cảnh báo rời màn hình">⚠️ Giám sát: ${maxCheat}l</span>`);
                }
                const featuresHtml = features.length > 0 ? `<div class="flex flex-wrap gap-1 justify-center max-w-[150px]">${features.join('')}</div>` : '<span class="text-gray-300">-</span>';

                const escapedName = escapeHTML(item.name || 'Không tên');
                const creator = item.creatorName || item.creator_name || accountsMap[item.creator_id || item.creatorId] || 'Hệ thống';
                const isCreator = currentUser && (String(item.creator_id || item.creatorId) === String(currentUser.id) || isAdminLoggedIn);

                return `
                    <tr class="hover:bg-purple-50/50 transition border-b border-gray-100">
                        <td class="py-3 px-3 text-center text-xs font-medium text-gray-500">${globalIdx}</td>
                        <td class="py-3 px-3 text-center text-xs font-mono text-gray-600 whitespace-nowrap">
                            <span class="bg-gray-100 px-2 py-1 rounded text-xs font-bold text-gray-700 select-all">${item.id}</span>
                        </td>
                        <td class="py-3 px-4 font-semibold text-gray-800 max-w-xs truncate" title="${escapedName}">
                            ${escapedName}
                        </td>
                        <td class="py-3 px-3 whitespace-nowrap">
                            <span class="text-xs font-semibold text-gray-600">${escapeHTML(creator)}</span>
                        </td>
                        <td class="py-3 px-3 whitespace-nowrap">${modeBadge}</td>
                        <td class="py-3 px-3 whitespace-nowrap">${lopBadge}</td>
                        <td class="py-3 px-3 text-center text-xs text-gray-700 whitespace-nowrap font-medium">${time} phút</td>
                        <td class="py-3 px-3 text-center text-xs font-semibold text-purple-700 whitespace-nowrap">
                            <span class="font-bold text-purple-800">${totalQ} câu</span>
                            <div class="text-[10px] text-gray-500 mt-0.5 font-normal">${detailStr}</div>
                        </td>
                        <td class="py-3 px-3 text-center text-xs whitespace-nowrap">
                            ${featuresHtml}
                        </td>
                        <td class="py-3 px-3 text-center whitespace-nowrap">
                            <div class="flex items-center justify-center gap-1.5">
                                <button onclick="loadExamConfigById('${item.id}')" class="px-2.5 py-1 bg-purple-600 text-white rounded text-xs font-medium hover:bg-purple-700 transition flex items-center gap-1" title="Nạp cấu hình vào khung soạn thảo">
                                    <span>⚙️</span> Nạp
                                </button>
                                <button onclick="openExportDocxModal('${item.id}')" class="px-2.5 py-1 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded text-xs font-medium hover:from-blue-700 hover:to-indigo-700 transition flex items-center gap-1 shadow-2xs" title="Xuất đề thi ra file Word (.docx)">
                                    <span>📄</span> Xuất
                                </button>
                                ${isCreator ? `
                                <button onclick="deleteExamConfig('${item.id}', '${escapedName.replace(/'/g, "\\'")}')" class="px-2.5 py-1 bg-red-100 text-red-600 hover:bg-red-200 rounded text-xs font-medium transition" title="Xóa đề thi này">
                                    🗑️
                                </button>` : ''}
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            renderExamConfigsPaginationControls(list.length, window.examConfigCurrentPage, pageSize, totalPages);
        };

        function renderExamConfigsPaginationControls(totalItems, currentPage, pageSize, totalPages) {
            const tbody = document.getElementById('exam-configs-table-body');
            if (!tbody) return;
            const table = tbody.closest('table');
            if (!table) return;

            let container = document.getElementById('exam-configs-pagination-container');
            if (!container) {
                container = document.createElement('div');
                container.id = 'exam-configs-pagination-container';
                container.className = 'flex flex-wrap items-center justify-between gap-3 pt-4 px-2 text-xs text-gray-600 font-medium border-t border-gray-100 mt-2';
                table.parentNode.insertBefore(container, table.nextSibling);
            }

            if (totalItems === 0) {
                container.innerHTML = `<div class="text-gray-400 italic">Tổng số: 0 đề thi</div>`;
                return;
            }

            const startNum = (currentPage - 1) * (typeof pageSize === 'number' ? pageSize : totalItems) + 1;
            const endNum = Math.min(startNum + (typeof pageSize === 'number' ? pageSize : totalItems) - 1, totalItems);

            const isFirst = currentPage <= 1;
            const isLast = currentPage >= totalPages;
            const sizeVal = window.examConfigPageSize || 30;

            container.innerHTML = `
                <div class="flex items-center gap-2">
                    <span>Hiển thị <strong class="text-purple-700">${startNum} - ${endNum}</strong> trên tổng số <strong class="text-purple-700">${totalItems.toLocaleString('vi-VN')}</strong> đề thi</span>
                    <span class="text-gray-300">|</span>
                    <label class="flex items-center gap-1.5">
                        <span>Số dòng:</span>
                        <select onchange="changeExamConfigsPageSize(this.value)" class="px-2 py-1 bg-white border border-gray-200 rounded-md font-semibold text-purple-700 shadow-2xs focus:outline-none focus:ring-1 focus:ring-purple-500 cursor-pointer">
                            <option value="30" ${sizeVal == 30 ? 'selected' : ''}>30 dòng / trang</option>
                            <option value="50" ${sizeVal == 50 ? 'selected' : ''}>50 dòng / trang</option>
                            <option value="100" ${sizeVal == 100 ? 'selected' : ''}>100 dòng / trang</option>
                            <option value="all" ${sizeVal == 'all' ? 'selected' : ''}>Hiển thị tất cả</option>
                        </select>
                    </label>
                </div>
                <div class="flex items-center gap-1.5">
                    <button onclick="changeExamConfigsPage(1)" ${isFirst ? 'disabled' : ''} class="px-2.5 py-1.5 rounded-lg border border-gray-200 bg-white hover:bg-purple-50 hover:text-purple-700 disabled:opacity-40 disabled:hover:bg-white disabled:hover:text-gray-400 transition font-medium cursor-pointer disabled:cursor-not-allowed">
                        ⏮️ Đầu
                    </button>
                    <button onclick="changeExamConfigsPage(${currentPage - 1})" ${isFirst ? 'disabled' : ''} class="px-2.5 py-1.5 rounded-lg border border-gray-200 bg-white hover:bg-purple-50 hover:text-purple-700 disabled:opacity-40 disabled:hover:bg-white disabled:hover:text-gray-400 transition font-medium cursor-pointer disabled:cursor-not-allowed">
                        ◀️ Trước
                    </button>
                    <span class="px-3 py-1.5 bg-purple-50 text-purple-800 rounded-lg border border-purple-200 font-bold">
                        Trang ${currentPage} / ${totalPages}
                    </span>
                    <button onclick="changeExamConfigsPage(${currentPage + 1})" ${isLast ? 'disabled' : ''} class="px-2.5 py-1.5 rounded-lg border border-gray-200 bg-white hover:bg-purple-50 hover:text-purple-700 disabled:opacity-40 disabled:hover:bg-white disabled:hover:text-gray-400 transition font-medium cursor-pointer disabled:cursor-not-allowed">
                        Sau ▶️
                    </button>
                    <button onclick="changeExamConfigsPage(${totalPages})" ${isLast ? 'disabled' : ''} class="px-2.5 py-1.5 rounded-lg border border-gray-200 bg-white hover:bg-purple-50 hover:text-purple-700 disabled:opacity-40 disabled:hover:bg-white disabled:hover:text-gray-400 transition font-medium cursor-pointer disabled:cursor-not-allowed">
                        Cuối ⏭️
                    </button>
                </div>
            `;
        }

        window.changeExamConfigsPage = function(page) {
            window.examConfigCurrentPage = page;
            window.renderExamConfigsTable();
        };

        window.changeExamConfigsPageSize = function(size) {
            window.examConfigPageSize = size === 'all' ? 'all' : parseInt(size, 10);
            window.examConfigCurrentPage = 1;
            window.renderExamConfigsTable();
        };

        window.loadExamConfigById = async function loadExamConfigById(selectedId) {
            if (!selectedId) return;
            const selectEl = document.getElementById('exam-config-name');
            if (selectEl) {
                selectEl.value = selectedId;
            }
            try {
                const token = localStorage.getItem('auth_token') || '';
                const res = await fetch(`/api/exams?id=${encodeURIComponent(selectedId)}`, {
                    headers: token ? { 'Authorization': 'Bearer ' + token } : {}
                });
                let resJson;
                const contentType = res.headers.get("content-type");
                if (contentType && contentType.includes("application/json")) {
                    resJson = await res.json();
                } else {
                    throw new Error("Server returned non-JSON response. Status: " + res.status);
                }
                
                if (res.ok && resJson.data) {
                    applyExamConfig(resJson.data);
                    showToast(`📂 Đã nạp cấu hình đề: ${resJson.data.name || selectedId}`, 'success');
                    const btnExport = document.getElementById('btn-export-exam-docx');
                    if (btnExport) btnExport.classList.remove('hidden');
                    // Cuộn mượt lên phần thông tin cấu hình
                    const topPanel = document.getElementById('tab-exams');
                    if (topPanel) topPanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            } catch (e) {
                console.error('Error in loadExamConfigById:', e);
                showToast('Không thể tải cấu hình đề thi đã chọn!', 'error');
            }
        };

        window.openExportDocxModal = async function openExportDocxModal(explicitExamId) {
            const targetExamId = explicitExamId || document.getElementById('exam-config-name')?.value || examConfig?.id;
            if (!targetExamId) {
                showToast('Vui lòng chọn một đề thi có sẵn trước khi xuất!', 'warning');
                return;
            }

            let targetExam = (window.allExamConfigsList || []).find(e => String(e.id) === String(targetExamId));
            if (!targetExam && examConfig && String(examConfig.id) === String(targetExamId)) {
                targetExam = examConfig;
            }

            if (!targetExam) {
                try {
                    const token = localStorage.getItem('auth_token') || '';
                    const res = await fetch(`/api/exams?id=${encodeURIComponent(targetExamId)}`, {
                        headers: token ? { 'Authorization': 'Bearer ' + token } : {}
                    });
                    const resJson = await res.json();
                    if (res.ok && resJson.data) targetExam = resJson.data;
                } catch(e) {}
            }

            const examName = targetExam ? (targetExam.name || targetExam.title || 'Đề thi') : (examConfig.name || 'Đề thi');
            const timeLimit = targetExam ? (targetExam.time_limit || targetExam.timeLimit || 45) : (examConfig.timeLimit || 45);
            
            let lessons = [];
            if (targetExam) {
                lessons = targetExam.selected_lessons || targetExam.selectedLessons || [];
                if (typeof lessons === 'string') {
                    try { lessons = JSON.parse(lessons); } catch(e) { lessons = []; }
                }
            } else if (examConfig.selectedLessons) {
                lessons = examConfig.selectedLessons;
            }

            const defaultSo = "SỞ GIÁO DỤC VÀ ĐÀO TẠO GIA LAI";
            const defaultTruong = (currentUser && currentUser.donvi) ? ("TRƯỜNG " + currentUser.donvi.toUpperCase()) : "TRƯỜNG THPT LÊ HOÀN";
            const defaultTitle = examName.toUpperCase().startsWith("ĐỀ") ? examName.toUpperCase() : ("ĐỀ KIỂM TRA: " + examName.toUpperCase());
            const defaultNamHoc = "NĂM HỌC 2026 - 2027";
            const defaultMon = (lessons && lessons.length > 0) ? ("MÔN " + String(lessons[0]).toUpperCase()) : "MÔN TIN HỌC, LỚP 12";
            const defaultMaDe = String(Math.floor(1000 + Math.random() * 9000));

            window.updateExportMaDeNote = function() {
                const numEl = document.getElementById('docx-export-so-luong');
                const maDeEl = document.getElementById('docx-export-made');
                const noteBox = document.getElementById('export-made-note-box');
                if (!noteBox) return;

                const num = Math.min(20, Math.max(1, parseInt(numEl?.value || '1', 10)));
                const baseMaDe = (maDeEl?.value || '1201').trim();

                if (num <= 1) {
                    noteBox.innerHTML = `<div class="flex items-center gap-1.5 font-medium text-blue-800"><span class="text-base">📄</span><span>Tạo <strong>1 đề thi đơn lẻ</strong> với mã đề: <strong class="text-indigo-700 font-mono bg-indigo-50 px-1.5 py-0.5 rounded border border-indigo-200">${escapeHTML(baseMaDe)}</strong> (file .docx).</span></div>`;
                } else {
                    let examples = [];
                    const match = baseMaDe.match(/^(.*?)(\d+)$/);
                    if (match) {
                        const prefix = match[1];
                        const digits = match[2];
                        const baseVal = parseInt(digits, 10);
                        for (let i = 0; i < Math.min(num, 4); i++) {
                            examples.push(prefix + String(baseVal + i).padStart(digits.length, '0'));
                        }
                    } else {
                        examples = [baseMaDe, baseMaDe + "_2", baseMaDe + "_3"];
                    }
                    const exText = examples.join(', ') + (num > 4 ? ', ...' : '');
                    noteBox.innerHTML = `<div class="space-y-1"><div class="flex items-center gap-1.5 font-bold text-amber-900"><span class="text-base">📦</span><span>Tự động bốc ngẫu nhiên tạo bộ <strong>${num} mã đề thi</strong> khác nhau:</span></div><div class="text-gray-700">• Các mã đề: <strong class="text-indigo-700 font-mono bg-indigo-50 px-1.5 py-0.5 rounded border border-indigo-200">${escapeHTML(exText)}</strong></div><div class="text-gray-600 text-[11px]">• Mỗi mã đề thi sẽ tự động bốc câu hỏi ngẫu nhiên theo đúng cấu hình khung ma trận đề thi. Kết quả xuất đóng gói vào 1 file <strong>.ZIP</strong> chứa đầy đủ ${num} file Word (.docx).</div></div>`;
                }
            };

            const modalContent = `
                <div class="p-4 sm:p-6 text-left w-full max-w-3xl mx-auto">
                    <div class="flex items-center justify-between pb-3.5 mb-4 border-b border-gray-100">
                        <div class="flex items-center gap-3">
                            <div class="w-11 h-11 rounded-2xl bg-gradient-to-br from-blue-600 via-indigo-600 to-purple-600 text-white flex items-center justify-center shadow-lg shadow-blue-500/20 shrink-0">
                                <svg class="w-6 h-6 text-amber-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path>
                                </svg>
                            </div>
                            <div>
                                <h3 class="text-lg sm:text-xl font-black text-gray-800 leading-tight">Xuất đề thi (Word / PDF / Excel đáp án)</h3>
                                <p class="text-xs sm:text-sm text-gray-500 font-medium">Định dạng A4 chuẩn Bộ GD&ĐT, tùy chọn xuất file Word (.docx) hoặc PDF (.pdf) kèm bảng đáp án Excel</p>
                            </div>
                        </div>
                    </div>

                    <form onsubmit="event.preventDefault(); window.executeDocxExport('${targetExamId}');" class="space-y-4">
                        <!-- Format Selection (Word / PDF) -->
                        <div class="bg-gradient-to-r from-blue-50/80 via-indigo-50/80 to-purple-50/80 p-3.5 rounded-2xl border border-blue-200/90 shadow-2xs space-y-2">
                            <label class="block text-xs md:text-sm font-bold text-gray-800 flex items-center gap-1.5">
                                <span>📦</span> Chọn định dạng file xuất đề thi:
                            </label>
                            <div class="grid grid-cols-2 gap-3">
                                <label class="flex items-center gap-2.5 p-3 bg-white rounded-xl border-2 border-blue-500 cursor-pointer hover:bg-blue-50/50 transition font-bold text-xs md:text-sm text-blue-900 shadow-2xs has-checked:border-blue-600 has-checked:bg-blue-50">
                                    <input type="radio" name="export-format" value="docx" checked class="w-4 h-4 text-blue-600 focus:ring-blue-500 cursor-pointer">
                                    <span class="flex items-center gap-1.5">
                                        <span class="text-base">📝</span> File Word (.docx)
                                    </span>
                                </label>
                                <label class="flex items-center gap-2.5 p-3 bg-white rounded-xl border-2 border-gray-200 cursor-pointer hover:bg-red-50/50 transition font-bold text-xs md:text-sm text-gray-700 shadow-2xs has-checked:border-red-500 has-checked:bg-red-50">
                                    <input type="radio" name="export-format" value="pdf" class="w-4 h-4 text-red-600 focus:ring-red-500 cursor-pointer">
                                    <span class="flex items-center gap-1.5">
                                        <span class="text-base">📑</span> File PDF (.pdf)
                                    </span>
                                </label>
                            </div>
                        </div>

                        <!-- Prominent Full-Width Exam Title Field -->
                        <div class="bg-blue-50/60 p-3.5 rounded-2xl border border-blue-200/80 space-y-1">
                            <label class="block text-xs md:text-sm font-bold text-blue-950 mb-1 flex items-center gap-1.5">
                                <span class="text-blue-600">📝</span> Tiêu đề kỳ thi / Đề kiểm tra:
                            </label>
                            <input type="text" id="docx-export-title" value="${escapeHtml(defaultTitle)}" 
                                   class="w-full px-4 py-2.5 text-sm md:text-base border-2 border-blue-300 focus:border-blue-600 focus:ring-4 focus:ring-blue-100 focus:outline-none bg-white font-bold text-gray-900 rounded-xl shadow-sm transition"
                                   placeholder="Nhập tiêu đề đề thi...">
                        </div>

                        <!-- Agency & School Info -->
                        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            <div>
                                <label class="block text-xs md:text-sm font-bold text-gray-700 mb-1">Cơ quan cấp trên / Sở GD&ĐT:</label>
                                <input type="text" id="docx-export-so" value="${escapeHtml(defaultSo)}" class="w-full px-3.5 py-2 text-xs md:text-sm border border-gray-300 rounded-xl focus:border-blue-500 focus:outline-none bg-white font-medium">
                            </div>
                            <div>
                                <label class="block text-xs md:text-sm font-bold text-gray-700 mb-1">Tên trường / Đơn vị:</label>
                                <input type="text" id="docx-export-truong" value="${escapeHtml(defaultTruong)}" class="w-full px-3.5 py-2 text-xs md:text-sm border border-gray-300 rounded-xl focus:border-blue-500 focus:outline-none bg-white font-medium">
                            </div>
                        </div>

                        <!-- Subject & Year Info -->
                        <div class="grid grid-cols-1 sm:grid-cols-3 gap-3">
                            <div class="sm:col-span-2">
                                <label class="block text-xs md:text-sm font-bold text-gray-700 mb-1">Môn học / Lớp:</label>
                                <input type="text" id="docx-export-monhoc" value="${escapeHtml(defaultMon)}" class="w-full px-3.5 py-2 text-xs md:text-sm border border-gray-300 rounded-xl focus:border-blue-500 focus:outline-none bg-white font-medium">
                            </div>
                            <div>
                                <label class="block text-xs md:text-sm font-bold text-gray-700 mb-1">Năm học:</label>
                                <input type="text" id="docx-export-namhoc" value="${escapeHtml(defaultNamHoc)}" class="w-full px-3.5 py-2 text-xs md:text-sm border border-gray-300 rounded-xl focus:border-blue-500 focus:outline-none bg-white font-medium">
                            </div>
                        </div>

                        <!-- Dedicated Multi-Exam & Test Code Section -->
                        <div class="p-4 bg-gradient-to-r from-amber-50/90 via-orange-50/70 to-indigo-50/80 border border-amber-200/90 rounded-2xl space-y-3">
                            <div class="flex items-center gap-2 font-black text-xs md:text-sm text-gray-800">
                                <span class="text-amber-600 text-lg">🎲</span>
                                <span>Tùy chọn bốc câu hỏi ngẫu nhiên & Xuất nhiều mã đề thi:</span>
                            </div>
                            <div class="grid grid-cols-1 sm:grid-cols-3 gap-3">
                                <div>
                                    <label class="block text-xs font-bold text-amber-950 mb-1">
                                        Số lượng đề thi cần xuất:
                                    </label>
                                    <input type="number" id="docx-export-so-luong" value="1" min="1" max="20" 
                                           oninput="window.updateExportMaDeNote()"
                                           onchange="window.updateExportMaDeNote()"
                                           class="w-full px-3.5 py-2 text-sm border-2 border-amber-300 rounded-xl focus:border-amber-600 focus:outline-none bg-white font-black text-amber-900 text-center shadow-sm">
                                </div>
                                <div>
                                    <label class="block text-xs font-bold text-indigo-950 mb-1">
                                        Mã đề thi bắt đầu (Đề 1):
                                    </label>
                                    <input type="text" id="docx-export-made" value="${escapeHtml(defaultMaDe)}" 
                                           oninput="window.updateExportMaDeNote()"
                                           class="w-full px-3.5 py-2 text-sm border-2 border-indigo-400 rounded-xl focus:border-indigo-600 focus:outline-none bg-indigo-50/80 font-black text-indigo-900 text-center tracking-wider shadow-sm">
                                </div>
                                <div>
                                    <label class="block text-xs font-bold text-gray-700 mb-1">
                                        Thời gian làm bài (phút):
                                    </label>
                                    <input type="number" id="docx-export-thoigian" value="${timeLimit}" min="1" max="300" class="w-full px-3.5 py-2 text-xs md:text-sm border border-gray-300 rounded-xl focus:border-blue-500 focus:outline-none bg-white font-bold shadow-sm">
                                </div>
                            </div>
                            <div id="export-made-note-box" class="p-3 bg-white/90 rounded-xl border border-amber-200/90 text-xs shadow-xs">
                                <!-- Updated dynamically via JS -->
                            </div>
                        </div>

                        <div class="p-3 bg-gray-50 border border-gray-200 rounded-xl text-xs text-gray-700 space-y-1">
                            <p class="font-bold flex items-center gap-1 text-gray-900">
                                <span>📐</span> Chuẩn định dạng trang in Word & File Excel đáp án:
                            </p>
                            <ul class="list-disc list-inside space-y-0.5 text-[11px] text-gray-600">
                                <li>File Word (.docx): Phông chữ <strong>Times New Roman 13pt</strong>, khổ <strong>A4</strong>, căn lề 2cm, bảng không viền thẳng hàng.</li>
                                <li>File Excel (.xlsx): Kèm theo bảng đáp án tổng hợp với các cột tương ứng từng mã đề thi và chi tiết từng câu hỏi.</li>
                                <li>Đóng gói trọn bộ file Word và file Excel đáp án vào 1 tệp tin (.zip) tiện lợi, an toàn.</li>
                            </ul>
                        </div>

                        <!-- Tiến trình tạo đề thi ngẫu nhiên thời gian thực -->
                        <div id="export-docx-progress-container" class="hidden p-4 bg-gradient-to-r from-blue-50/90 via-indigo-50/90 to-purple-50/90 border-2 border-blue-300/80 rounded-2xl shadow-md space-y-2.5 transition-all">
                            <div class="flex items-center justify-between text-xs md:text-sm font-bold text-blue-950">
                                <div class="flex items-center gap-2">
                                    <svg id="progress-spinner" class="animate-spin w-4.5 h-4.5 text-blue-600 shrink-0" fill="none" viewBox="0 0 24 24">
                                        <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                                        <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                    </svg>
                                    <span id="export-progress-title" class="font-bold text-gray-800">Đang tiến hành tạo đề thi & bảng đáp án Excel...</span>
                                </div>
                                <span id="export-progress-percent" class="font-black text-blue-700 font-mono text-sm md:text-base bg-blue-100/90 px-2.5 py-0.5 rounded-lg border border-blue-200">0%</span>
                            </div>

                            <!-- Thanh phần trăm tiến trình -->
                            <div class="w-full h-3.5 bg-blue-100/90 rounded-full overflow-hidden p-0.5 border border-blue-200 shadow-inner">
                                <div id="export-progress-bar" class="h-full bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 rounded-full transition-all duration-300 shadow-xs" style="width: 0%;"></div>
                            </div>

                            <!-- Thông tin chi tiết số lượng đề thi đã tạo thành công -->
                            <div class="flex items-center justify-between text-xs font-semibold text-gray-700 pt-0.5">
                                <span id="export-progress-status" class="text-blue-900 font-medium">Đang khởi tạo dữ liệu...</span>
                                <span id="export-progress-count" class="font-bold text-indigo-950 bg-white px-2.5 py-0.5 rounded-md border border-indigo-200/80 shadow-2xs font-mono">0 / 1 đề</span>
                            </div>
                        </div>

                        <div class="pt-3 border-t border-gray-100 flex items-center justify-end gap-3">
                            <button type="button" onclick="closeModal()" class="px-5 py-2.5 bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold rounded-xl text-xs md:text-sm transition cursor-pointer">
                                Hủy
                            </button>
                            <button type="submit" id="btn-submit-docx-export" class="px-6 py-2.5 bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white font-bold rounded-xl text-xs md:text-sm transition shadow-lg shadow-blue-500/25 active:scale-95 cursor-pointer flex items-center gap-2">
                                <svg class="w-4 h-4 text-amber-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                                <span>📥 Tải đề và đáp án</span>
                            </button>
                        </div>
                    </form>
                </div>
            `;
            showModal(modalContent, '3xl', true);
            if (window.updateExportMaDeNote) {
                window.updateExportMaDeNote();
            }
        };

        window.executeDocxExport = async function executeDocxExport(targetExamId) {
            const btn = document.getElementById('btn-submit-docx-export');
            const originalText = btn ? btn.innerHTML : '';

            const exportFormat = document.querySelector('input[name="export-format"]:checked')?.value || 'docx';
            const soGiaoDuc = document.getElementById('docx-export-so')?.value || '';
            const truongHoc = document.getElementById('docx-export-truong')?.value || '';
            const deThiTitle = document.getElementById('docx-export-title')?.value || '';
            const namHoc = document.getElementById('docx-export-namhoc')?.value || '';
            const monHoc = document.getElementById('docx-export-monhoc')?.value || '';
            const baseMaDe = (document.getElementById('docx-export-made')?.value || '1201').trim();
            const soLuongDe = Math.min(20, Math.max(1, parseInt(document.getElementById('docx-export-so-luong')?.value || '1', 10)));
            const thoiGian = document.getElementById('docx-export-thoigian')?.value || 45;

            const progressContainer = document.getElementById('export-docx-progress-container');
            const progressTitle = document.getElementById('export-progress-title');
            const progressPercent = document.getElementById('export-progress-percent');
            const progressBar = document.getElementById('export-progress-bar');
            const progressStatus = document.getElementById('export-progress-status');
            const progressCount = document.getElementById('export-progress-count');

            if (progressContainer) {
                progressContainer.classList.remove('hidden');
            }

            if (btn) {
                btn.disabled = true;
                btn.innerHTML = '<span>⏳</span> Đang bốc ngẫu nhiên & tạo đề...';
            }

            const updateProgress = (percent, statusText, countText) => {
                const rounded = Math.min(100, Math.max(0, Math.round(percent)));
                if (progressPercent) progressPercent.innerText = `${rounded}%`;
                if (progressBar) progressBar.style.width = `${rounded}%`;
                if (progressStatus && statusText) progressStatus.innerText = statusText;
                if (progressCount && countText) progressCount.innerText = countText;
            };

            const formatName = exportFormat === 'pdf' ? 'PDF' : 'Word';
            updateProgress(10, `Đang khởi tạo bốc câu hỏi ngẫu nhiên cho ${soLuongDe} mã đề (${formatName})...`, `0 / ${soLuongDe} đề`);

            // Nhường lượt vẽ DOM ngay lập tức cho trình duyệt để hiển thị thanh tiến trình tức thì không giật lag
            await new Promise(resolve => setTimeout(resolve, 60));

            try {
                const token = localStorage.getItem('auth_token') || '';
                let useClientFallback = false;
                let downloaded = false;

                if (exportFormat === 'pdf') {
                    useClientFallback = true;
                } else {
                    // 1. Gọi API Server xuất trọn bộ đề thi Word và file Excel bảng đáp án
                    try {
                        updateProgress(25, `Đang bốc ngẫu nhiên câu hỏi & tạo ${soLuongDe} mã đề thi Word kèm Excel đáp án...`, `0 / ${soLuongDe} đề`);
                        const response = await fetch('/api/exam/export-docx', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                ...(token ? { 'Authorization': 'Bearer ' + token } : {})
                            },
                            body: JSON.stringify({
                                examId: targetExamId,
                                teacherId: currentUser?.id,
                                soGiaoDuc,
                                truongHoc,
                                deThiTitle,
                                namHoc,
                                monHoc,
                                maDe: baseMaDe,
                                soLuongDe,
                                thoiGian,
                                exportFormat
                            })
                        });

                        if (!response.ok) {
                            let errorText = '';
                            try {
                                const errJson = await response.json();
                                errorText = errJson.error || '';
                            } catch(e) {}

                            if (errorText) {
                                throw new Error(errorText);
                            }
                            useClientFallback = true;
                        } else {
                            updateProgress(90, `📦 Đang tải về gói đề thi Word và file Excel bảng đáp án...`, `${soLuongDe} / ${soLuongDe} đề`);
                            const zipBlob = await response.blob();
                            const safeTitle = deThiTitle.replace(/[^a-zA-Z0-9_\u00C0-\u1EF9]/g, '_');
                            const zipFileName = soLuongDe === 1
                                ? `De_Thi_kem_Dap_An_${safeTitle}_MaDe_${baseMaDe}.zip`
                                : `Bo_De_Thi_${safeTitle}_Gom_${soLuongDe}_MaDe_kem_Dap_An.zip`;

                            if (typeof saveAs === 'function') {
                                saveAs(zipBlob, zipFileName);
                            } else if (window.saveAs) {
                                window.saveAs(zipBlob, zipFileName);
                            } else {
                                const downloadUrl = URL.createObjectURL(zipBlob);
                                const a = document.createElement('a');
                                a.href = downloadUrl;
                                a.download = zipFileName;
                                document.body.appendChild(a);
                                a.click();
                                setTimeout(() => {
                                    document.body.removeChild(a);
                                    URL.revokeObjectURL(downloadUrl);
                                }, 500);
                            }

                            updateProgress(100, `🎉 Hoàn tất! Đã xuất thành công ${soLuongDe} mã đề thi kèm file Excel đáp án`, `${soLuongDe} / ${soLuongDe} đề`);
                            showToast(`✅ Đã xuất thành công ${soLuongDe} mã đề thi kèm file Excel đáp án (.zip)!`, 'success');
                            downloaded = true;
                        }
                    } catch (serverErr) {
                        if (serverErr.message && !serverErr.message.includes('fetch') && !serverErr.message.includes('NetworkError')) {
                            throw serverErr;
                        }
                        console.warn("Server API export failed, switching to client-side generator:", serverErr);
                        useClientFallback = true;
                    }
                }

                // 2. Chế độ tạo tài liệu phía Client (Hỗ trợ định dạng PDF & Word)
                if (useClientFallback && !downloaded) {
                    console.log(`Running client-side ${formatName} & Excel document generator...`);
                    const headerOpts = {
                        soGiaoDuc,
                        truongHoc,
                        deThiTitle,
                        namHoc,
                        monHoc,
                        thoiGian,
                        maDe: baseMaDe
                    };
                    await generateDocxClientSide(targetExamId, headerOpts, soLuongDe, updateProgress, exportFormat);
                }

                setTimeout(() => {
                    closeModal();
                }, 1600);

            } catch(err) {
                console.error('Lỗi khi xuất file Word & Excel:', err);
                showToast('❌ Lỗi khi xuất đề thi: ' + (err.message || err), 'error');
                if (progressStatus) progressStatus.innerText = '❌ Có lỗi xảy ra trong quá trình bốc ngẫu nhiên & xuất đề thi!';
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = originalText;
                }
            }
        };

        async function generateDocxClientSide(targetExamId, headerOpts, soLuongDe, updateProgress, exportFormat = 'docx') {
            // 1. Tìm cấu hình đề thi mục tiêu từ các nguồn bộ nhớ client
            let targetExam = (window.allExamConfigsList || []).find(e => String(e.id) === String(targetExamId));
            if (!targetExam && window.examsList) {
                targetExam = window.examsList.find(e => String(e.id) === String(targetExamId));
            }
            if (!targetExam && examConfig && String(examConfig.id) === String(targetExamId)) {
                targetExam = examConfig;
            }

            // Nếu không có trong bộ nhớ, truy vấn API /api/exams
            if (!targetExam) {
                const token = localStorage.getItem('auth_token') || '';
                try {
                    const res = await fetch(`/api/exams?id=${encodeURIComponent(targetExamId)}`, {
                        headers: token ? { 'Authorization': 'Bearer ' + token } : {}
                    });
                    if (res.ok) {
                        const resJson = await res.json();
                        if (resJson && resJson.data) {
                            targetExam = Array.isArray(resJson.data) ? resJson.data.find(e => String(e.id) === String(targetExamId)) : resJson.data;
                        } else if (Array.isArray(resJson)) {
                            targetExam = resJson.find(e => String(e.id) === String(targetExamId));
                        }
                    }
                } catch(e) {
                    console.warn("Could not fetch exam config by ID, trying full list:", e);
                }

                if (!targetExam) {
                    try {
                        const res = await fetch('/api/exams', { headers: token ? { 'Authorization': 'Bearer ' + token } : {} });
                        if (res.ok) {
                            const resJson = await res.json();
                            const list = resJson.data || resJson.exams || resJson.results || (Array.isArray(resJson) ? resJson : []);
                            targetExam = list.find(e => String(e.id) === String(targetExamId));
                        }
                    } catch(e) {}
                }
            }

            let finalSelectedLessons = targetExam ? (targetExam.selected_lessons || targetExam.selectedLessons || []) : [];
            if (typeof finalSelectedLessons === 'string') {
                try { finalSelectedLessons = JSON.parse(finalSelectedLessons); } catch(e) { finalSelectedLessons = []; }
            }

            let countsDetail = targetExam ? (targetExam.counts_detail || targetExam.countsDetail || {}) : {};
            if (typeof countsDetail === 'string') {
                try { countsDetail = JSON.parse(countsDetail); } catch(e) { countsDetail = {}; }
            }

            let targetCount41 = Number(targetExam?.count_41 || targetExam?.count41 || 0);
            let targetCountTF4 = Number(targetExam?.count_tf4 || targetExam?.countTF4 || 0);
            let targetCountSQ = Number(targetExam?.count_sq || targetExam?.countSQ || 0);
            let targetCountTL = Number(targetExam?.count_tl || targetExam?.countTL || 0);

            const sum41Detail = Number(countsDetail.count41NB || 0) + Number(countsDetail.count41TH || 0) + Number(countsDetail.count41VD || 0);
            if (targetCount41 <= 0 && sum41Detail > 0) targetCount41 = sum41Detail;

            const sumTF4Detail = Number(countsDetail.countTF4NB || 0) + Number(countsDetail.countTF4TH || 0) + Number(countsDetail.countTF4VD || 0);
            if (targetCountTF4 <= 0 && sumTF4Detail > 0) targetCountTF4 = sumTF4Detail;

            const sumSQDetail = Number(countsDetail.countSQNB || 0) + Number(countsDetail.countSQTH || 0) + Number(countsDetail.countSQVD || 0);
            if (targetCountSQ <= 0 && sumSQDetail > 0) targetCountSQ = sumSQDetail;

            const sumTLDetail = Number(countsDetail.countTLNB || 0) + Number(countsDetail.countTLTH || 0) + Number(countsDetail.countTLVD || 0);
            if (targetCountTL <= 0 && sumTLDetail > 0) targetCountTL = sumTLDetail;

            const normalizeLesson = (l) => {
                if (!l) return '';
                return String(l).trim().toLowerCase().replace(/\s+/g, ' ');
            };

            const removeVietnameseTones = (str) => {
                if (!str) return '';
                return str
                    .normalize('NFD')
                    .replace(/[\u0300-\u036f]/g, '')
                    .replace(/đ/g, 'd')
                    .replace(/Đ/g, 'D');
            };

            const normalizeLessonKey = (l) => {
                if (!l) return '';
                return removeVietnameseTones(String(l).trim().toLowerCase())
                    .replace(/[^a-z0-9]/g, ' ')
                    .replace(/\s+/g, ' ')
                    .trim();
            };

            const isLessonMatched = (qLessonRaw, allowedLessons) => {
                if (!allowedLessons || allowedLessons.length === 0) return true;
                const qRaw = String(qLessonRaw || '').trim();
                if (!qRaw) return false;

                const qNorm = normalizeLesson(qRaw);
                const qKey = normalizeLessonKey(qRaw);

                for (const allowed of allowedLessons) {
                    const aRaw = String(allowed || '').trim();
                    if (!aRaw) continue;

                    if (qRaw === aRaw) return true;

                    const aNorm = normalizeLesson(aRaw);
                    if (qNorm === aNorm) return true;

                    const aKey = normalizeLessonKey(aRaw);
                    if (qKey === aKey) return true;
                }
                return false;
            };

            if (!finalSelectedLessons || finalSelectedLessons.length === 0) {
                throw new Error("Đề thi này chưa được chọn Bài học/Chuyên đề trong cấu hình cài đặt. Vui lòng vào cấu hình đề thi và tích chọn ít nhất 1 bài học!");
            }

            // 2. Nạp toàn bộ ngân hàng câu hỏi
            let allQuestions = (questions && questions.length > 0) ? questions : (window.allQuestionsList || window.questionsList || []);
            if (!allQuestions || allQuestions.length === 0) {
                const token = localStorage.getItem('auth_token') || '';
                try {
                    const qRes = await fetch('/api/questions', { headers: token ? { 'Authorization': 'Bearer ' + token } : {} });
                    if (qRes.ok) {
                        const qData = await qRes.json();
                        allQuestions = qData.data || qData.questions || qData.results || (Array.isArray(qData) ? qData : []);
                    }
                } catch(e) {
                    console.error("Lỗi khi tải danh sách câu hỏi:", e);
                }
            }

            const normalizeType = (type) => {
                const t = String(type || '').trim().toLowerCase();
                if (t === '4-1' || t === 'trac_nghiem' || t === 'mcq') return '4-1';
                if (t === 'tf4' || t === 'dung_sai' || t === 'true_false') return 'TF4';
                if (t === 'sq' || t === 'tra_loi_ngan' || t === 'short_answer') return 'SQ';
                if (t === 'tl' || t === 'tu_luan' || t === 'essay') return 'TL';
                return type;
            };

            const normalizeLevel = (lvl) => {
                const l = String(lvl || '').trim().toUpperCase();
                if (l === 'NB' || l === 'TH' || l === 'VD') return l;
                return 'NB';
            };

            const seenIds = new Set();
            const allMappedQuestions = allQuestions
                .filter(q => {
                    const qId = String(q.id || '');
                    if (!qId || seenIds.has(qId)) return false;

                    const contentStr = String(q.content || '').trim();
                    if (!contentStr) return false;

                    seenIds.add(qId);
                    return true;
                })
                .map(q => {
                    let opts = q.options || {};
                    if (typeof opts === 'string') {
                        try { opts = JSON.parse(opts); } catch(e) { opts = {}; }
                    }
                    return {
                        id: q.id,
                        type: normalizeType(q.type),
                        level: normalizeLevel(q.level),
                        lesson: q.lesson,
                        content: q.content,
                        options: opts,
                        answer: q.answer,
                        image: q.image || ''
                    };
                })
                .filter(q => {
                    if (q.type === '4-1') {
                        const opts = q.options || {};
                        let hasOpt = false;
                        if (Array.isArray(opts)) {
                            hasOpt = opts.some(v => v !== null && v !== undefined && String(typeof v === 'object' ? (v.text || v.content || '') : v).trim().length > 0);
                        } else if (typeof opts === 'object') {
                            hasOpt = Object.values(opts).some(v => v !== null && v !== undefined && String(typeof v === 'object' ? (v.text || v.content || '') : v).trim().length > 0);
                        }
                        if (!hasOpt) return false;
                    }
                    return true;
                });

            if (allMappedQuestions.length === 0) {
                throw new Error("Ngân hàng câu hỏi hiện đang trống. Vui lòng thêm câu hỏi vào ngân hàng trước khi xuất đề!");
            }

            const validPool = allMappedQuestions.filter(q => isLessonMatched(q.lesson, finalSelectedLessons));
            if (validPool.length === 0) {
                throw new Error(`Không tìm thấy câu hỏi nào thuộc bài học (${finalSelectedLessons.join(', ')}) trong ngân hàng đề!`);
            }

            const totalRequired = targetCount41 + targetCountTF4 + targetCountSQ + targetCountTL;
            if (totalRequired === 0) {
                throw new Error("Cấu hình đề thi chưa có số lượng câu hỏi nào (> 0)!");
            }

            const shuffle = (arr) => [...arr].sort(() => Math.random() - 0.5);

            function formatNextMaDe(baseStr, index) {
                if (index === 0) return baseStr;
                const match = baseStr.match(/^(.*?)(\d+)$/);
                if (match) {
                    const prefix = match[1];
                    const digits = match[2];
                    const nextVal = Number(digits) + index;
                    const nextDigitsStr = String(nextVal).padStart(digits.length, '0');
                    return prefix + nextDigitsStr;
                }
                return baseStr + "_" + (index + 1);
            }

            const generatedFiles = [];
            const examAnswerDocs = [];
            const baseMaDe = headerOpts.maDe || '1201';
            const isPdfFormat = exportFormat === 'pdf';

            for (let v = 0; v < soLuongDe; v++) {
                const currentMaDe = formatNextMaDe(baseMaDe, v);
                const startPercent = Math.round((v / soLuongDe) * 80);
                if (updateProgress) updateProgress(startPercent, `Đang bốc ngẫu nhiên câu hỏi & tạo đề thi mã đề ${currentMaDe}...`, `Đã xong ${v} / ${soLuongDe} đề`);

                const selectedQuestions = [];

                const pickCategory = (type, typeLabel, targetCount, nbTarget, thTarget, vdTarget) => {
                    if (targetCount <= 0) return;
                    const pool = validPool.filter(q => q.type === type);
                    if (pool.length < targetCount) {
                        throw new Error(`Ngân hàng đề không đủ câu hỏi [${typeLabel}] trong bài học đã chọn (${finalSelectedLessons.join(', ')})! Yêu cầu: ${targetCount} câu, nhưng chỉ có sẵn ${pool.length} câu.`);
                    }

                    const sumSub = (nbTarget || 0) + (thTarget || 0) + (vdTarget || 0);
                    if (sumSub > 0) {
                        const nbPool = shuffle(pool.filter(q => q.level === 'NB'));
                        const thPool = shuffle(pool.filter(q => q.level === 'TH'));
                        const vdPool = shuffle(pool.filter(q => q.level === 'VD'));

                        const pickedNB = nbPool.slice(0, nbTarget || 0);
                        const pickedTH = thPool.slice(0, thTarget || 0);
                        const pickedVD = vdPool.slice(0, vdTarget || 0);

                        const pickedSoFar = [...pickedNB, ...pickedTH, ...pickedVD];
                        const pickedIds = new Set(pickedSoFar.map(q => q.id));

                        if (pickedSoFar.length < targetCount) {
                            const remaining = shuffle(pool.filter(q => !pickedIds.has(q.id)));
                            const needed = targetCount - pickedSoFar.length;
                            pickedSoFar.push(...remaining.slice(0, needed));
                        }

                        if (pickedSoFar.length < targetCount) {
                            throw new Error(`Không đủ câu hỏi [${typeLabel}] để đáp ứng cấu hình đề! Cần ${targetCount} câu, chỉ bốc được ${pickedSoFar.length} câu.`);
                        }

                        selectedQuestions.push(...pickedSoFar);
                    } else {
                        selectedQuestions.push(...shuffle(pool).slice(0, targetCount));
                    }
                };

                pickCategory('4-1', 'Trắc nghiệm 4 lựa chọn', targetCount41, Number(countsDetail.count41NB || 0), Number(countsDetail.count41TH || 0), Number(countsDetail.count41VD || 0));
                pickCategory('TF4', 'Đúng - Sai', targetCountTF4, Number(countsDetail.countTF4NB || 0), Number(countsDetail.countTF4TH || 0), Number(countsDetail.countTF4VD || 0));
                pickCategory('SQ', 'Trả lời ngắn', targetCountSQ, Number(countsDetail.countSQNB || 0), Number(countsDetail.countSQTH || 0), Number(countsDetail.countSQVD || 0));
                pickCategory('TL', 'Tự luận', targetCountTL, Number(countsDetail.countTLNB || 0), Number(countsDetail.countTLTH || 0), Number(countsDetail.countTLVD || 0));

                if (selectedQuestions.length !== totalRequired) {
                    throw new Error(`Số lượng câu hỏi bốc được (${selectedQuestions.length} câu) không khớp với cấu hình đề thi (${totalRequired} câu)!`);
                }

                const currentHeader = { ...headerOpts, maDe: currentMaDe };
                
                // Yield lượt vẽ cho trình duyệt để đảm bảo giao diện cuộn mượt mà, không bị đơ
                await new Promise(resolve => setTimeout(resolve, 80));

                let docBlob, fileExt;
                if (isPdfFormat) {
                    docBlob = await generateExamPdfBlob(currentHeader, selectedQuestions);
                    fileExt = 'pdf';
                } else {
                    docBlob = await generateExamDocx(currentHeader, selectedQuestions);
                    fileExt = 'docx';
                }

                const safeFileName = `De_Thi_${headerOpts.deThiTitle.replace(/[^a-zA-Z0-9_\u00C0-\u1EF9]/g, '_')}_MaDe_${currentMaDe}.${fileExt}`;

                generatedFiles.push({
                    maDe: currentMaDe,
                    fileName: safeFileName,
                    blob: docBlob
                });

                examAnswerDocs.push({
                    maDe: currentMaDe,
                    questions: selectedQuestions
                });

                const endPercent = Math.round(((v + 1) / soLuongDe) * 80);
                if (updateProgress) updateProgress(endPercent, `✅ Đã bốc ngẫu nhiên & tạo thành công mã đề ${currentMaDe} (${isPdfFormat ? 'PDF' : 'Word'})`, `Đã xong ${v + 1} / ${soLuongDe} đề`);
            }

            // 3. Tạo file Excel Bảng đáp án tổng hợp theo các cột mã đề thi
            if (updateProgress) updateProgress(85, `📊 Đang khởi tạo file Excel bảng đáp án theo từng mã đề...`, `${soLuongDe} / ${soLuongDe} đề`);
            const excelHeaderInfo = {
                deThiTitle: headerOpts.deThiTitle || 'ĐỀ KIỂM TRA',
                soGiaoDuc: headerOpts.soGiaoDuc || "SỞ GIÁO DỤC VÀ ĐÀO TẠO",
                truongHoc: headerOpts.truongHoc || "TRƯỜNG THPT",
                monHoc: headerOpts.monHoc || (finalSelectedLessons.length > 0 ? `MÔN ${finalSelectedLessons[0].toUpperCase()}` : "MÔN TIN HỌC, LỚP 12"),
                namHoc: headerOpts.namHoc || "NĂM HỌC 2026 - 2027",
                thoiGian: headerOpts.thoiGian || 45
            };
            const excelBuffer = generateExamAnswerExcel(excelHeaderInfo, examAnswerDocs);
            const excelBlob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

            const startCode = generatedFiles[0].maDe;
            const endCode = generatedFiles[generatedFiles.length - 1].maDe;
            const excelFileName = soLuongDe === 1
                ? `Bang_Dap_An_MaDe_${startCode}.xlsx`
                : `Bang_Dap_An_Tong_Hop_Cac_Ma_De_${startCode}_den_${endCode}.xlsx`;

            // 4. Đóng gói toàn bộ file Word/PDF và file Excel đáp án vào file .ZIP
            const fileTypeName = isPdfFormat ? 'PDF' : 'Word';
            if (updateProgress) updateProgress(92, `📦 Đang nén các file ${fileTypeName} và file Excel đáp án vào file .ZIP...`, `${soLuongDe} / ${soLuongDe} đề`);
            const zip = new JSZip();
            for (const doc of generatedFiles) {
                zip.file(doc.fileName, doc.blob);
            }
            zip.file(excelFileName, excelBlob);

            const zipBlob = await zip.generateAsync({ type: 'blob' }, (metadata) => {
                if (metadata.percent && updateProgress) {
                    const zipPercent = 92 + Math.round((metadata.percent / 100) * 8);
                    updateProgress(zipPercent, `📦 Đang đóng gói file .ZIP (${Math.round(metadata.percent)}%)...`, `${soLuongDe} / ${soLuongDe} đề`);
                }
            });

            const safeTitle = (headerOpts.deThiTitle || 'De_Thi').replace(/[^a-zA-Z0-9_\u00C0-\u1EF9]/g, '_');
            const zipFileName = soLuongDe === 1
                ? `De_Thi_kem_Dap_An_${safeTitle}_MaDe_${startCode}.zip`
                : `Bo_De_Thi_${safeTitle}_Gom_${soLuongDe}_MaDe_${startCode}_den_${endCode}_kem_Dap_An.zip`;

            if (typeof saveAs === 'function') {
                saveAs(zipBlob, zipFileName);
            } else if (window.saveAs) {
                window.saveAs(zipBlob, zipFileName);
            } else {
                const downloadUrl = URL.createObjectURL(zipBlob);
                const a = document.createElement('a');
                a.href = downloadUrl;
                a.download = zipFileName;
                document.body.appendChild(a);
                a.click();
                setTimeout(() => {
                    document.body.removeChild(a);
                    URL.revokeObjectURL(downloadUrl);
                }, 500);
            }

            if (updateProgress) updateProgress(100, `🎉 Hoàn tất! Đã tải về thành công bộ ${soLuongDe} đề thi ${fileTypeName} kèm file Excel đáp án`, `${soLuongDe} / ${soLuongDe} đề`);
            showToast(`✅ Đã bốc ngẫu nhiên và xuất thành công bộ ${soLuongDe} mã đề thi ${fileTypeName} kèm file Excel đáp án (.zip)!`, 'success');

            return generatedFiles;
        }

        async function fetchAllExamsChunked(onProgress) {
            const token = localStorage.getItem('auth_token') || '';
            const chunkSize = 1000;
            let offset = 0;
            let allExams = [];
            let hasMore = true;
            let pageNum = 1;

            while (hasMore) {
                if (typeof onProgress === 'function') {
                    onProgress(allExams.length, pageNum, false);
                }
                const url = `/api/exams?limit=${chunkSize}&offset=${offset}`;
                const res = await fetch(url, {
                    headers: token ? { 'Authorization': 'Bearer ' + token } : {}
                });
                if (!res.ok) {
                    throw new Error(`Lỗi máy chủ (${res.status}) khi tải danh sách đề thi tại đợt ${pageNum}`);
                }
                const contentType = res.headers.get("content-type");
                let json;
                if (contentType && contentType.includes("application/json")) {
                    json = await res.json();
                } else {
                    throw new Error("Server returned non-JSON response. Status: " + res.status);
                }
                const chunk = (json && Array.isArray(json.data)) ? json.data : [];

                if (chunk.length > 0) {
                    allExams.push(...chunk);
                }

                const hasMoreFromApi = (json.has_more !== undefined) ? json.has_more : (chunk.length >= chunkSize);
                if (chunk.length < chunkSize || hasMoreFromApi === false || chunk.length === 0) {
                    hasMore = false;
                } else {
                    offset += chunkSize;
                    pageNum++;
                    if (pageNum > 100) {
                        console.warn('Đã đạt giới hạn an toàn 100 đợt tải (100,000 đề thi)');
                        break;
                    }
                }
            }

            if (typeof onProgress === 'function') {
                onProgress(allExams.length, pageNum, true);
            }
            return allExams;
        }
        window.fetchAllExamsChunked = fetchAllExamsChunked;

        async function updateExamNamesList(preserveSelection = false, onProgress = null) {
            console.log('updateExamNamesList called, currentUser:', currentUser, 'isAdmin:', isAdminLoggedIn, 'isTeacher:', isTeacherLoggedIn);
            if (!currentUser) {
                console.warn('updateExamNamesList: currentUser missing');
                return;
            }
            
            try {
                const data = await fetchAllExamsChunked(onProgress);
                console.log('✅ Exam names loaded:', data.length, 'items');
                window.allExamConfigsList = data;
                renderExamConfigsTable();

                const select = document.getElementById('exam-config-name');
                if (select) {
                    const currentVal = preserveSelection ? select.value : '';
                    select.innerHTML = '<option value="">Chọn đề thi có sẵn</option>';
                    
                    if (data && data.length > 0) {
                        data.forEach(d => {
                            const name = d.name;
                            const opt = document.createElement('option');
                            opt.value = d.id;
                            opt.dataset.name = name;
                            opt.textContent = name;
                            select.appendChild(opt);
                        });
                        
                        if (preserveSelection && currentVal && Array.from(select.options).some(o => o.value === currentVal || o.dataset.name === currentVal)) {
                            const matchedOpt = Array.from(select.options).find(o => o.value === currentVal) || 
                                               Array.from(select.options).find(o => o.dataset.name === currentVal);
                            select.value = matchedOpt ? matchedOpt.value : "";
                        } else {
                            select.value = "";
                        }
                    } else {
                        select.value = "";
                    }
                }
                examsLoaded = true;
            } catch (e) { 
                console.warn('⚠️ Error updating exam names list:', e); 
            }
        }

        window.deleteExamConfig = async function deleteExamConfig(explicitId = null, explicitName = null) {
            const selectEl = document.getElementById('exam-config-name');
            const selectedId = explicitId || selectEl?.value?.trim();
            if (!selectedId || !currentUser) {
                showToast('Vui lòng chọn đề thi cần xóa!', 'warning');
                return;
            }
            
            const name = explicitName || selectEl?.options[selectEl.selectedIndex]?.dataset.name || "Đề thi";
            
            showConfirmModal(`Bạn có chắc chắn muốn xóa đề thi "${name}" không?`, async () => {
                try {
                    const token = localStorage.getItem('auth_token') || '';
                    const res = await fetch(`/api/exams?id=${encodeURIComponent(selectedId)}`, {
                        method: 'DELETE',
                        headers: { 'Authorization': 'Bearer ' + token }
                    });
                    let resJson;
                    const contentType = res.headers.get("content-type");
                    if (contentType && contentType.includes("application/json")) {
                        resJson = await res.json();
                    } else {
                        throw new Error("Server returned non-JSON response (likely 502/504 during restart). Status: " + res.status);
                    }
                    
                    if (!res.ok || resJson.error) {
                        throw new Error(resJson.error || 'Lỗi khi xóa đề thi');
                    }
                    
                    showToast(`🗑️ Đã xóa đề thi: ${name}`, 'success');
                    
                    // Reset UI và load lại danh sách
                    resetExamPanelToDefault();
                    examsLoaded = false;
                    await updateExamNamesList(false);
                    closeModal(); // Đóng modal sau khi xóa thành công
                } catch (e) {
                    console.error('Error deleting exam config:', e);
                    showToast('Lỗi khi xóa đề thi! (Bạn có thể không có quyền xóa đề này)', 'error');
                }
            });
        }

        async function onExamNameChange() {
            const selectEl = document.getElementById('exam-config-name');
            const selectedId = selectEl?.value?.trim();
            if (!selectedId) {
                // Clear all exam configurations UI when the default value is selected
                resetExamPanelToDefault();
                return;
            }
            if (!currentUser) return;
            
            const name = selectEl.options[selectEl.selectedIndex]?.dataset.name || "Đề thi";
            
            try {
                const token = localStorage.getItem('auth_token') || '';
                const res = await fetch(`/api/exams?id=${encodeURIComponent(selectedId)}`, {
                    headers: { 'Authorization': 'Bearer ' + token }
                });
                let resJson;
const contentType = res.headers.get("content-type");
if (contentType && contentType.includes("application/json")) {
    resJson = await res.json();
} else {
    throw new Error("Server returned non-JSON response (likely 502/504 during restart). Status: " + res.status);
}
                
                if (res.ok && resJson.data) {
                    applyExamConfig(resJson.data);
                    showToast(`📂 Đã tải cấu hình đề: ${name}`, 'success');
                }
            } catch (e) { 
                console.error('Error in onExamNameChange:', e);
            }
        }

        function renderSharedTeachersSelect() {
            const select = document.getElementById('exam-shared-teachers');
            if (!select) return;
            
            if (!accounts || accounts.length === 0) {
                select.innerHTML = '<option value="" disabled>-- Đang tải danh sách tài khoản... --</option>';
                return;
            }

            select.innerHTML = '';
            // Lọc ra các tài khoản là Giáo viên hoặc Admin (trừ chính mình)
            // Cải tiến: Lấy tất cả tài khoản KHÔNG phải là "Học sinh" để đảm bảo không bỏ sót giáo viên
            const availableAccounts = accounts.filter(a => {
                const aid = String(a.id || '');
                const cid = String(currentUser?.id || '');
                if (!aid || aid === cid) return false;
                
                const target = String(a.target_audience || '').toLowerCase();
                const role = String(a.role || '').toLowerCase();
                
                return role === 'admin' || (target !== 'học sinh' && target !== 'hoc sinh');
            });

            if (availableAccounts.length === 0) {
                const opt = document.createElement('option');
                opt.value = "";
                opt.textContent = "-- Không có giáo viên khác để chọn --";
                opt.disabled = true;
                select.appendChild(opt);
                return;
            }

            availableAccounts.forEach(acc => {
                const opt = document.createElement('option');
                opt.value = acc.id;
                const roleMark = acc.role === 'admin' ? '[Admin] ' : '';
                opt.textContent = `${roleMark}${acc.full_name || acc.username} (${acc.username})`;
                select.appendChild(opt);
            });
        }

        function applyExamConfig(cData) {
            let parsedLessons = cData.selected_lessons || [];
            if (typeof parsedLessons === 'string') {
                try { parsedLessons = JSON.parse(parsedLessons); } catch(e) { parsedLessons = []; }
            }
            
            let parsedCountsDetail = cData.counts_detail || {};
            if (typeof parsedCountsDetail === 'string') {
                try { parsedCountsDetail = JSON.parse(parsedCountsDetail); } catch(e) { parsedCountsDetail = {}; }
            }
            
            let parsedAccessControl = cData.access_control || {};
            if (typeof parsedAccessControl === 'string') {
                try { parsedAccessControl = JSON.parse(parsedAccessControl); } catch(e) { parsedAccessControl = {}; }
            }

            cData.selected_lessons = parsedLessons;
            cData.counts_detail = parsedCountsDetail;
            cData.access_control = parsedAccessControl;

            examConfig = {
                ...examConfig, 
                id: cData.id,
                name: cData.name, 
                creatorId: cData.creator_id,
                creatorName: accounts.find(a => a.id === cData.creator_id)?.full_name || accountsMap[cData.creator_id] || 'Người dùng hệ thống', 
                chedodethi: cData.chedodethi || 'Đề công khai',
                mabaomatdethi: cData.mabaomatdethi || '',
                timeLimit: cData.time_limit, 
                count41: cData.count_41, 
                countTF4: cData.count_tf4, 
                countSQ: cData.count_sq, 
                count41NB: cData.counts_detail?.count41NB || 0, 
                count41TH: cData.counts_detail?.count41TH || 0, 
                count41VD: cData.counts_detail?.count41VD || 0, 
                countTF4NB: cData.counts_detail?.countTF4NB || 0, 
                countTF4TH: cData.counts_detail?.countTF4TH || 0, 
                countTF4VD: cData.counts_detail?.countTF4VD || 0, 
                countSQNB: cData.counts_detail?.countSQNB || 0, 
                countSQTH: cData.counts_detail?.countSQTH || 0, 
                countSQVD: cData.counts_detail?.countSQVD || 0, 
                countTL: cData.count_tl || 0,
                countTLNB: cData.counts_detail?.countTLNB || 0,
                countTLTH: cData.counts_detail?.countTLTH || 0,
                countTLVD: cData.counts_detail?.countTLVD || 0,
                creatorId: cData.creator_id || cData.counts_detail?.creatorId || null, 
                selectedLessons: cData.selected_lessons || [], 
                aiPrompt: cData.ai_prompt || '',
                aiGradingKey: cData.ai_grading_key || '',
                points41: parseFloat(cData.points_41 || 1), 
                pointsTF4: parseFloat(cData.points_tf4 || 1), 
                pointsSQ: parseFloat(cData.points_sq || 1), 
                pointsTL: parseFloat(cData.points_tl || 1), 
                tf4ScoringMode: cData.tf4_scoring_mode, 
                tf4Points: cData.tf4_points || examConfig.tf4Points, 
                immediateFeedback: Boolean(cData.immediate_feedback == 1 || cData.immediate_feedback === true || cData.immediate_feedback === '1' || cData.immediateFeedback == 1 || cData.immediateFeedback === true),
                sqCaseSensitive: cData.sq_case_sensitive !== undefined ? cData.sq_case_sensitive : false,
                sqPunctuationSensitive: cData.sq_punctuation_sensitive !== undefined ? cData.sq_punctuation_sensitive : false,
                autoGradeEssay: cData.auto_grade_essay !== undefined ? cData.auto_grade_essay : false,
                showScore: cData.show_score !== undefined ? cData.show_score : true,
                showDetails: cData.show_details !== undefined ? cData.show_details : true,
                isSharedResults: (cData.is_shared_results === true || cData.is_shared_results === 1 || cData.is_shared_results === 'true'),
                maxCheatWarnings: (typeof cData.max_cheat_warnings === 'number' && cData.max_cheat_warnings > 0) ? cData.max_cheat_warnings : ((typeof cData.maxCheatWarnings === 'number' && cData.maxCheatWarnings > 0) ? cData.maxCheatWarnings : 5),
                maxAttempts: (cData.max_attempts !== undefined && cData.max_attempts !== null) ? Number(cData.max_attempts) : ((cData.maxAttempts !== undefined && cData.maxAttempts !== null) ? Number(cData.maxAttempts) : 0),
                max_attempts: (cData.max_attempts !== undefined && cData.max_attempts !== null) ? Number(cData.max_attempts) : ((cData.maxAttempts !== undefined && cData.maxAttempts !== null) ? Number(cData.maxAttempts) : 0),
                accessControl: {
                    enabled: cData.access_control?.enabled || (cData.tg_bd || cData.tg_kt ? true : false),
                    startTime: cData.tg_bd || cData.access_control?.startTime || '',
                    endTime: cData.tg_kt || cData.access_control?.endTime || ''
                }
            };
            // Cập nhật UI: chỉ gán giá trị vào select exam-config-name khi đang ở tab quản lý đề thi của giáo viên/admin
            const examConfigSelect = document.getElementById('exam-config-name');
            if (examConfigSelect && (isTeacherLoggedIn || isAdminLoggedIn)) {
                const activeTab = document.querySelector('.tab-content.active')?.id;
                if (activeTab === 'tab-exams') {
                    examConfigSelect.value = examConfig.id || '';
                }
            }
            const newExamInput = document.getElementById('new-exam-name');
            if (newExamInput) newExamInput.value = '';
            
            const cbShared = document.getElementById('exam-config-shared-results');
            if (cbShared) {
                cbShared.checked = examConfig.isSharedResults;
                document.getElementById('shared-code-container')?.classList.toggle('hidden', !examConfig.isSharedResults);
                
                const codeInput = document.getElementById('exam-shared-code');
                if (codeInput) {
                    if (codeInput) codeInput.value = examConfig.id || '';
                }
            }

            if (document.getElementById('exam-config-time')) document.getElementById('exam-config-time').value = examConfig.timeLimit;
            if (document.getElementById('exam-config-max-cheat-warnings')) document.getElementById('exam-config-max-cheat-warnings').value = examConfig.maxCheatWarnings || 5;
            if (document.getElementById('exam-config-max-attempts')) document.getElementById('exam-config-max-attempts').value = examConfig.maxAttempts || 0;
            if (document.getElementById('exam-config-mode')) document.getElementById('exam-config-mode').value = examConfig.chedodethi;
            if (document.getElementById('exam-config-password')) document.getElementById('exam-config-password').value = examConfig.mabaomatdethi || '';
            
            if (currentUser && currentUser.role !== 'admin' && (examConfig.chedodethi === 'Đề cho đơn vị' || examConfig.chedodethi === 'Đề thi cho đơn vị')) {
                const teacherDonvi = String(currentUser.donvi || currentUser.address || '').trim();
                examConfig.target_donvi = teacherDonvi;
                examConfig.donvi = teacherDonvi;
            } else {
                examConfig.target_donvi = cData.target_donvi || cData.targetDonvi || cData.donvi || '';
                examConfig.donvi = examConfig.target_donvi;
            }
            examConfig.target_lop = cData.target_lop || cData.targetLop || cData.lop || '';
            examConfig.targetLop = examConfig.target_lop;
            examConfig.lop = examConfig.target_lop;

            // QUY TẮC: Nếu đề thi ở chế độ là Đề công khai thì ô đơn vị và ô lớp xóa rỗng
            if (examConfig.chedodethi === 'Đề công khai' || !examConfig.chedodethi) {
                examConfig.target_donvi = '';
                examConfig.donvi = '';
                examConfig.target_lop = '';
                examConfig.targetLop = '';
                examConfig.lop = '';
            }

            const donviEl = document.getElementById('exam-config-donvi');
            if (donviEl) {
                donviEl.value = examConfig.target_donvi;
                if (currentUser && currentUser.role !== 'admin' && (examConfig.chedodethi === 'Đề cho đơn vị' || examConfig.chedodethi === 'Đề thi cho đơn vị')) {
                    donviEl.readOnly = true;
                    donviEl.disabled = true;
                    donviEl.classList.add('bg-gray-100', 'cursor-not-allowed');
                } else {
                    donviEl.readOnly = false;
                    donviEl.disabled = false;
                    donviEl.classList.remove('bg-gray-100', 'cursor-not-allowed');
                }
            }
            if (document.getElementById('exam-config-lop')) document.getElementById('exam-config-lop').value = examConfig.target_lop;
            
            // Cập nhật bộ lọc giáo viên nếu đề thi này của người khác chia sẻ
            const teacherFilter = document.getElementById('exam-teacher-filter');
            if (teacherFilter && examConfig.creatorId && String(examConfig.creatorId) !== String(currentUser?.id)) {
                // Nếu chưa có trong danh sách thì thêm vào tạm thời
                let exists = Array.from(teacherFilter.options).some(opt => String(opt.value) === String(examConfig.creatorId));
                if (!exists) {
                    const opt = document.createElement('option');
                    opt.value = examConfig.creatorId;
                    opt.textContent = accountsMap[examConfig.creatorId] || `Người tạo đề (${examConfig.creatorId})`;
                    teacherFilter.appendChild(opt);
                }
                if (teacherFilter) teacherFilter.value = examConfig.creatorId;
            } else if (teacherFilter && currentUser) {
                if (teacherFilter) teacherFilter.value = currentUser.id;
            }

            toggleExamMode();
            if (document.getElementById('exam-count-41-nb')) document.getElementById('exam-count-41-nb').value = examConfig.count41NB;
            if (document.getElementById('exam-count-41-th')) document.getElementById('exam-count-41-th').value = examConfig.count41TH;
            if (document.getElementById('exam-count-41-vd')) document.getElementById('exam-count-41-vd').value = examConfig.count41VD;
            if (document.getElementById('exam-count-tf4-nb')) document.getElementById('exam-count-tf4-nb').value = examConfig.countTF4NB;
            if (document.getElementById('exam-count-tf4-th')) document.getElementById('exam-count-tf4-th').value = examConfig.countTF4TH;
            if (document.getElementById('exam-count-tf4-vd')) document.getElementById('exam-count-tf4-vd').value = examConfig.countTF4VD;
            if (document.getElementById('exam-count-sq-nb')) document.getElementById('exam-count-sq-nb').value = examConfig.countSQNB;
            if (document.getElementById('exam-count-sq-th')) document.getElementById('exam-count-sq-th').value = examConfig.countSQTH;
            if (document.getElementById('exam-count-sq-vd')) document.getElementById('exam-count-sq-vd').value = examConfig.countSQVD;
            
            if (document.getElementById('exam-count-tl-nb')) document.getElementById('exam-count-tl-nb').value = examConfig.countTLNB || 0;
            if (document.getElementById('exam-count-tl-th')) document.getElementById('exam-count-tl-th').value = examConfig.countTLTH || 0;
            if (document.getElementById('exam-count-tl-vd')) document.getElementById('exam-count-tl-vd').value = examConfig.countTLVD || 0;
            
            if (document.getElementById('exam-points-41')) document.getElementById('exam-points-41').value = examConfig.points41;
            if (document.getElementById('exam-points-tf4')) document.getElementById('exam-points-tf4').value = examConfig.pointsTF4;
            if (document.getElementById('exam-points-sq')) document.getElementById('exam-points-sq').value = examConfig.pointsSQ;
            if (document.getElementById('exam-points-tl')) document.getElementById('exam-points-tl').value = examConfig.pointsTL || 1;
            
            const elAIPrompt = document.getElementById('exam-config-ai-prompt');
            if (elAIPrompt) elAIPrompt.value = examConfig.aiPrompt || '';
            const elAIGradingKey = document.getElementById('exam-config-ai-grading-key');
            if (elAIGradingKey) {
                if (elAIGradingKey) elAIGradingKey.value = examConfig.aiGradingKey || '';
                // Xóa trạng thái check cũ nếu có
                const statusEl = document.getElementById('ai-key-status');
                const msgEl = document.getElementById('ai-key-msg');
                if (statusEl) statusEl.classList.add('hidden');
                if (msgEl) msgEl.classList.add('hidden');
                elAIGradingKey.classList.remove('border-green-500', 'border-red-500');
                
                // Nếu có key sẵn thì validate luôn
                if (examConfig.aiGradingKey && examConfig.aiGradingKey.trim().length > 5) {
                    window.validateAIGradingKey(examConfig.aiGradingKey);
                }
            }

            if (document.getElementById('exam-access-enabled')) document.getElementById('exam-access-enabled').checked = examConfig.accessControl.enabled;
            if (document.getElementById('exam-access-start')) document.getElementById('exam-access-start').value = examConfig.accessControl.startTime;
            if (document.getElementById('exam-access-end')) document.getElementById('exam-access-end').value = examConfig.accessControl.endTime;

            const elSQCaseConfig = document.getElementById('exam-config-sq-case-sensitive');
            if (elSQCaseConfig) elSQCaseConfig.checked = examConfig.sqCaseSensitive;

            const elSQPunctConfig = document.getElementById('exam-config-sq-punctuation-sensitive');
            if (elSQPunctConfig) elSQPunctConfig.checked = examConfig.sqPunctuationSensitive;

            const elImmediateFeedback = document.getElementById('exam-config-immediate-feedback');
            if (elImmediateFeedback) elImmediateFeedback.checked = examConfig.immediateFeedback;

            const elAutoGradeEssay = document.getElementById('exam-config-auto-grade-essay');
            if (elAutoGradeEssay) {
                elAutoGradeEssay.checked = !!examConfig.autoGradeEssay;
                const container = document.getElementById('ai-grading-key-container');
                if (container) container.classList.toggle('hidden', !elAutoGradeEssay.checked);
                updateAIGradingKeyLabel();
            }
            
            const elShowScore = document.getElementById('exam-config-show-score');
            if (elShowScore) elShowScore.checked = examConfig.showScore;
            
            const elShowDetails = document.getElementById('exam-config-show-details');
            if (elShowDetails) elShowDetails.checked = examConfig.showDetails;
            
            toggleAccessControl();
            updateAvailableCounts();
            renderLessonCheckboxes();
            updateExamCounts();
            updatePointsPreview();
            updateCurrentExamInfo();
            const btnExport = document.getElementById('btn-export-exam-docx');
            if (btnExport) btnExport.classList.remove('hidden');
        }

        function updateExamTeacherFilter() {
            const select = document.getElementById('exam-teacher-filter');
            if (!select) return;
            
            const currentVal = select.value;
            while (select.options.length > 1) {
                select.remove(1);
            }
            
            let creatorIds = [...new Set(questions.map(q => q.creatorId).filter(id => id))];
            
            // Nếu là giáo viên, CHỈ lọc chính mình
            if (currentUser && isTeacherLoggedIn && !isAdminLoggedIn) {
                const myId = String(currentUser.id);
                creatorIds = [myId];
                
                // Khóa select vì giáo viên không được xem đề của người khác
                select.disabled = true;
            } else {
                select.disabled = false;
                // Luôn thêm admin/gv hiện tại vào danh sách lọc nếu chưa có
                if (currentUser && (isAdminLoggedIn || isTeacherLoggedIn) && !creatorIds.map(String).includes(String(currentUser.id))) {
                    creatorIds.push(currentUser.id);
                }
            }
            
            const teachers = accounts.filter(acc => creatorIds.map(String).includes(String(acc.id)));
            
            teachers.forEach(t => {
                const opt = document.createElement('option');
                opt.value = t.id;
                opt.textContent = t.full_name || t.username;
                select.appendChild(opt);
            });
            
            if (currentVal && Array.from(select.options).some(o => o.value === currentVal)) {
                select.value = currentVal;
            } else if (isTeacherLoggedIn && !isAdminLoggedIn) {
                select.value = currentUser.id;
            }
        }

        function onExamTeacherFilterChange() {
            renderLessonCheckboxes();
            updateAvailableCounts();
        }

        window._studentTeacherChangeSeq = 0;
        window.onStudentTeacherFilterChange = async function onStudentTeacherFilterChange() {
            const currentTeacherSeq = ++window._studentTeacherChangeSeq;
            console.log('onStudentTeacherFilterChange called, seq:', currentTeacherSeq);
            
            const elTeacher = document.getElementById('student-teacher-filter');
            const teacherId = elTeacher ? elTeacher.value : '';
            const examSelect = document.getElementById('student-exam-name-filter');
            if (!examSelect) return;
            
            // Xóa danh sách cũ và hiển thị trạng thái đang tải
            examSelect.innerHTML = '<option value="">Đang tải danh sách đề thi...</option>';
            examSelect.disabled = true;

            // QUY TẮC SỐNG CÒN: XÓA TOÀN BỘ DỮ LIỆU CŨ KHI CHUYỂN GIÁO VIÊN
            // Giải quyết mâu thuẫn: Tránh nhầm lẫn dữ liệu giữa các giáo viên khác nhau
            if (examConfig) {
                examConfig.id = null; // BẮT BUỘC XÓA ID CŨ ĐỂ TRÁNH LỆCH ĐỀ
                examConfig.creatorId = '';
                examConfig.name = '';
                examConfig.chedodethi = 'Đề công khai';
                examConfig.mabaomatdethi = '';
                examConfig.timeLimit = 0;
                examConfig.count41 = 0;
                examConfig.countTF4 = 0;
                examConfig.countSQ = 0;
                examConfig.countTL = 0;
                examConfig.selectedLessons = [];
                examConfig.access_control = null;
                examConfig.tg_bd = null;
                examConfig.tg_kt = null;
            }
            questions = []; // Xóa sạch danh sách câu hỏi trong bộ nhớ
            questionsLoaded = false;
            window.examAvailableCounts = null;
            
            // Reset trạng thái bài thi về ban đầu nếu đang ở tab làm bài
            if (typeof resetExam === 'function') {
                resetExam();
            }
            
            if (!teacherId) {
                examSelect.innerHTML = '<option value="">Chọn Bộ Câu hỏi/Đề thi</option>';
                // we keep it disabled if no teacher is chosen
                updateCurrentExamInfo();
                return;
            }

            try {
                // QUY TẮC SỐNG CÒN: Chỉ lấy đề thi do CHÍNH giáo viên này tạo ra
                // Tuyệt đối không cho phép chia sẻ đề thi ở Tab này
                const token = localStorage.getItem('auth_token') || '';
                const res = await fetch(`/api/exams?teacherId=${encodeURIComponent(teacherId)}`, {
                    headers: token ? { 'Authorization': 'Bearer ' + token } : {}
                });
                if (currentTeacherSeq !== window._studentTeacherChangeSeq) {
                    return; // Đã có thao tác chọn giáo viên mới hơn, bỏ qua phản hồi cũ
                }
                let resJson;
                const contentType = res.headers.get("content-type");
                if (contentType && contentType.includes("application/json")) {
                    resJson = await res.json();
                } else {
                    throw new Error("Server returned non-JSON response (likely 502/504 during restart). Status: " + res.status);
                }
                const data = resJson.data || [];
                
                examSelect.disabled = false;
                examSelect.innerHTML = '<option value="">Chọn Bộ Câu hỏi/Đề thi</option>';
                
                if (data && data.length > 0) {
                    // Lọc đề thi theo quyền truy cập (Công khai / Đề cho đơn vị / Có mật khẩu / Riêng tư)
                    const filteredData = data.filter(exam => {
                        // 1. Admin luôn thấy tất cả
                        if (isAdminLoggedIn) return true;
                        
                        // 2. Giáo viên tạo đề luôn thấy đề của mình
                        if (currentUser && String(currentUser.id) === String(exam.creator_id)) return true;
                        
                        // 3. Đề công khai hoặc Đề có mã bảo mật: Cho phép hiển thị
                        if (exam.chedodethi === 'Đề công khai' || exam.chedodethi === 'Đề có mã bảo mật' || !exam.chedodethi) return true;
                        
                        // 4. Đề cho đơn vị (hoặc Đề thi cho đơn vị):
                        if (exam.chedodethi === 'Đề cho đơn vị' || exam.chedodethi === 'Đề thi cho đơn vị') {
                            const targetLop = String(exam.target_lop || exam.lop || '').trim();

                            // Tìm thông tin giáo viên tạo đề thi để lấy đơn vị
                            const teacherAccount = (accounts || []).find(a => String(a.id) === String(exam.creator_id));
                            const teacherDonvi = String(teacherAccount?.donvi || '').trim().toLowerCase();

                            // Lấy danh sách đơn vị được chỉ định riêng trong cấu hình
                            let allowedUnits = [];
                            const configDonvi = String(exam.target_donvi || exam.donvi || '').trim().toLowerCase();
                            if (configDonvi) allowedUnits.push(configDonvi);
                            if (exam.access_control) {
                                const ac = typeof exam.access_control === 'string' ? JSON.parse(exam.access_control || '{}') : exam.access_control;
                                if (ac && ac.allowedUnits) {
                                    const extraUnits = Array.isArray(ac.allowedUnits) 
                                        ? ac.allowedUnits.map(u => String(u).trim().toLowerCase()) 
                                        : [String(ac.allowedUnits).trim().toLowerCase()];
                                    allowedUnits.push(...extraUnits);
                                }
                            }

                            // Xác định xem thí sinh có thuộc đơn vị của đề thi này hay không
                            let isSameDonVi = false;
                            const inputLopVal = String(document.getElementById('guest_data_lop')?.value || document.getElementById('guest_data_2')?.value || '').trim();
                            const inputDonvi = String(document.getElementById('guest_data_donvi')?.value || inputLopVal).trim().toLowerCase();

                            if (!teacherDonvi && allowedUnits.length === 0) {
                                // Giáo viên chưa thiết lập đơn vị -> Mở cho tất cả học sinh
                                isSameDonVi = true;
                            } else if (currentUser) {
                                const userDonvi = String(currentUser.donvi || currentUser.address || '').trim().toLowerCase();
                                if (teacherDonvi && userDonvi && (userDonvi === teacherDonvi || userDonvi.includes(teacherDonvi) || teacherDonvi.includes(userDonvi))) {
                                    isSameDonVi = true;
                                } else if (allowedUnits.some(u => u && (u === userDonvi || userDonvi.includes(u) || u.includes(userDonvi)))) {
                                    isSameDonVi = true;
                                } else if (teacherDonvi && inputDonvi && (inputDonvi === teacherDonvi || inputDonvi.includes(teacherDonvi) || teacherDonvi.includes(inputDonvi))) {
                                    isSameDonVi = true;
                                } else if (allowedUnits.some(u => u && (u === inputDonvi || inputDonvi.includes(u) || u.includes(inputDonvi)))) {
                                    isSameDonVi = true;
                                }
                            } else {
                                // Thí sinh vãng lai chưa đăng nhập
                                if (teacherDonvi && inputDonvi && (inputDonvi === teacherDonvi || inputDonvi.includes(teacherDonvi) || teacherDonvi.includes(inputDonvi))) {
                                    isSameDonVi = true;
                                } else if (allowedUnits.some(u => u && (u === inputDonvi || inputDonvi.includes(u) || u.includes(inputDonvi)))) {
                                    isSameDonVi = true;
                                }
                            }

                            // Nếu không thuộc đơn vị đó -> Không hiển thị đề
                            if (!isSameDonVi) {
                                return false;
                            }

                            // Đã thuộc đơn vị đó:
                            // TH1: Đề KHÔNG nhập lớp nào -> Dành cho tất cả học sinh thuộc đơn vị đó, không ràng buộc lớp
                            if (!targetLop) {
                                return true;
                            }

                            // TH2: Đề CÓ nhập tên lớp cố định -> Chỉ những học sinh ĐĂNG NHẬP thuộc đúng các lớp được cấu hình mới thấy
                            if (!currentUser) {
                                return false; // Chưa đăng nhập sẽ không thấy đề cấu hình riêng theo lớp
                            }
                            const normalizeLop = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, '');
                            const userLop = normalizeLop(currentUser.lop || '');
                            const allowedLops = targetLop.split(',').map(s => normalizeLop(s)).filter(Boolean);
                            return allowedLops.includes(userLop);
                        }

                        return false;
                    });

                    // DÙNG CHÍNH XÁC ID DUY NHẤT LÀM VALUE CHO TỪNG ĐỀ THI
                    filteredData.forEach(exam => {
                        const opt = document.createElement('option');
                        opt.value = exam.id;
                        opt.dataset.name = exam.name;
                        opt.textContent = exam.name;
                        examSelect.appendChild(opt);
                    });
                }
            } catch (e) { 
                if (currentTeacherSeq !== window._studentTeacherChangeSeq) return;
                console.warn('Notice: Error loading exam names for student, trying cached exams:', e);
                examSelect.disabled = false;
                if (!examSelect.options || examSelect.options.length <= 1) {
                    examSelect.innerHTML = '<option value="">Chọn đề thi</option>';
                }
            }
            if (currentTeacherSeq === window._studentTeacherChangeSeq) {
                updateCurrentExamInfo();
            }
        }

        window._studentExamChangeSeq = 0;
        window.onStudentExamNameChange = async function onStudentExamNameChange() {
            const currentExamSeq = ++window._studentExamChangeSeq;
            console.log('onStudentExamNameChange called, seq:', currentExamSeq);
            const elTeacher = document.getElementById('student-teacher-filter');
            const teacherId = elTeacher ? elTeacher.value : '';
            const examSelect = document.getElementById('student-exam-name-filter');
            const selectedExamId = examSelect ? examSelect.value : '';
            const selectedExamName = examSelect?.options[examSelect.selectedIndex]?.dataset?.name || examSelect?.options[examSelect.selectedIndex]?.textContent || '';
            
            // QUY TẮC SỐNG CÒN: XÓA SẠCH DỮ LIỆU ĐỀ THI VÀ CÂU HỎI TRƯỚC ĐÓ ĐỂ TRÁNH CHỒNG CHÉO
            if (examConfig) {
                examConfig.id = null; // BẮT BUỘC RESET ID ĐẦU TIÊN
                examConfig.creatorId = '';
                examConfig.name = '';
                examConfig.chedodethi = 'Đề công khai';
                examConfig.mabaomatdethi = '';
                examConfig.timeLimit = 0;
                examConfig.count41 = 0;
                examConfig.countTF4 = 0;
                examConfig.countSQ = 0;
                examConfig.countTL = 0;
                examConfig.selectedLessons = [];
                examConfig.access_control = null;
                examConfig.tg_bd = null;
                examConfig.tg_kt = null;
            }
            questions = []; // Xóa câu hỏi trong bộ nhớ
            questionsLoaded = false;
            window.examAvailableCounts = null;
            
            if (typeof resetExam === 'function') {
                resetExam();
            }

            if (!teacherId || !selectedExamId) {
                updateCurrentExamInfo();
                return;
            }

            try {
                let data = null;
                try {
                    const token = localStorage.getItem('auth_token') || '';
                    // TẢI TRỰC TIẾP CHÍNH XÁC THEO ID DUY NHẤT CỦA ĐỀ THI
                    const detailRes = await fetch(`/api/exams?id=${encodeURIComponent(selectedExamId)}`, {
                        headers: token ? { 'Authorization': 'Bearer ' + token } : {}
                    });
                    if (currentExamSeq !== window._studentExamChangeSeq) return;
                    if (detailRes.ok) {
                        const detailJson = await detailRes.json();
                        data = detailJson.data;
                    }
                } catch (apiErr) {
                    console.warn('API get exam config error:', apiErr);
                }
                
                if (currentExamSeq !== window._studentExamChangeSeq) return;

                if (data) {
                    // 1. Kiểm tra thời gian cho phép làm bài TRƯỚC
                    if (data.access_control && data.access_control.enabled && !isAdminLoggedIn && (!currentUser || currentUser.id !== data.creator_id)) {
                        const now = await getInternetTime();
                        const startTime = data.tg_bd ? new Date(data.tg_bd) : (data.access_control.startTime ? new Date(data.access_control.startTime) : null);
                        const endTime = data.tg_kt ? new Date(data.tg_kt) : (data.access_control.endTime ? new Date(data.access_control.endTime) : null);
                        
                        if (startTime && now < startTime) {
                            await showTimeRestrictionModal(startTime, endTime, false);
                            if (currentExamSeq !== window._studentExamChangeSeq) return;
                            examSelect.value = ''; // Reset dropdown
                            updateCurrentExamInfo();
                            return;
                        }
                        
                        if (endTime && now > endTime) {
                            await showTimeRestrictionModal(startTime, endTime, true);
                            if (currentExamSeq !== window._studentExamChangeSeq) return;
                            examSelect.value = ''; // Reset dropdown
                            updateCurrentExamInfo();
                            return;
                        }
                    }
                    // 2. Kiểm tra mã bảo mật SAU nếu thời gian hợp lệ
                    if (data.chedodethi === 'Đề có mã bảo mật' && !isAdminLoggedIn && (!currentUser || currentUser.id !== data.creator_id)) {
                        const code = await showExamPasswordModal();
                        if (currentExamSeq !== window._studentExamChangeSeq) return;
                        if (code === null) { // Người dùng hủy
                            examSelect.value = ''; // Reset dropdown
                            updateCurrentExamInfo();
                            return;
                        }
                        if (code !== data.mabaomatdethi) {
                            showToast('❌ Mã bảo mật không chính xác!', 'error');
                            examSelect.value = ''; // Reset dropdown
                            updateCurrentExamInfo();
                            return;
                        }
                    }
                    
                    if (currentExamSeq !== window._studentExamChangeSeq) return;

                    applyExamConfig(data);
                    
                    // LUỒNG MỚI BƯỚC 2: Chỉ đếm số lượng câu hỏi trên Server, KHÔNG TẢI NỘI DUNG CÂU HỎI VỀ
                    await verifyExamQuestionsOnServer(data);
                    
                    if (currentExamSeq === window._studentExamChangeSeq) {
                        updateCurrentExamInfo();
                    }
                }
            } catch (e) { 
                if (currentExamSeq !== window._studentExamChangeSeq) return;
                console.warn('Notice: Could not load specific exam for student:', e); 
            }
        }
        
        window._verifyQuestionsSeq = 0;
        window.verifyExamQuestionsOnServer = async function(examData) {
            const currentVerifySeq = ++window._verifyQuestionsSeq;
            window.examAvailableCounts = null;
            if (!examData || !examData.creator_id) return;

            try {
                // Chỉ lấy type, level, lesson. Siêu nhẹ, bảo mật tuyệt đối không tải đáp án/nội dung
                const res = await fetch(`/api/questions?metaOnly=true&teacherId=${encodeURIComponent(examData.creator_id)}`);
                if (currentVerifySeq !== window._verifyQuestionsSeq) return;
                if (!res.ok) throw new Error('Không thể tải metadata câu hỏi');
                let resJson;
                const contentType = res.headers.get("content-type");
                if (contentType && contentType.includes("application/json")) {
                    resJson = await res.json();
                } else {
                    throw new Error("Server returned non-JSON response (likely 502/504 during restart). Status: " + res.status);
                }
                const data = resJson.data || [];
                
                let counts = {};
                const rawFilter = examData.selected_lessons || examData.selectedLessons || [];
                const lessonFilter = (Array.isArray(rawFilter) ? rawFilter : [rawFilter])
                    .map(l => String(l || '').trim().toLowerCase().replace(/\s+/g, ' '))
                    .filter(Boolean);
                const allowedSet = new Set(lessonFilter);

                const normType = (type) => {
                    const t = String(type || '').trim().toLowerCase();
                    if (t === '4-1' || t === 'trac_nghiem' || t === 'mcq') return '4-1';
                    if (t === 'tf4' || t === 'dung_sai' || t === 'true_false') return 'TF4';
                    if (t === 'sq' || t === 'tra_loi_ngan' || t === 'short_answer') return 'SQ';
                    if (t === 'tl' || t === 'tu_luan' || t === 'essay') return 'TL';
                    return type;
                };
                const normLevel = (lvl) => {
                    const l = String(lvl || '').trim().toUpperCase();
                    if (l === 'NB' || l === 'TH' || l === 'VD') return l;
                    return 'NB';
                };
                
                if (data && Array.isArray(data)) {
                    for (let q of data) {
                        const qLesson = String(q.lesson || '').trim().toLowerCase().replace(/\s+/g, ' ');
                        // CHỈ ĐẾM CÂU HỎI KHI BÀI HỌC THỰC SỰ NẰM TRONG BÀI ĐÃ CHỌN CỦA ĐỀ THI
                        if (allowedSet.size > 0 && allowedSet.has(qLesson)) {
                            const key = normType(q.type) + '-' + normLevel(q.level);
                            counts[key] = (counts[key] || 0) + 1;
                        }
                    }
                }
                if (currentVerifySeq === window._verifyQuestionsSeq) {
                    window.examAvailableCounts = counts;
                    updateCurrentExamInfo();
                }
            } catch(e) {
                if (currentVerifySeq !== window._verifyQuestionsSeq) return;
                console.error("Error verifying exam questions on server:", e);
            }
        };

        function updateAvailableCountsForStudent() {
            updateCurrentExamInfo();
        }

        window.updateCurrentExamInfo = function updateCurrentExamInfo() {
            const elName = document.getElementById('current-exam-name');
            const elInfo = document.getElementById('current-exam-info');
            const elCreator = document.getElementById('exam-creator-name');
            const elCreatorWrapper = document.getElementById('exam-creator-wrapper') || elCreator?.parentElement;
            const fullDetailsContainer = document.getElementById('student-exam-full-details');
            
            const studentTeacher = document.getElementById('student-teacher-filter')?.value;
            const studentExam = document.getElementById('student-exam-name-filter')?.value;
            
            // Boolean checking if both filters are actually selected in the student UI
            const hasStudentSelectedExam = !!(studentTeacher && studentExam);

            // 1. Áp dụng hiển thị text cơ bản nếu chưa chọn đề
            if (!hasStudentSelectedExam) {
                if (elName) elName.textContent = 'Chưa có đề thi'; 
                if (elCreatorWrapper) elCreatorWrapper.classList.add('hidden');
                if (fullDetailsContainer) fullDetailsContainer.classList.add('hidden');
                if (elInfo) { elInfo.innerHTML = ''; elInfo.classList.add('hidden'); }
            } else {
                if (elName) elName.textContent = examConfig.name || '';
                if (elCreator) elCreator.textContent = examConfig.creatorName || accountsMap[examConfig.creatorId] || ho_ten_khach_hang || '';
                if (elCreatorWrapper) elCreatorWrapper.classList.remove('hidden');
                if (fullDetailsContainer) fullDetailsContainer.classList.remove('hidden');
            }

            const total = (examConfig.count41 || 0) + (examConfig.countTF4 || 0) + (examConfig.countSQ || 0) + (examConfig.countTL || 0);
            
            let isEnough = true;
            let filteredQuestions = questions;
            let getCount = (type, level) => 0;

            if (total > 0) {
                // Lọc theo người tạo cấu hình đề thi
                if (examConfig.creatorId) {
                    filteredQuestions = filteredQuestions.filter(q => String(q.creatorId) === String(examConfig.creatorId));
                } else {
                    const isConfigTabActive = document.getElementById('exams-panel') && !document.getElementById('exams-panel').classList.contains('hidden');
                    if (isConfigTabActive) {
                        const examTeacherFilter = document.getElementById('exam-teacher-filter')?.value;
                        if (examTeacherFilter) {
                            filteredQuestions = filteredQuestions.filter(q => String(q.creatorId) === String(examTeacherFilter));
                        } else if (currentUser && currentUser.role !== 'admin') {
                            filteredQuestions = filteredQuestions.filter(q => String(q.creatorId) === String(currentUser.id));
                        }
                    } else if (studentTeacher) {
                        filteredQuestions = filteredQuestions.filter(q => String(q.creatorId) === String(studentTeacher));
                    }
                }

                const rawFilter = examConfig.selectedLessons || [];
                const allowedLessons = (Array.isArray(rawFilter) ? rawFilter : [rawFilter])
                    .map(l => String(l || '').trim().toLowerCase().replace(/\s+/g, ' '))
                    .filter(Boolean);
                const allowedSet = new Set(allowedLessons);
                const filterByLesson = (q) => {
                    if (allowedSet.size === 0) return false;
                    const qLesson = String(q.lesson || '').trim().toLowerCase().replace(/\s+/g, ' ');
                    return allowedSet.has(qLesson);
                };
                
                // NẾU CÓ DỮ LIỆU ĐÃ ĐẾM XÁC THỰC TỪ SERVER CHO HỌC SINH -> ƯU TIÊN DÙNG SỐ LIỆU NÀY
                if (window.examAvailableCounts && studentTeacher && studentExam) {
                    getCount = (type, level) => window.examAvailableCounts[type + '-' + level] || 0;
                } else {
                    const normType = (t) => {
                        const s = String(t || '').trim().toLowerCase();
                        if (s === '4-1' || s === 'trac_nghiem' || s === 'mcq') return '4-1';
                        if (s === 'tf4' || s === 'dung_sai' || s === 'true_false') return 'TF4';
                        if (s === 'sq' || s === 'tra_loi_ngan' || s === 'short_answer') return 'SQ';
                        if (s === 'tl' || s === 'tu_luan' || s === 'essay') return 'TL';
                        return t;
                    };
                    const normLevel = (lvl) => {
                        const l = String(lvl || '').trim().toUpperCase();
                        if (l === 'NB' || l === 'TH' || l === 'VD') return l;
                        return 'NB';
                    };
                    getCount = (type, level) => filteredQuestions.filter(q => normType(q.type) === type && normLevel(q.level) === level && filterByLesson(q)).length;
                }
                
                isEnough = checkExamQuestionsAvailability(examConfig, getCount);
            }

            // 2. Cập nhật chi tiết các thẻ chỉ số trên giao diện học sinh khi đã chọn đề
            if (hasStudentSelectedExam) {
                // Số câu
                const elTotal = document.getElementById('exam-detail-total-questions');
                if (elTotal) elTotal.textContent = `${total} câu`;

                // Thời gian
                const elTime = document.getElementById('exam-detail-time-limit');
                if (elTime) elTime.textContent = `${examConfig.timeLimit || 0} phút`;

                // Lượt làm bài được phép
                const elAttempts = document.getElementById('exam-detail-max-attempts');
                if (elAttempts) {
                    const maxAtt = Math.max(0, parseInt(examConfig.maxAttempts || examConfig.max_attempts) || 0);
                    if (maxAtt > 0) {
                        let localAttempts = 0;
                        const nameVal = document.getElementById('guest_data_1')?.value?.trim() || '';
                        const currentStudentName = nameVal.toLowerCase();
                        const currentUserId = (currentUser?.id || currentUser?.user_id) ? String(currentUser.id || currentUser.user_id) : null;
                        const resList = (window.resultsList && Array.isArray(window.resultsList)) ? window.resultsList : (typeof resultsList !== 'undefined' && Array.isArray(resultsList) ? resultsList : []);
                        
                        if (resList.length > 0 && (currentUserId || currentStudentName)) {
                            localAttempts = resList.filter(r => {
                                const matchExam = String(r.exam_id) === String(studentExam) || (r.exam_name && String(r.exam_name).trim().toLowerCase() === String(examConfig.name || '').trim().toLowerCase());
                                if (!matchExam) return false;
                                if (currentUserId && r.user_id && String(r.user_id) === currentUserId) return true;
                                if (currentStudentName && r.student_name && String(r.student_name).trim().toLowerCase() === currentStudentName) return true;
                                return false;
                            }).length;
                        }
                        elAttempts.textContent = `${maxAtt} lần${localAttempts > 0 ? ` (Đã làm: ${localAttempts}l)` : ''}`;
                    } else {
                        elAttempts.textContent = 'Không giới hạn';
                    }
                }

                // Số lần được rời màn hình
                const elCheat = document.getElementById('exam-detail-max-cheat');
                if (elCheat) {
                    const maxCheat = (typeof examConfig.maxCheatWarnings === 'number' && examConfig.maxCheatWarnings > 0) 
                        ? examConfig.maxCheatWarnings 
                        : 5;
                    elCheat.textContent = `Tối đa ${maxCheat} lần`;
                }

                // Cơ cấu loại câu hỏi
                const elBreakdown = document.getElementById('exam-question-type-breakdown');
                if (elBreakdown) {
                    const types = [];
                    if (examConfig.count41 > 0) types.push(`<span class="px-2 py-0.5 bg-blue-100 text-blue-800 rounded-md font-bold">4 chọn 1: ${examConfig.count41} câu</span>`);
                    if (examConfig.countTF4 > 0) types.push(`<span class="px-2 py-0.5 bg-emerald-100 text-emerald-800 rounded-md font-bold">Đúng/Sai: ${examConfig.countTF4} câu</span>`);
                    if (examConfig.countSQ > 0) types.push(`<span class="px-2 py-0.5 bg-orange-100 text-orange-800 rounded-md font-bold">Trả lời ngắn: ${examConfig.countSQ} câu</span>`);
                    if (examConfig.countTL > 0) types.push(`<span class="px-2 py-0.5 bg-purple-100 text-purple-800 rounded-md font-bold">Tự luận: ${examConfig.countTL} câu</span>`);
                    elBreakdown.innerHTML = types.length > 0 ? `<span class="font-semibold text-gray-500 mr-1">Cơ cấu:</span> ${types.join(' ')}` : '<span class="italic text-gray-400">Chưa phân bổ câu hỏi</span>';
                }

                // Trạng thái ngân hàng câu hỏi
                const elStatus = document.getElementById('exam-availability-status');
                if (elStatus) {
                    const countDetails = `Chi tiết kiểm tra:\nTổng: ${total}\n[4-1] NB cần ${examConfig.count41NB || 0}, TH cần ${examConfig.count41TH || 0}, VD cần ${examConfig.count41VD || 0}\n[TF4] NB cần ${examConfig.countTF4NB || 0}, TH cần ${examConfig.countTF4TH || 0}, VD cần ${examConfig.countTF4VD || 0}\n[SQ] NB cần ${examConfig.countSQNB || 0}, TH cần ${examConfig.countSQTH || 0}, VD cần ${examConfig.countSQVD || 0}\n[TL] NB cần ${examConfig.countTLNB || 0}, TH cần ${examConfig.countTLTH || 0}, VD cần ${examConfig.countTLVD || 0}`;
                    if (total > 0) {
                        if (!isEnough) {
                            elStatus.innerHTML = `<span class="text-rose-700 bg-rose-100 px-2.5 py-1 rounded-lg font-bold flex items-center gap-1 cursor-help" title="${countDetails}">❌ Kho chưa đủ câu</span>`;
                        } else {
                            elStatus.innerHTML = `<span class="text-emerald-700 bg-emerald-100 px-2.5 py-1 rounded-lg font-bold flex items-center gap-1">✅ Đáp ứng đủ ${total} câu</span>`;
                        }
                    } else {
                        elStatus.innerHTML = `<span class="text-amber-700 bg-amber-100 px-2.5 py-1 rounded-lg font-bold">⚠️ Chưa cấu hình câu hỏi</span>`;
                    }
                }
            }

            // KHOÁ / MỞ KHOÁ NÚT BẮT ĐẦU DỰA VÀO ĐIỀU KIỆN ĐỀ THI
            const startBtn = document.querySelector('button[onclick="startExam(this)"]') || document.querySelector('button[onclick*="startExam"]');
            if (startBtn) {
                if (hasStudentSelectedExam && total > 0 && isEnough) {
                    startBtn.disabled = false;
                    startBtn.classList.remove('opacity-50', 'cursor-not-allowed');
                } else {
                    startBtn.disabled = true;
                    startBtn.classList.add('opacity-50', 'cursor-not-allowed');
                }
            }

            // Update Access Info - Hidden as per user request to remove time check mechanism
            const elAccessInfo = document.getElementById('exam-access-info');
            if (elAccessInfo) elAccessInfo.classList.add('hidden');

            const configDisplay = document.getElementById('current-config-display');
            if (configDisplay) {
                const examConfigSelect = document.getElementById('exam-config-name');
                const hasSelectedConfig = examConfigSelect && examConfigSelect.value.trim() !== '';

                if (total > 0 && hasSelectedConfig) {
                    configDisplay.classList.remove('hidden');
                    
                    configDisplay.innerHTML = `
                        <div class="flex items-center gap-2 mb-3 flex-wrap">
                            <span class="text-lg font-bold text-purple-800">Thông tin cấu hình đề thi: ${examConfig.name || 'Chưa có tên'}</span></u>
                            <span class="px-3 py-1 bg-purple-100 text-purple-700 rounded-full text-sm font-semibold">${total} câu / ${examConfig.timeLimit} phút</span></u>
                            <span class="px-3 py-1 bg-indigo-100 text-indigo-700 rounded-full text-sm font-semibold">${(examConfig.maxAttempts && examConfig.maxAttempts > 0) ? `Giới hạn: ${examConfig.maxAttempts} lần` : 'Không giới hạn lần làm'}</span></u>
                            <span class="text-sm text-gray-600 font-semibold italic ml-auto">Người tạo đề thi: <span class="text-purple-600">${accountsMap[examConfig.creatorId] || ho_ten_khach_hang}</span></u></span></u>
                        </div>
                        <div class="grid grid-cols-1 md:grid-cols-4 gap-4 text-sm">
                            <div class="bg-white p-3 rounded-lg shadow-sm border border-gray-100">
                                <div class="font-bold text-blue-600 mb-1">Trắc nghiệm 4 chọn 1</div>
                                <div class="text-gray-600">NB: ${examConfig.count41NB || 0} | TH: ${examConfig.count41TH || 0} | VD: ${examConfig.count41VD || 0}</div>
                                <div class="font-semibold mt-1">Tổng: ${examConfig.count41} câu</div>
                            </div>
                            <div class="bg-white p-3 rounded-lg shadow-sm border border-gray-100">
                                <div class="font-bold text-green-600 mb-1">Trắc nghiệm Đúng/Sai</div>
                                <div class="text-gray-600">NB: ${examConfig.countTF4NB || 0} | TH: ${examConfig.countTF4TH || 0} | VD: ${examConfig.countTF4VD || 0}</div>
                                <div class="font-semibold mt-1">Tổng: ${examConfig.countTF4} câu</div>
                            </div>
                            <div class="bg-white p-3 rounded-lg shadow-sm border border-gray-100">
                                <div class="font-bold text-orange-600 mb-1">Trắc nghiệm Trả lời ngắn</div>
                                <div class="text-gray-600">NB: ${examConfig.countSQNB || 0} | TH: ${examConfig.countSQTH || 0} | VD: ${examConfig.countSQVD || 0}</div>
                                <div class="font-semibold mt-1">Tổng: ${examConfig.countSQ} câu</div>
                            </div>
                            <div class="bg-white p-3 rounded-lg shadow-sm border border-gray-100">
                                <div class="font-bold text-purple-600 mb-1">Tự luận</div>
                                <div class="text-gray-600">NB: ${examConfig.countTLNB || 0} | TH: ${examConfig.countTLTH || 0} | VD: ${examConfig.countTLVD || 0}</div>
                                <div class="font-semibold mt-1">Tổng: ${examConfig.countTL} câu</div>
                            </div>
                        </div>
                        ${!isEnough && questionsLoaded ? '<div class="mt-3 text-red-500 font-semibold text-sm flex items-center gap-1"><span>⚠️</span></u> Cảnh báo: Ngân hàng câu hỏi không đủ câu hỏi theo cấu hình này!</div>' : ''}
                        ${!isEnough && !questionsLoaded ? '<div class="mt-3 text-blue-500 font-semibold text-sm flex items-center gap-1 italic"><span>🔄</span></u> Đang tải ngân hàng câu hỏi, vui lòng đợi...</div>' : ''}
                    `;
                } else {
                    configDisplay.classList.add('hidden');
                }
            }
        }

        // ==================== EXAM TAB ====================
        function showExamPasswordModal() {
            return new Promise((resolve) => {
                const modalContent = `
                    <div class="p-8 text-center max-w-md mx-auto">
                        <div class="text-5xl mb-4">🔐</div>
                        <h3 class="text-2xl font-bold text-gray-800 mb-2">Mã bảo mật đề thi</h3>
                        <p class="text-gray-600 mb-6">Đề thi này được bảo mật. Vui lòng nhập mã để tiếp tục.</p>
                        
                        <div class="space-y-4 text-left">
                            <div class="relative">
                                <input type="text" id="exam-password-input" style="-webkit-text-security: disc;" placeholder="Nhập mã bảo mật" autocomplete="off" data-lpignore="true" class="w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-purple-500 focus:outline-none text-lg pr-12" onkeypress="if(event.key==='Enter') document.getElementById('confirm-password-btn').click()">
                                <button type="button" onclick="togglePasswordVisibility('exam-password-input', this)" class="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-500 hover:text-gray-700">
                                    <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                                </button>
                            </div>
                        </div>
                        
                        <div class="mt-6 flex justify-center gap-4">
                            <button id="cancel-password-btn" class="px-4 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 transition font-semibold">Hủy</button>
                            <button id="confirm-password-btn" class="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition font-semibold">Xác nhận</button>
                        </div>
                    </div>
                `;
                showModal(modalContent);
                
                document.getElementById('cancel-password-btn').onclick = () => {
                    closeModal();
                    resolve(null);
                };
                
                document.getElementById('confirm-password-btn').onclick = () => {
                    const password = document.getElementById('exam-password-input')?.value || '';
                    closeModal();
                    resolve(password);
                };
                
                // Focus input
                setTimeout(() => document.getElementById('exam-password-input').focus(), 100);
            });
        }

        window.startExamUI = function startExamUI() {
            const examForm = document.getElementById('exam-form');
            const examInterface = document.getElementById('exam-interface');
            const examResults = document.getElementById('exam-results');

            if (examForm) examForm.classList.add('hidden');
            if (examResults) examResults.classList.add('hidden');
            if (examInterface) {
                examInterface.classList.remove('hidden');
                examInterface.classList.add('fade-in');
            }

            const elName = document.getElementById('exam-student-name');
            const elTitle = document.getElementById('exam-title');
            const elCreator = document.getElementById('exam-creator-name-running');
            if (elName) elName.textContent = currentExam.studentName || '';
            if (elTitle) elTitle.textContent = examConfig.name || '';
            if (elCreator) elCreator.textContent = examConfig.creatorName || ho_ten_khach_hang || '';

            // Khởi tạo giám sát phòng thi mượt mà
            if (window.initExamMonitoring) {
                window.initExamMonitoring();
            }

            startTimer();
            renderQuestionNav();
            renderCurrentQuestion(true);
            updateProgress();
            if (window.backupExamState) window.backupExamState();

            // Cuộn trang mượt mà lên đầu bài thi, không làm khựng hoặc giật trang
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };

        window.startExam = async function startExam(btn) {
            console.log('startExam called');
            try { getExamAudioContext(); } catch(e) {}
            const startBtn = btn || document.querySelector('button[onclick*="startExam"]');
            const originalBtnText = startBtn ? startBtn.innerHTML : '';
            
            try {
                const name = document.getElementById('guest_data_1')?.value?.trim() || '';
                const inputLop = (document.getElementById('guest_data_lop') || document.getElementById('guest_data_2'))?.value?.trim() || '';
                const inputDonvi = document.getElementById('guest_data_donvi')?.value?.trim() || '';
                const teacherId = document.getElementById('student-teacher-filter')?.value || '';
                const examSelectEl = document.getElementById('student-exam-name-filter');
                const selectedExamId = examSelectEl?.value || '';
                const examName = examSelectEl?.options[examSelectEl.selectedIndex]?.dataset?.name || examSelectEl?.options[examSelectEl.selectedIndex]?.textContent || examConfig?.name || '';

                if (!name) {
                    showToast('Vui lòng nhập họ và tên!', 'error');
                    document.getElementById('guest_data_1')?.focus();
                    return;
                }
                // Nếu học sinh không có đăng nhập, học sinh tự do thì chỉ cần cho phép nhập lớp hoặc đơn vị là có thể tham gia làm bài
                if (!inputLop && !inputDonvi) {
                    showToast('Vui lòng nhập lớp hoặc đơn vị!', 'error');
                    const targetFocus = !inputLop ? (document.getElementById('guest_data_lop') || document.getElementById('guest_data_2')) : document.getElementById('guest_data_donvi');
                    targetFocus?.focus();
                    return;
                }
                const studentClass = inputLop && inputDonvi ? `${inputLop} - ${inputDonvi}` : (inputLop || inputDonvi);
                if (!teacherId) {
                    showToast('Vui lòng chọn tên giáo viên!', 'error');
                    document.getElementById('student-teacher-filter')?.focus();
                    return;
                }
                if (!selectedExamId) {
                    showToast('Vui lòng chọn bộ câu hỏi hoặc đề thi!', 'error');
                    document.getElementById('student-exam-name-filter')?.focus();
                    return;
                }

                // KHẮC PHỤC LỖI TẢI NHẦM ĐỀ: Đồng bộ tuyệt đối giữa examConfig trong bộ nhớ và đề được chọn
                if (!examConfig || !examConfig.id || String(examConfig.id) !== String(selectedExamId)) {
                    const token = localStorage.getItem('auth_token') || '';
                    const detailRes = await fetch(`/api/exams?id=${encodeURIComponent(selectedExamId)}`, {
                        headers: token ? { 'Authorization': 'Bearer ' + token } : {}
                    });
                    if (detailRes.ok) {
                        const detailJson = await detailRes.json();
                        if (detailJson.data) {
                            applyExamConfig(detailJson.data);
                        }
                    }
                }

                if (!examConfig || !examConfig.id || String(examConfig.id) !== String(selectedExamId)) {
                    showToast('Không thể xác thực cấu hình đề thi đã chọn. Vui lòng chọn lại đề!', 'error');
                    return;
                }

                // Disable button to prevent double clicks
                if (startBtn) {
                    startBtn.disabled = true;
                    startBtn.innerHTML = '<span>⏳</span> Đang tải dữ liệu đề thi...';
                }

                // Kiểm tra phân quyền cho chế độ Đề cho đơn vị
                if ((examConfig.chedodethi === 'Đề cho đơn vị' || examConfig.chedodethi === 'Đề thi cho đơn vị') && !isAdminLoggedIn && (!currentUser || String(currentUser.id) !== String(examConfig.creatorId))) {
                    const targetLop = String(examConfig.target_lop || examConfig.lop || '').trim();
                    
                    // Lấy thông tin đơn vị của giáo viên tạo đề
                    const teacherAccount = (accounts || []).find(a => String(a.id) === String(examConfig.creatorId || teacherId));
                    const teacherDonvi = String(teacherAccount?.donvi || '').trim().toLowerCase();
                    let allowedUnits = [];
                    const configDonvi = String(examConfig.target_donvi || examConfig.donvi || '').trim().toLowerCase();
                    if (configDonvi) allowedUnits.push(configDonvi);
                    if (examConfig.accessControl && examConfig.accessControl.allowedUnits) {
                        const extraUnits = Array.isArray(examConfig.accessControl.allowedUnits) 
                            ? examConfig.accessControl.allowedUnits.map(u => String(u).trim().toLowerCase()) 
                            : [String(examConfig.accessControl.allowedUnits).trim().toLowerCase()];
                        allowedUnits.push(...extraUnits);
                    }

                    let isSameDonVi = false;
                    const candidateDonvi = String(inputDonvi || (currentUser?.donvi || currentUser?.address) || inputLop).trim().toLowerCase();

                    if (!teacherDonvi && allowedUnits.length === 0) {
                        isSameDonVi = true;
                    } else if (currentUser) {
                        const userDonvi = String(currentUser.donvi || currentUser.address || '').trim().toLowerCase();
                        if (teacherDonvi && userDonvi && (userDonvi === teacherDonvi || userDonvi.includes(teacherDonvi) || teacherDonvi.includes(userDonvi))) {
                            isSameDonVi = true;
                        } else if (allowedUnits.some(u => u && (u === userDonvi || userDonvi.includes(u) || u.includes(userDonvi)))) {
                            isSameDonVi = true;
                        } else if (teacherDonvi && candidateDonvi && (candidateDonvi === teacherDonvi || candidateDonvi.includes(teacherDonvi) || teacherDonvi.includes(candidateDonvi))) {
                            isSameDonVi = true;
                        } else if (allowedUnits.some(u => u && (u === candidateDonvi || candidateDonvi.includes(u) || u.includes(candidateDonvi)))) {
                            isSameDonVi = true;
                        }
                    } else {
                        if (teacherDonvi && candidateDonvi && (candidateDonvi === teacherDonvi || candidateDonvi.includes(teacherDonvi) || teacherDonvi.includes(candidateDonvi))) {
                            isSameDonVi = true;
                        } else if (allowedUnits.some(u => u && (u === candidateDonvi || candidateDonvi.includes(u) || u.includes(candidateDonvi)))) {
                            isSameDonVi = true;
                        }
                    }

                    if (!isSameDonVi) {
                        showToast(`🛑 Bạn không có quyền làm đề thi này do Đơn vị/Trường không phù hợp! (Đề thi chỉ dành cho học sinh thuộc đơn vị "${teacherAccount?.donvi || 'được chỉ định'}").`, 'error');
                        if (startBtn) { startBtn.disabled = false; startBtn.innerHTML = originalBtnText; }
                        return;
                    }

                    // Nếu có cấu hình lớp cụ thể
                    if (targetLop) {
                        if (!currentUser) {
                            showToast(`🛑 Bạn không có quyền làm đề thi này do chưa đăng nhập! (Đề thi chỉ dành riêng cho học sinh Lớp ${targetLop}. Vui lòng đăng nhập tài khoản học sinh để làm bài).`, 'error');
                            if (startBtn) { startBtn.disabled = false; startBtn.innerHTML = originalBtnText; }
                            return;
                        }
                        const normalizeLop = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, '');
                        const userLop = normalizeLop(currentUser.lop || inputLop || '');
                        const candidateLop = normalizeLop(inputLop);
                        const allowedLops = targetLop.split(/[,;\n]+/).map(s => normalizeLop(s)).filter(Boolean);
                        const isLopMatched = allowedLops.some(al => 
                            (userLop && (al === userLop || userLop === 'lớp' + al || al === 'lớp' + userLop || userLop.endsWith(al) || al.endsWith(userLop))) ||
                            (candidateLop && (al === candidateLop || candidateLop === 'lớp' + al || al === 'lớp' + candidateLop || candidateLop.endsWith(al) || al.endsWith(candidateLop)))
                        );
                        if (!isLopMatched) {
                            showToast(`🛑 Bạn không có quyền làm đề thi này do Lớp không phù hợp! (Đề thi chỉ dành riêng cho học sinh Lớp ${targetLop}. Tài khoản của bạn hiện thuộc Lớp ${currentUser.lop || inputLop || 'khác'}).`, 'error');
                            if (startBtn) { startBtn.disabled = false; startBtn.innerHTML = originalBtnText; }
                            return;
                        }
                    }
                    // Nếu không nhập lớp -> dành cho tất cả học sinh thuộc đơn vị đó, không ràng buộc lớp
                }

                // Kiểm tra thời gian cho phép làm bài (tg_bd, tg_kt)
                if (examConfig.accessControl && examConfig.accessControl.enabled && !isAdminLoggedIn && (!currentUser || currentUser.id !== examConfig.creatorId)) {
                    const internetNow = await getInternetTime();
                    const startTime = examConfig.accessControl.startTime ? new Date(examConfig.accessControl.startTime) : null;
                    const endTime = examConfig.accessControl.endTime ? new Date(examConfig.accessControl.endTime) : null;
                    
                    if (startTime && internetNow < startTime) {
                        await showTimeRestrictionModal(startTime, endTime, false);
                        if (startBtn) { startBtn.disabled = false; startBtn.innerHTML = originalBtnText; }
                        return;
                    }
                    
                    if (endTime && internetNow > endTime) {
                        await showTimeRestrictionModal(startTime, endTime, true);
                        if (startBtn) { startBtn.disabled = false; startBtn.innerHTML = originalBtnText; }
                        return;
                    }
                }

                const total = examConfig.count41 + examConfig.countTF4 + examConfig.countSQ + examConfig.countTL;
                if (total === 0) {
                    showToast('Đề thi chưa có câu hỏi nào. Vui lòng cấu hình đề thi!', 'warning');
                    if (startBtn) { startBtn.disabled = false; startBtn.innerHTML = originalBtnText; }
                    return;
                }

                // KIỂM TRA TRƯỚC SỐ LẦN LÀM BÀI TRÊN CLIENT
                const maxAttemptsVal = Math.max(0, parseInt(examConfig.maxAttempts || examConfig.max_attempts) || 0);
                if (maxAttemptsVal > 0 && !isAdminLoggedIn && !isTeacherLoggedIn) {
                    let localAttempts = 0;
                    const currentStudentName = (name || '').trim().toLowerCase();
                    const currentUserId = (currentUser?.id || currentUser?.user_id) ? String(currentUser.id || currentUser.user_id) : null;
                    
                    const resList = (window.resultsList && Array.isArray(window.resultsList)) ? window.resultsList : (typeof resultsList !== 'undefined' && Array.isArray(resultsList) ? resultsList : []);
                    if (resList.length > 0) {
                        localAttempts = resList.filter(r => {
                            const matchExam = String(r.exam_id) === String(selectedExamId) || (r.exam_name && String(r.exam_name).trim().toLowerCase() === String(examName).trim().toLowerCase());
                            if (!matchExam) return false;
                            if (currentUserId && r.user_id && String(r.user_id) === currentUserId) return true;
                            if (currentStudentName && r.student_name && String(r.student_name).trim().toLowerCase() === currentStudentName) return true;
                            return false;
                        }).length;
                    }

                    if (localAttempts >= maxAttemptsVal) {
                        showToast(`🛑 Bạn đã đạt giới hạn số lần làm bài thi này! (Bạn đã hoàn thành ${localAttempts} lần / Tối đa ${maxAttemptsVal} lần làm bài quy định). Bạn không thể làm thêm nữa!`, 'error');
                        if (startBtn) { startBtn.disabled = false; startBtn.innerHTML = originalBtnText; }
                        return;
                    }
                }

                // Tải đề thi từ Backend Server (bảo mật, không có đáp án, lấy đúng số lượng theo đề thi được chọn)
                const payload = {
                    teacherId,
                    examId: selectedExamId,
                    examName: examName,
                    studentName: name,
                    studentLop: inputLop,
                    studentDonvi: inputDonvi,
                    studentClass: studentClass,
                    userLop: (currentUser && currentUser.lop) ? currentUser.lop : inputLop,
                    userDonvi: (currentUser && (currentUser.donvi || currentUser.address)) ? (currentUser.donvi || currentUser.address) : inputDonvi,
                    examConfig
                };
                
                const authToken = localStorage.getItem('auth_token') || '';
                const reqHeaders = { 'Content-Type': 'application/json' };
                if (authToken) {
                    reqHeaders['Authorization'] = 'Bearer ' + authToken;
                }

                const response = await fetch('/api/exam/generate', {
                    method: 'POST',
                    headers: reqHeaders,
                    body: JSON.stringify(payload)
                });
                
                if (!response.ok) {
                    let errMessage = 'Lỗi khi tải đề thi từ máy chủ';
                    try {
                        const rawText = await response.text();
                        let parsed = null;
                        try {
                            parsed = JSON.parse(rawText);
                        } catch(jsonErr) {}

                        if (parsed && (parsed.error || parsed.message)) {
                            errMessage = parsed.error || parsed.message;
                        } else if (rawText && rawText.trim() && rawText.length < 300 && !rawText.includes('<html')) {
                            errMessage = rawText.trim();
                        } else if (response.status === 403) {
                            errMessage = '🛑 Bạn không có quyền tham gia làm đề thi này do Đơn vị, Lớp học không phù hợp hoặc đã đạt giới hạn số lần làm bài quy định.';
                        } else if (response.status === 404) {
                            errMessage = '🛑 Không tìm thấy câu hỏi hoặc cấu hình đề thi trên hệ thống.';
                        } else {
                            errMessage = '🛑 Lỗi kết nối hoặc máy chủ phản hồi không đúng định dạng.';
                        }
                    } catch(e) {
                        errMessage = '🛑 Lỗi kết nối hoặc máy chủ phản hồi không đúng định dạng.';
                    }
                    showToast(errMessage, 'error');
                    if (startBtn) { startBtn.disabled = false; startBtn.innerHTML = originalBtnText; }
                    return;
                }
                
                const result = await response.json();
                const examQuestions = result.questions;
                window.currentExamToken = result.token; // Lưu khóa bảo mật để chấm điểm sau

                // Cập nhật chế độ công bố kết quả ngay lập tức trực tiếp từ phản hồi máy chủ
                if (result.immediateFeedback !== undefined) {
                    examConfig.immediateFeedback = Boolean(result.immediateFeedback);
                }

                // Lấy số lần rời màn hình trực tiếp từ CSDL phản hồi bởi máy chủ (bảo mật, không cho tự ý can thiệp)
                const maxCheatAllowed = (result && typeof result.maxCheatWarnings === 'number' && result.maxCheatWarnings > 0)
                    ? result.maxCheatWarnings
                    : ((examConfig && typeof examConfig.maxCheatWarnings === 'number' && examConfig.maxCheatWarnings > 0) ? examConfig.maxCheatWarnings : 5);

                currentExam = {
                    questions: examQuestions,
                    answers: {},
                    currentIndex: 0,
                    startTime: Date.now(),
                    timerInterval: null,
                    studentName: name,
                    studentLop: inputLop,
                    studentDonvi: inputDonvi,
                    studentClass: studentClass,
                    cheatWarningCount: 0,
                    maxCheatWarnings: maxCheatAllowed
                };

                startExamUI();

                showToast('Bắt đầu làm bài! Chúc bạn thi tốt.', 'success');
            } catch (error) {
                console.error('Lỗi khi bắt đầu thi:', error);
                showToast('Có lỗi xảy ra khi chuẩn bị đề thi. Vui lòng thử lại!', 'error');
            } finally {
                if (startBtn) {
                    startBtn.disabled = false;
                    startBtn.innerHTML = originalBtnText;
                }
            }
        }

        function generateExamQuestions() {
            let selectedQuestions = [];
            const rawFilter = examConfig.selectedLessons || [];
            const allowedLessons = (Array.isArray(rawFilter) ? rawFilter : [rawFilter])
                .map(l => String(l || '').trim().toLowerCase().replace(/\s+/g, ' '))
                .filter(Boolean);
            const allowedSet = new Set(allowedLessons);
            const filterByLesson = (q) => {
                if (allowedSet.size === 0) return false;
                const qLesson = String(q.lesson || '').trim().toLowerCase().replace(/\s+/g, ' ');
                return allowedSet.has(qLesson);
            };
            const shuffle = (arr) => [...arr].sort(() => Math.random() - 0.5);

            let filteredQuestions = questions;
            
            // Lọc theo người tạo cấu hình đề thi
            if (examConfig.creatorId) {
                filteredQuestions = filteredQuestions.filter(q => String(q.creatorId) === String(examConfig.creatorId));
            } else {
                const studentTeacherFilter = document.getElementById('student-teacher-filter')?.value;
                const isConfigTabActive = document.getElementById('exams-panel') && !document.getElementById('exams-panel').classList.contains('hidden');
                if (isConfigTabActive) {
                    const examTeacherFilter = document.getElementById('exam-teacher-filter')?.value;
                    if (examTeacherFilter) {
                        filteredQuestions = filteredQuestions.filter(q => String(q.creatorId) === String(examTeacherFilter));
                    } else if (currentUser && currentUser.role !== 'admin') {
                        filteredQuestions = filteredQuestions.filter(q => String(q.creatorId) === String(currentUser.id));
                    }
                } else if (studentTeacherFilter) {
                    filteredQuestions = filteredQuestions.filter(q => String(q.creatorId) === String(studentTeacherFilter));
                }
            }

            // Helper to get questions by type and level
            const getQuestions = (type, level) => filteredQuestions.filter(q => q.type === type && q.level === level && filterByLesson(q));
            const getAllQuestionsByType = (type) => filteredQuestions.filter(q => q.type === type && filterByLesson(q));

            const pushQuestions = (type, count, nb, th, vd) => {
                const sum = (nb || 0) + (th || 0) + (vd || 0);
                if (sum > 0) {
                    selectedQuestions.push(...shuffle(getQuestions(type, 'NB')).slice(0, nb || 0));
                    selectedQuestions.push(...shuffle(getQuestions(type, 'TH')).slice(0, th || 0));
                    selectedQuestions.push(...shuffle(getQuestions(type, 'VD')).slice(0, vd || 0));
                } else if ((count || 0) > 0) {
                    selectedQuestions.push(...shuffle(getAllQuestionsByType(type)).slice(0, count));
                }
            };

            pushQuestions('4-1', examConfig.count41, examConfig.count41NB, examConfig.count41TH, examConfig.count41VD);
            pushQuestions('TF4', examConfig.countTF4, examConfig.countTF4NB, examConfig.countTF4TH, examConfig.countTF4VD);
            pushQuestions('SQ', examConfig.countSQ, examConfig.countSQNB, examConfig.countSQTH, examConfig.countSQVD);
            pushQuestions('TL', examConfig.countTL, examConfig.countTLNB, examConfig.countTLTH, examConfig.countTLVD);

            // Shuffle all questions
            selectedQuestions = shuffle(selectedQuestions);

            // Track question usage
            selectedQuestions.forEach(q => {
                q.usageCount = (q.usageCount || 0) + 1;
            });
            saveQuestionsToDB(selectedQuestions);

            return selectedQuestions.map(q => ({
                ...q,
                shuffledOptions: (q.type === '4-1' || q.type === 'TF4') ? shuffle(['A', 'B', 'C', 'D']) : null
            }));
        }

        window.scrollToTimerHeader = function scrollToTimerHeader() {
            const header = document.getElementById('exam-interface');
            if (header) {
                header.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        };

        // ==================== HỆ THỐNG ÂM THANH CẢNH BÁO THỜI GIAN LÀM BÀI ====================
        let examAudioContext = null;

        function getExamAudioContext() {
            if (!examAudioContext && typeof window !== 'undefined') {
                const AudioCtx = window.AudioContext || window.webkitAudioContext;
                if (AudioCtx) {
                    examAudioContext = new AudioCtx();
                }
            }
            if (examAudioContext && examAudioContext.state === 'suspended') {
                examAudioContext.resume().catch(() => {});
            }
            return examAudioContext;
        }

        function playCountdownTickSound(urgencyLevel) {
            try {
                const ctx = getExamAudioContext();
                if (!ctx) return;
                const now = ctx.currentTime;

                if (urgencyLevel === 'standard') {
                    // Còn 30s đến 16s: Tiếng tích nhịp nhàng đều đặn (880Hz -> 320Hz giòn như đồng hồ đếm ngược)
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();

                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(880, now);
                    osc.frequency.exponentialRampToValueAtTime(320, now + 0.045);

                    gain.gain.setValueAtTime(0.28, now);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.045);

                    osc.connect(gain);
                    gain.connect(ctx.destination);

                    osc.start(now);
                    osc.stop(now + 0.045);
                } else if (urgencyLevel === 'urgent') {
                    // Còn 15s đến 1s: Tiếng tích dồn dập, nhanh hơn, liên tục gấp đôi (2 nhịp tích / giây)
                    // Nhịp 1 (t = now)
                    const osc1 = ctx.createOscillator();
                    const gain1 = ctx.createGain();
                    osc1.type = 'sine';
                    osc1.frequency.setValueAtTime(1046, now); // Nốt C6 cao
                    osc1.frequency.exponentialRampToValueAtTime(450, now + 0.04);
                    gain1.gain.setValueAtTime(0.35, now);
                    gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.04);
                    osc1.connect(gain1);
                    gain1.connect(ctx.destination);
                    osc1.start(now);
                    osc1.stop(now + 0.04);

                    // Nhịp 2 (t = now + 0.28s) - dồn dập báo nộp bài gấp
                    const osc2 = ctx.createOscillator();
                    const gain2 = ctx.createGain();
                    osc2.type = 'sine';
                    osc2.frequency.setValueAtTime(1318, now + 0.28); // Nốt E6 cao
                    osc2.frequency.exponentialRampToValueAtTime(500, now + 0.32);
                    gain2.gain.setValueAtTime(0.4, now + 0.28);
                    gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.32);
                    osc2.connect(gain2);
                    gain2.connect(ctx.destination);
                    osc2.start(now + 0.28);
                    osc2.stop(now + 0.32);
                }
            } catch (err) {
                console.warn('Audio tick playback error:', err);
            }
        }

        function startTimer() {
            const timerEl = document.getElementById('exam-timer');
            const floatingTimerEl = document.getElementById('floating-exam-timer');
            const floatingTextEl = document.getElementById('floating-timer-text');

            if (floatingTimerEl) {
                floatingTimerEl.classList.remove('hidden');
                floatingTimerEl.classList.add('flex');
            }

            const totalSeconds = examConfig.timeLimit * 60;
            if (totalSeconds <= 0) return;

            // Khởi tạo và mở khóa âm thanh ngay khi bắt đầu tính giờ
            try { getExamAudioContext(); } catch(e) {}

            currentExam.timerInterval = setInterval(() => {
                const elapsed = Math.floor((Date.now() - currentExam.startTime) / 1000);
                const remaining = Math.max(0, totalSeconds - elapsed);

                const minutes = Math.floor(remaining / 60);
                const seconds = remaining % 60;
                const timeFormatted = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

                if (timerEl) {
                    timerEl.textContent = timeFormatted;
                    if (remaining <= 15) {
                        timerEl.classList.remove('text-purple-600', 'text-amber-500');
                        timerEl.classList.add('text-rose-600', 'pulse-anim', 'font-black');
                    } else if (remaining <= 30) {
                        timerEl.classList.remove('text-purple-600');
                        timerEl.classList.add('text-amber-500', 'pulse-anim');
                    } else if (remaining <= 60) {
                        timerEl.classList.add('text-purple-600', 'pulse-anim');
                    }
                }

                if (floatingTextEl) {
                    floatingTextEl.textContent = timeFormatted;
                    if (remaining <= 15) {
                        floatingTimerEl?.classList.remove('border-amber-400/80', 'bg-rose-950/95');
                        floatingTimerEl?.classList.add('border-rose-500', 'bg-rose-900', 'animate-bounce');
                        floatingTextEl.classList.remove('text-amber-300');
                        floatingTextEl.classList.add('text-white', 'font-black');
                    } else if (remaining <= 30) {
                        floatingTimerEl?.classList.remove('border-amber-400/80');
                        floatingTimerEl?.classList.add('border-rose-500', 'bg-rose-950/95', 'animate-pulse');
                        floatingTextEl.classList.remove('text-amber-300');
                        floatingTextEl.classList.add('text-rose-300');
                    } else if (remaining <= 60) {
                        floatingTimerEl?.classList.remove('border-amber-400/80');
                        floatingTimerEl?.classList.add('border-rose-500', 'bg-rose-950/95', 'animate-pulse');
                        floatingTextEl.classList.remove('text-amber-300');
                        floatingTextEl.classList.add('text-rose-300');
                    } else {
                        floatingTimerEl?.classList.add('border-amber-400/80');
                        floatingTimerEl?.classList.remove('border-rose-500', 'bg-rose-950/95', 'bg-rose-900', 'animate-pulse', 'animate-bounce');
                        floatingTextEl.classList.add('text-amber-300');
                        floatingTextEl.classList.remove('text-rose-300', 'text-white', 'font-black');
                    }
                }

                // ==================== ÂM THANH CẢNH BÁO THỜI GIAN ====================
                // Khi còn <= 30 giây và > 15 giây: phát tiếng tích, tích, tích nhịp nhàng báo hiệu sắp hết giờ
                if (remaining <= 30 && remaining > 15) {
                    if (currentExam._lastTickSecond !== remaining) {
                        currentExam._lastTickSecond = remaining;
                        playCountdownTickSound('standard');
                    }
                }
                // Khi còn <= 15 giây và > 0: phát tiếng tích nhanh hơn, liên tục dồn dập báo nộp bài gấp
                else if (remaining <= 15 && remaining > 0) {
                    if (currentExam._lastTickSecond !== remaining) {
                        currentExam._lastTickSecond = remaining;
                        playCountdownTickSound('urgent');
                    }
                }

                if (remaining === 0) {
                    clearInterval(currentExam.timerInterval);
                    playCountdownTickSound('standard');
                    submitExam(true);
                }
            }, 1000);
        }

        function renderQuestionNav() {
            const nav = document.getElementById('question-nav');
            if (!nav) return;
            const immediateFeedbackOn = examConfig.immediateFeedback !== undefined ? examConfig.immediateFeedback : appSettings.immediateFeedback;

            nav.innerHTML = currentExam.questions.map((q, i) => {
                const isAnswered = currentExam.answers[i] !== undefined;
                const isCurrent = i === currentExam.currentIndex;
                
                let btnClass = 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200';
                
                if (immediateFeedbackOn && isAnswered) {
                    let isAllCorrect = false;
                    if (q.type === '4-1') {
                        isAllCorrect = currentExam.answers[i] === q.answer;
                    } else if (q.type === 'TF4') {
                        const correctAnswers = (q.answer || '').split('&');
                        const ans = currentExam.answers[i] || {};
                        const keys = Object.keys(ans);
                        isAllCorrect = keys.length > 0 && keys.every(k => (ans[k] === true && correctAnswers.includes(k)) || (ans[k] === false && !correctAnswers.includes(k)));
                    } else if (q.type === 'SQ') {
                        isAllCorrect = isSQCorrect(currentExam.answers[i], q.answer);
                    }

                    if (isCurrent) {
                        btnClass = isAllCorrect
                            ? 'current ring-2 ring-emerald-500 ring-offset-2 bg-emerald-600 text-white shadow-md transform scale-110'
                            : 'current ring-2 ring-rose-500 ring-offset-2 bg-rose-600 text-white shadow-md transform scale-110';
                    } else {
                        btnClass = isAllCorrect
                            ? 'answered bg-emerald-500 text-white shadow-sm border-emerald-600'
                            : 'answered bg-rose-500 text-white shadow-sm border-rose-600';
                    }
                } else {
                    if (isCurrent) {
                        btnClass = 'current ring-2 ring-indigo-500 ring-offset-2 bg-indigo-600 text-white shadow-md transform scale-110';
                    } else if (isAnswered) {
                        btnClass = 'answered bg-emerald-500 text-white shadow-sm border-emerald-600';
                    }
                }
                
                return `<button onclick="goToQuestion(${i})" class="question-nav-btn w-6 h-6 md:w-7 md:h-7 text-[10px] md:text-xs rounded-md font-semibold transition-all duration-200 ${btnClass}">${i + 1}</button>`;
            }).join('');

            // Chỉ cuộn nội bộ bên trong hộp #question-nav, tuyệt đối không gọi scrollIntoView làm nhảy vị trí trang của học sinh
            const currentBtn = nav.querySelector('.question-nav-btn.current');
            if (currentBtn && nav.scrollHeight > nav.clientHeight) {
                const btnTop = currentBtn.offsetTop - nav.offsetTop;
                if (btnTop < nav.scrollTop || btnTop + currentBtn.offsetHeight > nav.scrollTop + nav.clientHeight) {
                    nav.scrollTop = Math.max(0, btnTop - (nav.clientHeight / 2) + (currentBtn.offsetHeight / 2));
                }
            }
        }

