        window.updateQuestion = function updateQuestion(id) {
            try {
                const idStr = String(id);
                const q = questions.find(q => String(q.id) === idStr);
                if (!q) {
                    showToast('❌ Không tìm thấy câu hỏi!', 'error');
                    return;
                }

                if (!isAdminLoggedIn && currentUser && q.creatorId && q.creatorId !== currentUser.id) {
                    showToast('❌ Bạn không có quyền chỉnh sửa câu hỏi này!', 'error');
                    return;
                }

                q.content = document.getElementById('edit-q-content')?.value?.trim() || '';
                q.lesson = document.getElementById('edit-q-lesson')?.value?.trim().toUpperCase() || '';
                q.level = document.getElementById('edit-q-level')?.value || '';
                const answerRaw = document.getElementById('edit-q-answer')?.value?.trim() || '';
                q.answer = q.type === 'TL' ? answerRaw : answerRaw.toUpperCase();

                // Update question image
                const imgPreview = document.getElementById('edit-q-image-preview');
                if (imgPreview && !imgPreview.classList.contains('hidden') && imgPreview.getAttribute('src')) {
                    q.image = imgPreview.src;
                } else {
                    q.image = '';
                }

                if (q.type === '4-1' || q.type === 'TF4') {
                    if (!q.options || typeof q.options !== 'object') q.options = {};
                    ['A', 'B', 'C', 'D'].forEach(opt => {
                        const optInput = document.getElementById(`edit-q-opt-${opt}`);
                        const optText = optInput ? optInput.value.trim() : '';
                        const optImgPreview = document.getElementById(`edit-q-opt-preview-${opt}`);
                        let optImg = '';
                        
                        if (optImgPreview && !optImgPreview.classList.contains('hidden') && optImgPreview.getAttribute('src')) {
                            optImg = optImgPreview.src;
                        }

                        q.options[opt] = {
                            text: optText,
                            image: optImg
                        };
                    });
                } else {
                    // For SQ and TL, handle answer image
                    const ansImgPreview = document.getElementById('edit-q-answer-image-preview');
                    if (!q.options || typeof q.options !== 'object') q.options = {};
                    if (ansImgPreview && !ansImgPreview.classList.contains('hidden') && ansImgPreview.getAttribute('src')) {
                        q.options.answerImage = ansImgPreview.src;
                    } else {
                        delete q.options.answerImage;
                    }
                }

                saveQuestionsToDB([q]);
                closeModal();
                try { updateQuestionStats(); } catch(e) { console.warn(e); }
                try { updateLessonFilter(); } catch(e) { console.warn(e); }
                try { renderQuestionsList(); } catch(e) { console.warn(e); }
                
                // Cập nhật thống kê và kiểm tra lại cấu hình đề thi
                try { updateExamGlobalStats(); } catch(e) { console.warn(e); }
                try { checkExamConfigSufficiency(); } catch(e) { console.warn(e); }
                
                // 🔄 RELOAD QL ĐỀ THI
                try {
                    if (document.getElementById('exams-panel') && !document.getElementById('exams-panel').classList.contains('hidden')) {
                        console.log('🔄 Reloading Exam Panel after editing question...');
                        initExamPanel();
                    }
                } catch(e) { console.warn(e); }
                
                showToast('Đã cập nhật câu hỏi! QL Đề thi đã cập nhật.', 'success');
            } catch (err) {
                console.error('Lỗi khi cập nhật câu hỏi:', err);
                showToast('❌ Có lỗi khi cập nhật: ' + err.message, 'error');
            }
        };

        function checkExamConfigSufficiency() {
            // Check if enough questions for current exam config
            const total = examConfig.count41 + examConfig.countTF4 + examConfig.countSQ;
            console.log('Checking exam config sufficiency. Total:', total, 'ExamConfig:', examConfig);
            
            const examConfigSelect = document.getElementById('exam-config-name');
            const hasSelectedConfig = examConfigSelect && examConfigSelect.value.trim() !== '';

            if (total > 0 && hasSelectedConfig && questionsLoaded) {
                // Use setTimeout to ensure UI updates are processed before checking
                setTimeout(() => {
                    let filteredQuestions = questions;
                    if (currentUser && currentUser.role !== 'admin' && isTeacherLoggedIn) {
                        filteredQuestions = questions.filter(q => q.creatorId === currentUser.id);
                    }
                    // Use actual lesson filtering
                    const rawFilter = examConfig.selectedLessons || [];
                    const allowedLessons = (Array.isArray(rawFilter) ? rawFilter : [rawFilter])
                        .map(l => String(l || '').trim().toLowerCase().replace(/\s+/g, ' '))
                        .filter(Boolean);
                    const allowedSet = new Set(allowedLessons);
                    const filterByLesson = (q) => {
                        if (allowedSet.size === 0) return false;
                        const qLesson = String(q.lesson || '').trim().toLowerCase().replace(/\s+/g, ' ');
                        return allowedSet.has(qLesson);
                    };
                    const getCount = (type, level) => filteredQuestions.filter(q => q.type === type && q.level === level && filterByLesson(q)).length;
                    
                    let isEnough = checkExamQuestionsAvailability(examConfig, getCount);

                    if (!isEnough) {
                        showToast('⚠️ Cảnh báo: Ngân hàng câu hỏi hiện không đủ số lượng cho cấu hình đề thi đang áp dụng!', 'warning', 'small');
                    }
                }, 100);
            }
        }

        window.deleteQuestion = function deleteQuestion(id) {
            const idStr = String(id);
            const q = questions.find(q => String(q.id) === idStr);
            if (!q) return;

            if (!isAdminLoggedIn && currentUser && q.creatorId && q.creatorId !== currentUser.id) {
                showToast('❌ Bạn không có quyền xóa câu hỏi này!', 'error');
                return;
            }

            showConfirmModal('Bạn có chắc muốn xóa câu hỏi này?', () => {
                questions = questions.filter(q => String(q.id) !== idStr);
                selectedQuestionIds.delete(idStr);
                saveQuestionsToDB(null, [idStr]);
                updateStats();
                updateQuestionStats();
                updateAvailableCounts();
                updateExamGlobalStats();
                updateLessonFilter();
                renderQuestionsList();
                showToast('Đã xóa câu hỏi!', 'success');

                checkExamConfigSufficiency();
            });
        }

