            if (document.getElementById('usr-payment-status')) document.getElementById('usr-payment-status').value = usr.payment_status || 'Chưa thanh toán';
            if (document.getElementById('usr-payment-method')) document.getElementById('usr-payment-method').value = usr.payment_method || '';
            
