            if (document.getElementById('usr-address')) document.getElementById('usr-address').value = usr.address || '';
            if (document.getElementById('usr-donvi')) document.getElementById('usr-donvi').value = usr.donvi || '';
            if (document.getElementById('usr-lop')) document.getElementById('usr-lop').value = usr.lop || '';
