        // Cập nhật thanh trạng thái tóm tắt Key trên giao diện chính của form tạo câu hỏi
        window.updateAIKeySummaryUI = function() {
            const bar = document.getElementById('ai-key-summary-bar');
            const btnLabel = document.getElementById('ai-key-btn-label');
            const inputEl = document.getElementById('ai-api-key');
            if (!bar) return;

            let keyStr = inputEl ? inputEl.value.trim() : '';
            if (!keyStr) {
                keyStr = window.currentUser?.username
                    ? (localStorage.getItem('gemini_api_key_' + window.currentUser.username) || localStorage.getItem('gemini_api_key') || '')
                    : (localStorage.getItem('gemini_api_key') || '');
            }

            const validKeys = keyStr.split(/\s+/).filter(k => k.length > 5 && !k.includes("••••••••") && !k.includes("YOUR_"));
            const count = validKeys.length;

            if (count > 0) {
                bar.className = 'p-3 rounded-xl border border-emerald-200 bg-emerald-50/80 flex items-center justify-between text-xs transition';
                bar.innerHTML = `
                    <div class="flex items-center gap-2">
                        <span class="text-base text-emerald-600">✅</span>
                        <div>
                            <span class="font-bold text-emerald-900">${count === 1 ? 'Đã cài đặt 1 API Key' : `Đã cài đặt ${count} API Key`}</span>
                            <span class="text-emerald-700 text-[11px] block sm:inline sm:ml-1 font-medium">(Tự động chuyển key khi hết hạn mức)</span>
                        </div>
                    </div>
                    <button type="button" onclick="toggleAIKeySettingsForm(true)" class="text-xs font-bold text-emerald-800 hover:text-emerald-950 underline shrink-0 cursor-pointer">
                        Đổi Key
                    </button>
                `;
                if (btnLabel) btnLabel.innerText = `Cài đặt Key (${count})`;
            } else {
                bar.className = 'p-3 rounded-xl border border-amber-200 bg-amber-50/80 flex items-center justify-between text-xs transition';
                bar.innerHTML = `
                    <div class="flex items-center gap-2">
                        <span class="text-base text-amber-600">⚠️</span>
                        <div>
                            <span class="font-bold text-amber-900">Chưa cài đặt Gemini API Key</span>
                            <span class="text-amber-700 text-[11px] block sm:inline sm:ml-1 font-medium">(Cần key để AI tạo câu hỏi)</span>
                        </div>
                    </div>
                    <button type="button" onclick="toggleAIKeySettingsForm(true)" class="px-3 py-1 bg-amber-600 hover:bg-amber-700 text-white rounded-lg text-xs font-bold transition shadow-xs shrink-0 cursor-pointer">
                        Cài đặt ngay
                    </button>
                `;
                if (btnLabel) btnLabel.innerText = 'Cài đặt Key';
            }
        };

        // Chuyển đổi hiển thị giữa Form tạo câu hỏi chính và Form cài đặt Key
        window.toggleAIKeySettingsForm = function(show) {
            const mainForm = document.getElementById('ai-generate-main-form');
            const settingsForm = document.getElementById('ai-key-settings-form');
            if (!mainForm || !settingsForm) return;

            if (show) {
                mainForm.classList.add('hidden');
                settingsForm.classList.remove('hidden');
            } else {
                settingsForm.classList.add('hidden');
                mainForm.classList.remove('hidden');
                updateAIKeySummaryUI();
            }
            const modalEl = document.getElementById('modal-content');
            if (modalEl) {
                modalEl.classList.add('always-scrollbar-y');
            }
        };

        // Lưu cấu hình key và trở về form tạo câu hỏi chính
        window.saveAIKeySettingsAndApply = function() {
            const inputEl = document.getElementById('ai-api-key');
            if (inputEl) {
                const key = inputEl.value.trim();
                if (window.currentUser?.username) {
                    localStorage.setItem('gemini_api_key_' + window.currentUser.username, key);
                } else {
                    localStorage.setItem('gemini_api_key', key);
                }
            }
            updateAIKeySummaryUI();
            toggleAIKeySettingsForm(false);
            showToast('Đã lưu cấu hình API Key thành công!', 'success');
        };

        // Kiểm tra trạng thái danh sách Key ngay trong Modal Tạo câu hỏi AI
        window.validateModalAIKeys = async function() {
            const inputEl = document.getElementById('ai-api-key');
            const reportEl = document.getElementById('ai-modal-key-report');
            if (!inputEl) return;
            const val = inputEl.value.trim();
            if (!val) {
                showToast('Vui lòng nhập ít nhất một Gemini API Key để kiểm tra.', 'warning');
                return;
            }
            const rawKeys = val.split(/\s+/).filter(k => k.length > 5);
            if (rawKeys.length === 0) {
                showToast('Định dạng API Key không hợp lệ hoặc quá ngắn.', 'error');
                return;
            }
            if (reportEl) {
                reportEl.classList.remove('hidden');
                reportEl.innerHTML = `<div class="p-2.5 bg-indigo-50 border border-indigo-200 rounded-lg text-xs text-indigo-700 font-medium flex items-center gap-2"><span class="animate-spin">⏳</span> Đang kiểm tra chi tiết ${rawKeys.length} API Key...</div>`;
            }
            try {
                const results = await Promise.all(rawKeys.map(k => testSingleGeminiKey(k)));
                window.lastModalValidationReports = results;
                const total = results.length;
                const active = results.filter(r => r.ok).length;
                const failed = total - active;

                if (!reportEl) return;

                if (failed === 0) {
                    reportEl.innerHTML = `
                        <div class="p-2.5 bg-emerald-50 border border-emerald-200 rounded-lg text-xs text-emerald-800 space-y-1">
                            <div class="font-bold flex items-center gap-1.5"><span>✅</span> Tất cả ${total} API Key đều hoạt động tốt!</div>
                            <div class="text-[11px] text-emerald-700 font-medium">Hệ thống đã sẵn sàng tạo câu hỏi và tự động chuyển key khi cần.</div>
                        </div>
                    `;
                    showToast(`✅ Tất cả ${total} API Key đều hoạt động tốt!`, 'success');
                } else if (active > 0) {
                    reportEl.innerHTML = `
                        <div class="p-2.5 bg-amber-50 border border-amber-200 rounded-lg text-xs space-y-2">
                            <div class="flex items-center justify-between">
                                <span class="font-bold text-amber-900 flex items-center gap-1"><span>⚠️</span> Phát hiện ${failed}/${total} Key gặp sự cố</span>
                                <button type="button" onclick="showAIKeyIssueModal({ title: 'Chi tiết sự cố các API Key', message: 'Hệ thống đã kiểm tra và phát hiện một số key bị hết hạn mức hoặc lỗi.', keyReports: window.lastModalValidationReports })" class="text-[11px] text-amber-800 underline font-bold hover:text-amber-950">Xem chi tiết</button>
                            </div>
                            <div class="space-y-1">
                                ${results.map((r, i) => `
                                    <div class="flex items-center justify-between text-[11px] p-1 bg-white rounded border ${r.ok ? 'border-emerald-200 text-emerald-800' : 'border-amber-200 text-amber-900'}">
                                        <span class="font-mono">Key ${i+1} (${r.maskedKey}):</span>
                                        <span class="font-medium">${r.ok ? 'Tốt ✅' : `${r.title} ⚠️`}</span>
                                    </div>
                                `).join('')}
                            </div>
                            <p class="text-[11px] text-amber-800 font-medium">👉 Hệ thống vẫn có thể tạo câu hỏi nhờ <strong>${active} key còn lại</strong>.</p>
                        </div>
                    `;
                    showToast(`⚠️ Có ${failed}/${total} Key gặp sự cố, bạn nên thay thế kịp thời.`, 'warning');
                } else {
                    reportEl.innerHTML = `
                        <div class="p-2.5 bg-rose-50 border border-rose-200 rounded-lg text-xs space-y-2">
                            <div class="flex items-center justify-between">
                                <span class="font-bold text-rose-900 flex items-center gap-1"><span>🛑</span> Toàn bộ ${total} Key đều không thể sử dụng!</span>
                                <button type="button" onclick="showAIKeyIssueModal({ title: 'Khắc phục toàn bộ API Key bị lỗi', message: 'Tất cả API Key trong danh sách đều đã hết hạn mức hoặc không hợp lệ.', keyReports: window.lastModalValidationReports })" class="text-[11px] text-rose-800 underline font-bold hover:text-rose-950">Xem cách khắc phục</button>
                            </div>
                            <div class="space-y-1">
                                ${results.map((r, i) => `
                                    <div class="flex items-center justify-between text-[11px] p-1 bg-white rounded border border-rose-200 text-rose-900">
                                        <span class="font-mono">Key ${i+1} (${r.maskedKey}):</span>
                                        <span class="font-medium">${r.title} ❌</span>
                                    </div>
                                `).join('')}
                            </div>
                            <div class="flex items-center justify-between pt-0.5">
                                <span class="text-[11px] text-rose-700 font-medium">Vui lòng lấy key mới từ Google AI Studio.</span>
                                <a href="https://aistudio.google.com/app/apikey" target="_blank" class="px-2 py-0.5 bg-rose-600 hover:bg-rose-700 text-white rounded text-[11px] font-bold shadow-xs">Lấy Key ↗</a>
                            </div>
                        </div>
                    `;
                    showToast('🛑 Toàn bộ API Key đều không thể sử dụng!', 'error');
                }
            } catch (err) {
                console.error('Lỗi kiểm tra key trong modal:', err);
            }
        };

        window.generateQuestionsWithAI = async function() {
            if (!navigator.onLine) {
                showToast('Không có kết nối internet, vui lòng kiểm tra lại.', 'error');
                return;
            }

            const module = await loadGoogleAI();
            if (!module) {
                showToast('Không thể tải thư viện AI. Vui lòng kiểm tra kết nối mạng.', 'error');
                return;
            }
            const { GoogleGenAI, Type } = module;

            const apiKey = document.getElementById('ai-api-key')?.value?.trim() || '';
            const topic = document.getElementById('ai-q-topic')?.value?.trim() || '';
            const type = document.getElementById('ai-q-type')?.value || '';
            const level = document.getElementById('ai-q-level')?.value || '';
            let count = parseInt(document.getElementById('ai-q-count')?.value) || 5;
            if (count > 10) count = 10;
            if (count < 1) count = 1;
            const lesson = document.getElementById('ai-q-lesson')?.value?.trim().toUpperCase() || 'AI GENERATED';
            
            const validKeys = apiKey.split(/\s+/).filter(k => k.length > 5 && !k.includes("••••••••") && !k.includes("YOUR_"));
            if (validKeys.length === 0) {
                showToast('Vui lòng cài đặt ít nhất một Gemini API Key trước khi bắt đầu tạo câu hỏi!', 'warning');
                toggleAIKeySettingsForm(true);
                return;
            }
            if (!topic) {
                showToast('Vui lòng nhập chủ đề hoặc nội dung kiến thức!', 'error');
                return;
            }

            // Lưu API Key cá nhân của tài khoản hiện tại vào localStorage để không phải nhập lại
            if (window.currentUser?.username) { 
                localStorage.setItem('gemini_api_key_' + window.currentUser.username, apiKey); 
            } else { 
                localStorage.setItem('gemini_api_key', apiKey); 
            }

            window.lastAIGeneration = { apiKey, topic, type, level, count, lesson };

            const btn = document.getElementById('btn-ai-generate');
            const status = document.getElementById('ai-generate-status');
            
            btn.disabled = true;
            btn.innerHTML = `
                <svg class="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24">
                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Đang tạo... (tối đa 60s)
            `;
            btn.classList.add('opacity-70', 'cursor-not-allowed');
            status.classList.remove('hidden');

            try {
                const ai = new GoogleGenAI({ apiKey });
                let allGeneratedQuestions = [];
                const chunkSize = 10;
                for (let i = 0; i < count; i += chunkSize) {
                    const currentChunkSize = Math.min(chunkSize, count - i);
                    status.innerText = `Đang tạo câu ${i + 1}-${Math.min(i + chunkSize, count)}/${count}...`;

                    const generatePromise = ai.models.generateContent({
                        model: "gemini-3.8-flash",
                        config: {
                            thinkingConfig: { thinkingLevel: "LOW" },
                            responseMimeType: "application/json",
                            responseSchema: {
                                type: Type.ARRAY,
                                items: {
                                    type: Type.OBJECT,
                                    properties: {
                                        type: { type: Type.STRING, description: "Loại câu hỏi: '4-1', 'TF4', 'SQ', hoặc 'TL'" },
                                        level: { type: Type.STRING, description: "Mức độ: 'NB', 'TH', hoặc 'VD'" },
                                        content: { type: Type.STRING, description: "Nội dung câu hỏi, hỗ trợ LaTeX $...$" },
                                        answer: { type: Type.STRING, description: "Đáp án đúng. 4-1: A/B/C/D. TF4: các ý đúng cách nhau bởi &, VD: A&C. SQ: kết quả ngắn. TL: hướng dẫn chấm." },
                                        options: {
                                            type: Type.OBJECT,
                                            properties: {
                                                A: { type: Type.OBJECT, properties: { text: { type: Type.STRING } } },
                                                B: { type: Type.OBJECT, properties: { text: { type: Type.STRING } } },
                                                C: { type: Type.OBJECT, properties: { text: { type: Type.STRING } } },
                                                D: { type: Type.OBJECT, properties: { text: { type: Type.STRING } } }
                                            }
                                        }
                                    },
                                    required: ["type", "level", "content", "answer"]
                                }
                            }
                        },
                        contents: [{
                            parts: [{
                                text: (appSettings.aiPrompt || DEFAULT_AI_PROMPT)
                                    .replace('{count}', currentChunkSize)
                                    .replace('{topic}', topic)
                                    .replace('{type}', type === 'MIXED' ? 'Hỗn hợp 4-1, TF4, SQ, TL' : type)
                                    .replace('{level}', level === 'MIXED' ? 'Hỗn hợp NB, TH, VD' : level)
                            }]
                        }]
                    });

                    const timeoutPromise = new Promise((_, reject) => {
                        setTimeout(() => reject(new Error('Quá thời gian chờ (60 giây). Vui lòng thử lại hoặc giảm số lượng câu hỏi.')), 60000);
                    });

                    const response = await Promise.race([generatePromise, timeoutPromise]);
                    const generatedQuestions = JSON.parse(response.text);
                    if (Array.isArray(generatedQuestions)) {
                        allGeneratedQuestions.push(...generatedQuestions);
                    } else {
                        throw new Error('Dữ liệu AI trả về không phải là một mảng.');
                    }
                }
                window.tempGeneratedQuestions = [];
                allGeneratedQuestions.forEach(q => {
                        let parsedType = String(q.type || '').trim().toUpperCase();
                        let parsedLevel = String(q.level || '').trim().toUpperCase();

                        const validTypes = ['4-1', 'TF4', 'SQ', 'TL'];
                        const validLevels = ['NB', 'TH', 'VD', 'VDC'];

                        // 1. Tự động phát hiện nếu AI ghi nhầm hoặc hoán đổi cột Mức độ (level) và Loại (type)
                        if (validLevels.includes(parsedType) && validTypes.includes(parsedLevel)) {
                            const temp = parsedType;
                            parsedType = parsedLevel;
                            parsedLevel = temp;
                        }

                        // 2. Dự phòng chuẩn hóa cột Loại câu hỏi nếu sai lệch hoặc không hợp lệ
                        if (!validTypes.includes(parsedType)) {
                            parsedType = (type && type !== 'MIXED') ? type : '4-1';
                        }

                        // 3. Dự phòng chuẩn hóa cột Mức độ câu hỏi nếu sai lệch hoặc không hợp lệ
                        if (!validLevels.includes(parsedLevel)) {
                            parsedLevel = (level && level !== 'MIXED') ? level : 'NB';
                        }

                        let newQ = {
                            id: generateUUID(),
                            type: parsedType,
                            lesson: lesson,
                            level: parsedLevel,
                            content: q.content || '',
                            answer: parsedType === 'TL' ? String(q.answer || '') : String(q.answer || '').toUpperCase(),
                            image: '',
                            options: {},
                            usageCount: 0,
                            creatorId: currentUser ? currentUser.id : null
                        };
                        
                        if (newQ.type === '4-1' || newQ.type === 'TF4') {
                            ['A', 'B', 'C', 'D'].forEach(opt => {
                                let optText = '';
                                if (q.options && q.options[opt]) {
                                    optText = typeof q.options[opt] === 'object' ? q.options[opt].text : q.options[opt];
                                }
                                newQ.options[opt] = { text: optText || '', image: '' };
                            });
                        }

                        newQ = sanitizeQuestionFormulas(newQ);

                        window.tempGeneratedQuestions.push(newQ);
                    });

                    showAIGeneratedPreview(window.tempGeneratedQuestions);

            } catch (error) {
                console.error('AI Generation Error:', error);
                let errorMsg = error.message || 'Lỗi không xác định';
                const lower = errorMsg.toLowerCase();
                if (lower.includes('api key') || lower.includes('quota') || lower.includes('429') || lower.includes('hạn mức') || lower.includes('resource_exhausted') || lower.includes('không thể sử dụng') || lower.includes('location') || lower.includes('failed_precondition')) {
                    const keys = apiKey.split(/\s+/).filter(k => k.length > 5);
                    let reports = [];
                    try {
                        reports = await Promise.all(keys.map(k => testSingleGeminiKey(k)));
                    } catch {
                        reports = keys.map((k, idx) => ({
                            status: 'quota_exceeded',
                            maskedKey: k.length > 10 ? `${k.substring(0, 6)}...${k.substring(k.length - 4)}` : k,
                            title: 'Hết hạn mức / Lỗi kết nối',
                            message: 'Không thể xử lý yêu cầu lúc này'
                        }));
                    }
                    showAIKeyIssueModal({
                        title: 'Sự cố API Key: Không thể tạo câu hỏi',
                        message: `Hệ thống đã cố gắng chạy lần lượt qua ${keys.length > 1 ? `tất cả ${keys.length} API Key trong danh sách` : 'API Key của bạn'} nhưng đều bị Google từ chối do hết hạn mức (Quota exceeded / Rate Limit), lỗi mạng hoặc key không hợp lệ.`,
                        keyReports: reports
                    });
                } else {
                    showToast('Lỗi khi tạo câu hỏi: ' + errorMsg, 'error');
                }
            } finally {
                btn.disabled = false;
                btn.innerHTML = '<span>✨</span></u> Bắt đầu tạo';
                btn.classList.remove('opacity-70', 'cursor-not-allowed');
                status.classList.add('hidden');
            }
        };

        function showAIGeneratedPreview(generatedQuestions) {
            let questionsHtml = generatedQuestions.map((q, index) => {
                let optionsHtml;
                if (q.type === '4-1' || q.type === 'TF4') {
                    optionsHtml = `
                        <div class="grid grid-cols-2 gap-2 mt-2 text-sm">
                            <div class="p-2 border rounded ${q.answer === 'A' || (q.type === 'TF4' && q.answer.includes('A')) ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-200'}"><strong>A.</strong> ${formatContent(q.options?.A?.text || '')}</div>
                            <div class="p-2 border rounded ${q.answer === 'B' || (q.type === 'TF4' && q.answer.includes('B')) ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-200'}"><strong>B.</strong> ${formatContent(q.options?.B?.text || '')}</div>
                            <div class="p-2 border rounded ${q.answer === 'C' || (q.type === 'TF4' && q.answer.includes('C')) ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-200'}"><strong>C.</strong> ${formatContent(q.options?.C?.text || '')}</div>
                            <div class="p-2 border rounded ${q.answer === 'D' || (q.type === 'TF4' && q.answer.includes('D')) ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-200'}"><strong>D.</strong> ${formatContent(q.options?.D?.text || '')}</div>
                        </div>
                    `;
                } else {
                    optionsHtml = `
                        <div class="mt-2 text-sm p-2 bg-green-50 border border-green-200 rounded">
                            <strong>Đáp án:</strong> ${formatContent(q.answer)}
                            ${q.options && q.options.answerImage ? `<div class="mt-2 text-xs font-semibold text-green-700">Hình ảnh đáp án:</div><img src="${q.options.answerImage}" class="mt-1 max-w-xs h-auto rounded border border-green-200 cursor-zoom-in" onclick="zoomImage('${q.options.answerImage}')">` : ''}
                        </div>`;
                }

                return `
                    <div id="ai-preview-q-${index}" class="p-4 border-2 border-gray-200 rounded-lg mb-4 relative">
                        <div class="flex items-center gap-2 mb-2">
                            <span class="px-2 py-1 bg-indigo-100 text-indigo-800 text-xs font-bold rounded">Câu ${index + 1}</span></u>
                            <span class="px-2 py-1 bg-gray-100 text-gray-800 text-xs font-bold rounded">${q.type}</span></u>
                            <span class="px-2 py-1 bg-blue-100 text-blue-800 text-xs font-bold rounded">${q.level}</span></u>
                            <span class="px-2 py-1 bg-purple-100 text-purple-800 text-xs font-bold rounded">${q.lesson}</span></u>
                            <button onclick="editAIGeneratedQuestion(${index})" class="ml-auto px-2 py-1 bg-blue-100 text-blue-600 text-xs font-bold rounded hover:bg-blue-200 transition flex items-center gap-1" title="Sửa câu hỏi này">
                                <span>✏️</span></u> Sửa
                            </button>
                            <button onclick="removeAIGeneratedQuestion(${index})" class="px-2 py-1 bg-red-100 text-purple-600 text-xs font-bold rounded hover:bg-red-200 transition flex items-center gap-1" title="Xóa câu hỏi này">
                                <span>🗑️</span></u> Xóa
                            </button>
                        </div>
                        <div class="font-medium text-gray-800 mb-2">${formatContent(q.content)}</div>
                        ${optionsHtml}
                    </div>
                `;
            }).join('');

            const modalContent = `
                <div class="p-6 max-w-4xl w-full mx-auto flex flex-col" style="max-height: 85vh;">
                    <h3 class="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
                        <span class="text-2xl">👀</span></u> Xem trước câu hỏi AI tạo (${generatedQuestions.length} câu)
                    </h3>
                    <div class="overflow-y-auto flex-1 pr-2">
                        ${questionsHtml}
                    </div>
                    <div class="flex justify-end gap-3 mt-6 pt-4 border-t border-gray-200">
                        <button onclick="closeModal()" class="px-4 py-2 text-gray-600 font-semibold hover:bg-gray-100 rounded-lg transition">Hủy bỏ</button>
                        <button id="btn-ai-appraise" onclick="appraiseAIQuestions()" class="px-4 py-2 bg-amber-500 text-white font-bold rounded-lg hover:bg-amber-600 transition shadow-md">Thẩm định</button>
                        <button onclick="confirmAddAIGeneratedQuestions()" class="px-6 py-2 bg-indigo-600 text-white font-bold rounded-lg hover:bg-indigo-700 transition shadow-md">Thêm vào ngân hàng</button>
                    </div>
                </div>
            `;
            showModal(modalContent);
            setTimeout(() => {
                const container = document.getElementById('modal-content');
                if(container) queueMathJax(container);
            }, 100);
        };

        window.removeAIGeneratedQuestion = function(index) {
            window.tempGeneratedQuestions.splice(index, 1);
            if (window.tempGeneratedQuestions.length === 0) {
                closeModal();
            } else {
                showAIGeneratedPreview(window.tempGeneratedQuestions);
            }
        };

        window.editAIGeneratedQuestion = function(index) {
            const q = window.tempGeneratedQuestions[index];
            const modalContent = `
                <div class="p-6 md:p-8 max-w-full">
                    <!-- Header -->
                    <div class="flex flex-wrap items-center justify-between gap-2 pb-4 mb-5 border-b border-gray-100">
                        <div class="flex items-center gap-3">
                            <span class="w-10 h-10 rounded-xl bg-indigo-100 text-indigo-600 flex items-center justify-center text-xl shadow-xs">🤖</span>
                            <div>
                                <h3 class="text-xl md:text-2xl font-bold text-gray-800">Sửa câu hỏi AI tạo (Câu ${index + 1})</h3>
                                <p class="text-xs text-gray-500">Chỉnh sửa nội dung trước khi đưa vào ngân hàng đề</p>
                            </div>
                        </div>
                    </div>

                    <div class="space-y-6">
                        <!-- Phân loại -->
                        <div class="grid grid-cols-1 sm:grid-cols-3 gap-4 bg-gray-50/80 p-4 rounded-xl border border-gray-200/70">
                            <div>
                                <label class="block text-xs font-bold text-gray-700 uppercase tracking-wider mb-1.5">Bài học</label>
                                <input type="text" id="edit-ai-lesson" value="${escapeHTML(q.lesson) || ''}" class="w-full px-3.5 py-2.5 bg-white border border-gray-300 rounded-lg text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 focus:outline-none transition font-medium">
                            </div>
                            <div>
                                <label class="block text-xs font-bold text-gray-700 uppercase tracking-wider mb-1.5">Mức độ</label>
                                <select id="edit-ai-level" class="w-full px-3.5 py-2.5 bg-white border border-gray-300 rounded-lg text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 focus:outline-none transition font-medium">
                                    <option value="NB" ${q.level === 'NB' ? 'selected' : ''}>🟢 Nhận biết (NB)</option>
                                    <option value="TH" ${q.level === 'TH' ? 'selected' : ''}>🔵 Thông hiểu (TH)</option>
                                    <option value="VD" ${q.level === 'VD' ? 'selected' : ''}>🟠 Vận dụng (VD)</option>
                                    <option value="VDC" ${q.level === 'VDC' ? 'selected' : ''}>🔴 Vận dụng cao (VDC)</option>
                                </select>
                            </div>
                            <div>
                                <label class="block text-xs font-bold text-gray-700 uppercase tracking-wider mb-1.5">Loại</label>
                                <select id="edit-ai-type" class="w-full px-3.5 py-2.5 bg-white border border-gray-300 rounded-lg text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 focus:outline-none transition font-medium" onchange="toggleAIEditOptions(this.value)">
                                    <option value="4-1" ${q.type === '4-1' ? 'selected' : ''}>Trắc nghiệm 4-1 (1 đáp án)</option>
                                    <option value="TF4" ${q.type === 'TF4' ? 'selected' : ''}>Đúng / Sai 4 ý (TF4)</option>
                                    <option value="SQ" ${q.type === 'SQ' ? 'selected' : ''}>Tự luận ngắn (SQ)</option>
                                    <option value="TL" ${q.type === 'TL' ? 'selected' : ''}>Tự luận tự do (TL)</option>
                                </select>
                            </div>
                        </div>

                        <!-- Nội dung câu hỏi -->
                        <div>
                            <div class="flex items-center justify-between mb-1.5">
                                <label class="block text-sm font-bold text-gray-800">Nội dung câu hỏi <span class="text-red-500">*</span></label>
                                <span class="text-xs text-indigo-600 font-medium bg-indigo-50 px-2 py-0.5 rounded-md border border-indigo-100">💡 Hỗ trợ LaTeX: $\\frac{a}{b}$, $x^2$, $\\ce{H2O}$</span>
                            </div>
                            <textarea id="edit-ai-content" rows="4" class="w-full px-3.5 py-2.5 border border-gray-300 rounded-xl text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 focus:outline-none transition font-normal">${escapeHTML(q.content)}</textarea>
                        </div>
                        
                        <!-- Options 2-column on desktop -->
                        <div id="ai-edit-options-container" class="${(q.type === 'SQ' || q.type === 'TL') ? 'hidden' : ''}">
                            <div class="flex items-center justify-between mb-3">
                                <label class="block text-sm font-bold text-gray-800">Các phương án đáp án (A, B, C, D):</label>
                                <span class="text-xs text-gray-500">Hiển thị dạng 2 cột trực quan</span>
                            </div>
                            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                                ${['A', 'B', 'C', 'D'].map(opt => `
                                    <div class="p-4 border border-gray-200 rounded-xl bg-white shadow-2xs hover:border-indigo-300 transition">
                                        <div class="flex items-center gap-2.5">
                                            <span class="w-8 h-8 flex-shrink-0 flex items-center justify-center bg-indigo-600 text-white rounded-lg font-bold text-sm shadow-xs">${opt}</span>
                                            <input type="text" id="edit-ai-opt-${opt}" value="${escapeHTML(q.options?.[opt]?.text || '')}" class="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 focus:outline-none transition font-medium" placeholder="Nội dung đáp án ${opt}">
                                        </div>
                                    </div>
                                `).join('')}
                            </div>
                        </div>
                        
                        <!-- Đáp án đúng -->
                        <div>
                            <div class="flex items-center justify-between mb-1.5">
                                <label class="block text-sm font-bold text-gray-800">Đáp án chính xác / Hướng dẫn chấm <span class="text-red-500">*</span></label>
                                <span class="text-xs text-gray-500">4-1: A/B/C/D | TF4: A&C | SQ: Kết quả | TL: Biểu điểm</span>
                            </div>
                            <textarea id="edit-ai-answer" rows="3" class="w-full px-3.5 py-2.5 border border-gray-300 rounded-xl text-sm focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 focus:outline-none transition font-medium" placeholder="4-1: A/B/C/D. TF4: A&C. SQ: Kết quả. TL: Hướng dẫn chấm">${escapeHTML(q.answer)}</textarea>
                            
                            <div class="mt-3 bg-gray-50/70 p-3 rounded-xl border border-dashed border-gray-300">
                                <div class="flex flex-wrap items-center justify-between gap-2">
                                    <label class="block text-xs font-bold text-gray-700">🖼️ Hình ảnh đi kèm đáp án (tùy chọn)</label>
                                    <button type="button" onclick="document.getElementById('edit-ai-answer-image-preview').src=''; document.getElementById('edit-ai-answer-image-preview').classList.add('hidden');" class="px-2.5 py-1 bg-red-50 text-red-600 border border-red-200 rounded-lg text-xs font-semibold hover:bg-red-100 transition">Xóa ảnh</button>
                                </div>
                                <div class="mt-2 flex items-center gap-3">
                                    <input type="file" id="edit-ai-answer-image" accept="image/*" onchange="handleImageUpload(event, 'edit-ai-answer-image-preview')" class="w-full text-xs text-gray-500 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-semibold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100 cursor-pointer">
                                </div>
                                <img id="edit-ai-answer-image-preview" src="${(q.options && q.options.answerImage) ? q.options.answerImage : ''}" class="${(q.options && q.options.answerImage) ? '' : 'hidden'} mt-2 max-h-48 max-w-sm rounded-lg border border-gray-200 shadow-sm object-contain bg-white p-1">
                            </div>
                        </div>
                    </div>

                    <!-- Footer Action Bar -->
                    <div class="flex items-center justify-end gap-3 mt-8 pt-4 border-t border-gray-200 sticky bottom-0 bg-white/95 backdrop-blur-sm -mx-6 md:-mx-8 px-6 md:px-8 py-3 z-10 shadow-xs">
                        <button type="button" onclick="showAIGeneratedPreview(window.tempGeneratedQuestions)" class="px-5 py-2.5 bg-gray-100 text-gray-700 font-semibold rounded-xl hover:bg-gray-200 transition">Quay lại</button>
                        <button type="button" onclick="updateAIGeneratedQuestion(${index})" class="px-6 py-2.5 bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-bold rounded-xl hover:from-indigo-700 hover:to-purple-700 shadow-md transition flex items-center gap-2">
                            <span>💾 Cập nhật câu hỏi</span>
                        </button>
                    </div>
                </div>
            `;
            showModal(modalContent, 'wide');
        };

        window.toggleAIEditOptions = function(type) {
            const container = document.getElementById('ai-edit-options-container');
            if (type === 'SQ' || type === 'TL') {
                container.classList.add('hidden');
            } else {
                container.classList.remove('hidden');
            }
        };

        window.updateAIGeneratedQuestion = function(index) {
            const q = window.tempGeneratedQuestions[index];
            q.content = document.getElementById('edit-ai-content')?.value?.trim() || '';
            q.lesson = document.getElementById('edit-ai-lesson')?.value?.trim().toUpperCase() || '';
            q.level = document.getElementById('edit-ai-level')?.value || '';
            q.type = document.getElementById('edit-ai-type')?.value || '';
            const answerRaw = document.getElementById('edit-ai-answer')?.value?.trim() || '';
            q.answer = q.type === 'TL' ? answerRaw : answerRaw.toUpperCase();

            if (q.type === '4-1' || q.type === 'TF4') {
                ['A', 'B', 'C', 'D'].forEach(opt => {
                    const optText = document.getElementById(`edit-ai-opt-${opt}`).value.trim();
                    if (!q.options[opt]) q.options[opt] = { text: '', image: '' };
                    q.options[opt].text = optText;
                });
            } else {
                // For SQ and TL, handle answer image
                const ansImgPreview = document.getElementById('edit-ai-answer-image-preview');
                if (!q.options) q.options = {};
                if (ansImgPreview && !ansImgPreview.classList.contains('hidden') && ansImgPreview.getAttribute('src')) {
                    q.options.answerImage = ansImgPreview.src;
                } else {
                    delete q.options.answerImage;
                }
            }

            window.tempGeneratedQuestions[index] = sanitizeQuestionFormulas(q);

            showAIGeneratedPreview(window.tempGeneratedQuestions);
            showToast('Đã cập nhật câu hỏi AI tạo!', 'success');
        };

        window.confirmAddAIGeneratedQuestions = function() {
            if (!window.tempGeneratedQuestions || window.tempGeneratedQuestions.length === 0) return;
            
            const sanitizedQuestions = window.tempGeneratedQuestions.map(q => sanitizeQuestionFormulas(q));
            sanitizedQuestions.forEach(q => questions.push(q));
            
            saveQuestionsToDB(sanitizedQuestions);
            updateStats();
            updateQuestionStats();
            updateLessonFilter();
            renderQuestionsList();
            
            if (document.getElementById('exams-panel') && !document.getElementById('exams-panel').classList.contains('hidden')) {
                initExamPanel();
            }

            showToast(`🎉 Đã thêm thành công ${window.tempGeneratedQuestions.length} câu hỏi vào ngân hàng!`, 'success');
            window.tempGeneratedQuestions = [];
            closeModal();
        };

        window.appraiseAIQuestions = async function() {
            if (!navigator.onLine) {
                showToast('Không có kết nối internet, vui lòng kiểm tra lại.', 'error');
                return;
            }

            if (!window.tempGeneratedQuestions || window.tempGeneratedQuestions.length === 0) {
                showToast('Không có câu hỏi nào để thẩm định!', 'warning');
                return;
            }

            const ctx = window.lastAIGeneration;
            if (!ctx || !ctx.apiKey) {
                showToast('Không tìm thấy API Key để thẩm định!', 'error');
                return;
            }

            const module = await loadGoogleAI();
            if (!module) {
                showToast('Không thể tải thư viện AI. Vui lòng kiểm tra kết nối mạng.', 'error');
                return;
            }
            const { GoogleGenAI, Type } = module;

            const btn = document.getElementById('btn-ai-appraise');
            btn.disabled = true;
            btn.innerHTML = `
                <svg class="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24">
                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Đang thẩm định... (tối đa 60s)
            `;
            btn.classList.add('opacity-70', 'cursor-not-allowed');

            try {
                const ai = new GoogleGenAI({ apiKey: ctx.apiKey });
                
                const questionsJson = JSON.stringify(window.tempGeneratedQuestions.map(q => ({
                    type: q.type,
                    level: q.level,
                    content: q.content,
                    answer: q.answer,
                    options: q.options
                })));

                const prompt = (appSettings.aiAppraisePrompt || DEFAULT_AI_APPRAISE_PROMPT)
                    .replace('{topic}', ctx.topic)
                    .replace('{type}', ctx.type === 'MIXED' ? 'Hỗn hợp 4-1, TF4, SQ, TL' : ctx.type)
                    .replace('{level}', ctx.level === 'MIXED' ? 'Hỗn hợp NB, TH, VD' : ctx.level)
                    .replace('{questionsJson}', questionsJson);

                const generatePromise = ai.models.generateContent({
                    model: "gemini-3.8-flash",
                    config: {
                        thinkingConfig: { thinkingLevel: "LOW" },
                        responseMimeType: "application/json",
                        responseSchema: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    score: { type: Type.NUMBER, description: "Điểm thẩm định trên thang 100" },
                                    evaluation: { type: Type.STRING, description: "Nhận xét chi tiết về câu hỏi, đáp án, độ phù hợp" }
                                },
                                required: ["score", "evaluation"]
                            }
                        }
                    },
                    contents: [{ parts: [{ text: prompt }] }]
                });

                const timeoutPromise = new Promise((_, reject) => {
                    setTimeout(() => reject(new Error('Quá thời gian chờ (60 giây). Vui lòng thử lại.')), 60000);
                });

                const response = await Promise.race([generatePromise, timeoutPromise]);
                const appraisals = JSON.parse(response.text);

                if (Array.isArray(appraisals) && appraisals.length === window.tempGeneratedQuestions.length) {
                    appraisals.forEach((appraisal, index) => {
                        const qDiv = document.getElementById(`ai-preview-q-${index}`);
                        if (qDiv) {
                            const oldAppraisal = qDiv.querySelector('.ai-appraisal-result');
                            if (oldAppraisal) oldAppraisal.remove();

                            const scoreColor = appraisal.score >= 80 ? 'text-green-600' : (appraisal.score >= 50 ? 'text-amber-600' : 'text-purple-600');
                            const bgColor = appraisal.score >= 80 ? 'bg-green-50 border-green-200' : (appraisal.score >= 50 ? 'bg-amber-50 border-amber-200' : 'bg-purple-50 border-red-200');

                            const appraisalHtml = `
                                <div class="ai-appraisal-result mt-3 p-3 border rounded-lg ${bgColor}">
                                    <div class="font-bold ${scoreColor} mb-1">Điểm thẩm định: ${appraisal.score}/100</div>
                                    <div class="text-sm text-gray-700 italic">${appraisal.evaluation}</div>
                                </div>
                            `;
                            qDiv.insertAdjacentHTML('beforeend', appraisalHtml);
                        }
                    });
                    showToast('✅ Đã thẩm định xong!', 'success');
                } else {
                    throw new Error('Dữ liệu thẩm định không khớp với số lượng câu hỏi.');
                }

            } catch (error) {
                console.error('AI Appraisal Error:', error);
                let errorMsg = error.message || 'Lỗi không xác định';
                if (errorMsg.includes('QuotaFailure') || errorMsg.includes('429') || errorMsg.includes('rate-limit')) {
                    errorMsg = 'Đã hết lượt sử dụng AI miễn phí (vượt quá giới hạn của Google Gemini). Vui lòng thử lại sau hoặc sử dụng API Key khác.';
                }
                showToast('Lỗi khi thẩm định: ' + errorMsg, 'error');
            } finally {
                btn.disabled = false;
                btn.innerHTML = 'Thẩm định';
                btn.classList.remove('opacity-70', 'cursor-not-allowed');
            }
        };

        window.togglePasswordVisibility = togglePasswordVisibility;
        window.updateAppTitle = updateAppTitle;
        window.saveAIPrompt = saveAIPrompt;
        window.resetAIPrompt = resetAIPrompt;
        window.saveAIAppraisePrompt = saveAIAppraisePrompt;
        window.resetAIAppraisePrompt = resetAIAppraisePrompt;
        window.onNewExamNameInput = function(val) {
            const selectEl = document.getElementById('exam-config-name');
            if (selectEl && selectEl.value !== '') {
                // Đang có cấu hình cũ được load, khi nhập tên mới thì đưa về mặc định
                resetExamPanelToDefault();
                const newExamInput = document.getElementById('new-exam-name');
                if (newExamInput) newExamInput.value = val;
            }
            examConfig.name = val;
            if (window.updateCurrentExamInfo) window.updateCurrentExamInfo();
        };

        window.onExamNameChange = onExamNameChange;
        window.handleImageUpload = handleImageUpload;
        window.deletePendingQuestion = deletePendingQuestion;
        window.editPendingQuestion = editPendingQuestion;
        window.finalizeImport = finalizeImport;
        window.toggleAllLessons = toggleAllLessons;
        window.updateSelectedLessons = updateSelectedLessons;
        window.updatePointsPreview = updatePointsPreview;
        window.toggleExamMode = toggleExamMode;
        window.updateRankingSelection = updateRankingSelection;
        window.toggleAllRankingCheckboxes = toggleAllRankingCheckboxes;
        window.exportRanking = exportRanking;
        window.showAccountModal = showAccountModal;
        window.saveAccount = saveAccount;
        window.closeAccountModal = closeAccountModal;
        window.userRegister = userRegister;
        window.setQuestionTypeFilter = setQuestionTypeFilter;
        window.deleteSelectedRankingResults = deleteSelectedRankingResults;
        window.deleteSingleRankingResult = deleteSingleRankingResult;
        window.clearAllResults = clearAllResults;
        window.clearAllRankingSelection = clearAllRankingSelection;
        window.selectAllFilteredRankingResults = selectAllFilteredRankingResults;
        window.rankingSortColumn = 'rank';
        window.rankingSortDirection = 'asc';

        window.sortRankingBy = function sortRankingBy(columnKey) {
            if (!columnKey) return;
            if (window.rankingSortColumn === columnKey) {
                window.rankingSortDirection = window.rankingSortDirection === 'asc' ? 'desc' : 'asc';
            } else {
                window.rankingSortColumn = columnKey;
                if (columnKey === 'score' || columnKey === 'correctCount' || columnKey === 'timestamp') {
                    window.rankingSortDirection = 'desc';
                } else {
                    window.rankingSortDirection = 'asc';
                }
            }
            const selectEl = document.getElementById('ranking-sort-select');
            if (selectEl && selectEl.value !== columnKey) {
                selectEl.value = columnKey;
            }
            updateRankingHeaderSortIcons();
            renderRanking();
        };

        window.toggleRankingSortDirection = function toggleRankingSortDirection() {
            window.rankingSortDirection = window.rankingSortDirection === 'asc' ? 'desc' : 'asc';
            updateRankingHeaderSortIcons();
            renderRanking();
        };

        window.updateRankingHeaderSortIcons = function updateRankingHeaderSortIcons() {
            const columns = ['rank', 'loaiThiSinh', 'studentName', 'lop', 'donvi', 'score', 'correctCount', 'timeTaken', 'aiGrading', 'examName'];
            const activeCol = window.rankingSortColumn || 'rank';
            const activeDir = window.rankingSortDirection || 'asc';

            columns.forEach(col => {
                const iconEl = document.getElementById(`sort-icon-${col}`);
                if (iconEl) {
                    if (activeCol === col) {
                        iconEl.textContent = activeDir === 'asc' ? ' 🔼' : ' 🔽';
                        iconEl.className = 'text-xs font-bold text-amber-300 drop-shadow-xs opacity-100';
                    } else {
                        iconEl.textContent = ' ↕️';
                        iconEl.className = 'text-xs opacity-60 hover:opacity-100 transition-opacity';
                    }
                }
            });

            const btnIconEl = document.getElementById('sort-direction-btn-icon');
            if (btnIconEl) {
                btnIconEl.textContent = activeDir === 'asc' ? '🔼 Tăng dần' : '🔽 Giảm dần';
            }
        };

        window.renderRanking = renderRanking;
        window.showExamDetail = showExamDetail;
        window.deleteSingleRankingResult = deleteSingleRankingResult;
        window.populateRankingExamFilter = populateRankingExamFilter;

        // ==================== REPORT FUNCTION (BÁO CÁO ĐỐI CHIẾU TIẾN ĐỘ) ====================
        window.openExamReportModal = async function openExamReportModal() {
            const outsideSelectedExamName = document.getElementById('ranking-exam-filter')?.value || '';
            if (!outsideSelectedExamName) {
                showToast('⚠️ Vui lòng chọn một đề thi cụ thể ở mục "Quản lý kết quả" trước khi xem báo cáo đối chiếu!', 'warning');
                return;
            }

            const token = localStorage.getItem('auth_token') || localStorage.getItem('token') || (window.currentUser && window.currentUser.token) || '';

            try {
                // Fetch the latest data to make report 100% accurate
                const [resUsers, resResults, resExams] = await Promise.all([
                    fetch('/api/users?limit=all', { headers: { 'Authorization': 'Bearer ' + token } }).then(r => r.json()).catch(() => null),
                    fetch('/api/results?limit=5000', { headers: { 'Authorization': 'Bearer ' + token } }).then(r => r.json()).catch(() => null),
                    fetch('/api/exams?forRanking=true', { headers: { 'Authorization': 'Bearer ' + token } }).then(r => r.json()).catch(() => null)
                ]);

                let localUsers = [];
                if (resUsers && Array.isArray(resUsers.data)) {
                    localUsers = resUsers.data;
                } else if (window.usersList && window.usersList.length > 0) {
                    localUsers = window.usersList;
                } else if (typeof usersList !== 'undefined' && Array.isArray(usersList) && usersList.length > 0) {
                    localUsers = usersList;
                } else if (typeof accounts !== 'undefined' && Array.isArray(accounts) && accounts.length > 0) {
                    localUsers = accounts;
                }

                let localResults = [];
                if (resResults && Array.isArray(resResults.data)) {
                    localResults = resResults.data;
                } else if (typeof results !== 'undefined' && Array.isArray(results) && results.length > 0) {
                    localResults = results;
                }

                let localExams = [];
                if (resExams && Array.isArray(resExams.data)) {
                    localExams = resExams.data;
                    window.allExamConfigsList = localExams;
                } else if (typeof examConfigs !== 'undefined' && Array.isArray(examConfigs) && examConfigs.length > 0) {
                    localExams = examConfigs;
                }

                // Filter localUsers to get only 'Học sinh' / student accounts
                const studentUsers = localUsers.filter(u => {
                    if (!u) return false;
                    const aud = String(u.target_audience || u.targetAudience || '').toLowerCase().trim();
                    const role = String(u.role || '').toLowerCase().trim();
                    if (role === 'admin' || role === 'teacher' || aud === 'admin' || aud === 'teacher' || aud === 'giáo viên') {
                        return false;
                    }
                    if (aud === 'học sinh' || aud === 'student' || aud === 'hoc sinh' || aud.includes('học sinh') || aud.includes('thí sinh')) {
                        return true;
                    }
                    if (role === 'học sinh' || role === 'hocsinh' || role === 'student' || role === 'user') {
                        return true;
                    }
                    return (!aud || aud === 'học sinh');
                });

                if (studentUsers.length === 0 && localUsers.length > 0) {
                    studentUsers.push(...localUsers.filter(u => {
                        const r = String(u.role || '').toLowerCase();
                        const aud = String(u.target_audience || '').toLowerCase();
                        return r !== 'admin' && r !== 'teacher' && aud !== 'admin' && aud !== 'teacher';
                    }));
                }

                // Apply strict teacher / admin locking
                let filteredStudentUsers = [...studentUsers];
                if (isTeacherLoggedIn && currentUser && currentUser.donvi) {
                    const teacherDonvi = String(currentUser.donvi).trim().toLowerCase();
                    filteredStudentUsers = studentUsers.filter(u => 
                        String(u.donvi || u.address || '').trim().toLowerCase() === teacherDonvi
                    );
                }

                const allExamsList = [
                    ...(Array.isArray(localExams) ? localExams : []),
                    ...(Array.isArray(window.allExamConfigsList) ? window.allExamConfigsList : []),
                    ...(typeof examConfigs !== 'undefined' && Array.isArray(examConfigs) ? examConfigs : [])
                ];

                // Gather list of exams (ensure we map using 'name' column)
                const examsList = [];
                const seenExamNames = new Set();
                allExamsList.forEach(e => {
                    if (!e) return;
                    const name = e.name || e.title || e.examName;
                    if (name && !seenExamNames.has(String(name).toLowerCase().trim())) {
                        seenExamNames.add(String(name).toLowerCase().trim());
                        examsList.push({ id: e.id || name, name });
                    }
                });

                if (examsList.length === 0) {
                    const uniqueExamNames = [...new Set(localResults.map(r => r.examName || r.exam_name).filter(Boolean))];
                    uniqueExamNames.forEach(name => examsList.push({ id: name, name }));
                }

                const modalHtml = `
                    <div class="p-2 sm:p-4 md:p-6 w-full max-w-5xl mx-auto flex flex-col max-h-[90vh]">
                        <!-- Header -->
                        <div class="flex items-center justify-between border-b pb-2 mb-2">
                            <div class="flex items-center gap-2 sm:gap-3">
                                <span class="text-2xl sm:text-3xl">📊</span>
                                <div>
                                    <h3 class="text-base sm:text-xl font-bold text-gray-800">Báo cáo đối chiếu & Tiến độ làm bài</h3>
                                    <p class="text-[10px] sm:text-xs text-gray-500">Đối chiếu danh sách Người dùng để tìm học sinh chưa tham gia thi</p>
                                </div>
                            </div>
                        </div>

                        <!-- Filters Grid -->
                        <div class="grid grid-cols-1 md:grid-cols-3 gap-1.5 md:gap-3 mb-2 bg-slate-50 p-2 md:p-3 rounded-xl border border-slate-100">
                            <div>
                                <label class="block text-[10px] md:text-xs font-bold text-gray-600 mb-0.5">1. Chọn đề thi (*)</label>
                                <select id="report-exam-select" class="w-full px-2 py-1 md:py-2 border border-slate-200 bg-slate-100 cursor-not-allowed rounded-lg text-xs md:text-sm focus:outline-none" disabled>
                                    ${examsList.map(e => {
                                        const isSelected = String(e.name).toLowerCase().trim() === String(outsideSelectedExamName).toLowerCase().trim() ? 'selected' : '';
                                        return `<option value="${e.id}" ${isSelected}>${e.name}</option>`;
                                    }).join('')}
                                </select>
                            </div>
                            <div>
                                <label class="block text-[10px] md:text-xs font-bold text-gray-600 mb-0.5">2. Lọc theo đơn vị / Trường</label>
                                <select id="report-unit-select" class="w-full px-2 py-1 md:py-2 border border-slate-200 rounded-lg text-xs md:text-sm focus:border-indigo-500 focus:outline-none bg-white" ${isTeacherLoggedIn ? 'disabled' : ''}>
                                    ${isTeacherLoggedIn ? '' : '<option value="">-- Tất cả đơn vị --</option>'}
                                </select>
                            </div>
                            <div>
                                <label class="block text-[10px] md:text-xs font-bold text-gray-600 mb-0.5">3. Lọc theo lớp học</label>
                                <select id="report-class-select" class="w-full px-2 py-1 md:py-2 border border-slate-200 rounded-lg text-xs md:text-sm focus:border-indigo-500 focus:outline-none bg-white">
                                    <option value="">-- Tất cả lớp --</option>
                                </select>
                            </div>
                        </div>

                        <!-- Statistics Counter (Compact Single Line) -->
                        <div class="grid grid-cols-2 sm:flex sm:flex-wrap items-center justify-between gap-1 px-2 py-1 bg-slate-50 border border-slate-200/60 rounded-xl mb-2 text-[10px] sm:text-xs font-semibold text-slate-700">
                            <div class="flex items-center justify-center sm:justify-start gap-1 px-2 py-0.5 bg-blue-50 text-blue-800 rounded-lg border border-blue-100">
                                <span>👥 Tổng:</span>
                                <span id="report-stat-total" class="font-bold text-xs sm:text-sm text-blue-900">0</span>
                            </div>
                            <div class="flex items-center justify-center sm:justify-start gap-1 px-2 py-0.5 bg-green-50 text-green-800 rounded-lg border border-green-100">
                                <span>✅ Đã làm:</span>
                                <span id="report-stat-done" class="font-bold text-xs sm:text-sm text-green-900">0</span>
                            </div>
                            <div class="flex items-center justify-center sm:justify-start gap-1 px-2 py-0.5 bg-rose-50 text-rose-800 rounded-lg border border-rose-100">
                                <span>❌ Chưa làm:</span>
                                <span id="report-stat-undone" class="font-bold text-xs sm:text-sm text-rose-900">0</span>
                            </div>
                            <div class="flex items-center justify-center sm:justify-start gap-1 px-2 py-0.5 bg-indigo-50 text-indigo-800 rounded-lg border border-indigo-100">
                                <span>📈 Tỉ lệ:</span>
                                <span id="report-stat-percent" class="font-bold text-xs sm:text-sm text-indigo-900">0%</span>
                            </div>
                        </div>

                        <!-- Controls -->
                        <div class="flex items-center gap-1.5 mb-2">
                            <input type="text" id="report-search" placeholder="🔍 Tìm nhanh theo tên..." class="flex-1 min-w-0 px-2.5 py-1 md:py-1.5 border border-slate-200 rounded-lg text-xs md:text-sm focus:border-indigo-500 focus:outline-none">
                            <button id="btn-export-report-excel" class="px-2.5 py-1 md:py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-lg text-xs md:text-sm transition flex items-center gap-1 shadow-sm cursor-pointer shrink-0">
                                📊 <span class="hidden sm:inline">Xuất Excel</span><span class="sm:hidden">Excel</span>
                            </button>
                        </div>

                        <!-- Report Table -->
                        <div class="flex-1 overflow-y-auto border border-slate-200 rounded-xl">
                            <table class="w-full text-sm text-left border-collapse">
                                <thead class="bg-slate-100 text-slate-700 font-bold sticky top-0 z-10 text-xs md:text-sm select-none">
                                    <tr>
                                        <th class="px-2 py-1.5 text-center w-10 border-b border-slate-200 hidden sm:table-cell">STT</th>
                                        <th onclick="toggleReportSort('name')" class="px-2.5 py-1.5 border-b border-slate-200 text-left cursor-pointer hover:bg-slate-200 transition-colors">
                                            Học viên / Học sinh <span id="sort-icon-name" class="text-slate-300 font-bold">↕</span>
                                        </th>
                                        <th onclick="toggleReportSort('class')" class="px-2 py-1.5 text-center w-16 border-b border-slate-200 hidden sm:table-cell cursor-pointer hover:bg-slate-200 transition-colors">
                                            Lớp <span id="sort-icon-class" class="text-slate-300 font-bold">↕</span>
                                        </th>
                                        <th onclick="toggleReportSort('unit')" class="px-2 py-1.5 text-left w-32 border-b border-slate-200 hidden md:table-cell cursor-pointer hover:bg-slate-200 transition-colors">
                                            Đơn vị <span id="sort-icon-unit" class="text-slate-300 font-bold">↕</span>
                                        </th>
                                        <th onclick="toggleReportSort('status')" class="px-2 py-1.5 text-center w-20 border-b border-slate-200 cursor-pointer hover:bg-slate-200 transition-colors">
                                            Trạng thái <span id="sort-icon-status" class="text-slate-300 font-bold">↕</span>
                                        </th>
                                        <th onclick="toggleReportSort('attempts')" class="px-2 py-1.5 text-center w-16 border-b border-slate-200 cursor-pointer hover:bg-slate-200 transition-colors">
                                            Lần làm <span id="sort-icon-attempts" class="text-slate-300 font-bold">↕</span>
                                        </th>
                                        <th onclick="toggleReportSort('score')" class="px-2 py-1.5 text-center w-16 border-b border-slate-200 cursor-pointer hover:bg-slate-200 transition-colors">
                                            Điểm cao <span id="sort-icon-score" class="text-slate-300 font-bold">↕</span>
                                        </th>
                                        <th onclick="toggleReportSort('duration')" class="px-2 py-1.5 text-center w-20 border-b border-slate-200 hidden sm:table-cell cursor-pointer hover:bg-slate-200 transition-colors">
                                            Thời gian <span id="sort-icon-duration" class="text-slate-300 font-bold">↕</span>
                                        </th>
                                        <th onclick="toggleReportSort('time')" class="px-2 py-1.5 text-center w-28 border-b border-slate-200 hidden md:table-cell cursor-pointer hover:bg-slate-200 transition-colors">
                                            Làm vào lúc <span id="sort-icon-time" class="text-slate-300 font-bold">↕</span>
                                        </th>
                                        <th class="px-2 py-1.5 text-center w-20 border-b border-slate-200">Thao tác</th>
                                    </tr>
                                </thead>
                                <tbody id="report-table-body" class="divide-y divide-slate-100 text-slate-700 bg-white">
                                    <!-- Dynamic rows -->
                                </tbody>
                            </table>
                        </div>
                    </div>
                `;

                showModal(modalHtml, true);
                const modalEl = document.getElementById('modal-content');
                if (modalEl) {
                    modalEl.style.width = '1000px';
                    modalEl.style.maxWidth = '98vw';
                }

                let currentSortCol = 'name';
                let currentSortDir = 'asc';

                window.toggleReportSort = (col) => {
                    if (currentSortCol === col) {
                        currentSortDir = currentSortDir === 'asc' ? 'desc' : 'asc';
                    } else {
                        currentSortCol = col;
                        currentSortDir = 'asc';
                    }
                    renderReportRows(false);
                };

                const updateUnitFilterOptions = () => {
                    const examSelect = document.getElementById('report-exam-select');
                    const unitSelect = document.getElementById('report-unit-select');
                    if (!unitSelect) return;

                    const previousSelectedUnit = unitSelect.value || '';
                    const examIdOrName = examSelect?.value || outsideSelectedExamName || '';

                    const targetExam = allExamsList.find(e => {
                        if (!e) return false;
                        const eId = String(e.id || '').trim();
                        const eName = String(e.name || e.title || e.examName || '').trim().toLowerCase();
                        const targetQuery = String(examIdOrName || '').trim().toLowerCase();
                        const outsideQuery = String(outsideSelectedExamName || '').trim().toLowerCase();

                        return (
                            (eId && (eId === targetQuery || eId === outsideQuery)) ||
                            (eName && (eName === targetQuery || eName === outsideQuery)) ||
                            (window.examNameToIdMap && eId && String(window.examNameToIdMap[outsideSelectedExamName]) === eId)
                        );
                    });

                    const unitsSet = new Set();
                    const targetDonviRaw = String(targetExam?.target_donvi || targetExam?.targetDonVi || targetExam?.donvi || targetExam?.donVi || '').trim();

                    if (targetDonviRaw) {
                        // Đề thi có cấu hình đơn vị cụ thể: CHỈ hiển thị đúng các đơn vị được chỉ định của đề thi đó
                        targetDonviRaw.split(/[,;\n]+/).forEach(u => {
                            const trimmed = u.trim();
                            if (trimmed) unitsSet.add(trimmed);
                        });
                    } else {
                        // Đề thi công khai (không có target_donvi): Lấy từ kết quả thi và danh sách học sinh
                        const targetExamName = String(targetExam?.name || targetExam?.title || targetExam?.examName || outsideSelectedExamName || '').trim().toLowerCase();
                        const targetExamId = String(targetExam?.id || '').trim();

                        (localResults || []).forEach(r => {
                            const rName = String(r.examName || r.exam_name || '').trim().toLowerCase();
                            const rId = String(r.examId || r.exam_id || '').trim();
                            if ((targetExamName && rName === targetExamName) || (targetExamId && rId === targetExamId)) {
                                const rUnit = String(r.don_vi || r.donvi || r.studentClass || '').trim();
                                if (rUnit) unitsSet.add(rUnit);
                            }
                        });

                        filteredStudentUsers.forEach(u => {
                            const unitName = String(u.donvi || u.address || '').trim();
                            if (unitName) unitsSet.add(unitName);
                        });
                    }

                    const sortedUnits = Array.from(unitsSet).sort(window.naturalSort);

                    let unitOptionsHtml = isTeacherLoggedIn ? '' : '<option value="">-- Tất cả đơn vị --</option>';
                    sortedUnits.forEach(u => {
                        let isSelected = false;
                        if (previousSelectedUnit && previousSelectedUnit.toLowerCase() === u.toLowerCase()) {
                            isSelected = true;
                        } else if (!previousSelectedUnit && targetDonviRaw && sortedUnits.length === 1) {
                            isSelected = true;
                        }
                        unitOptionsHtml += `<option value="${u}" ${isSelected ? 'selected' : ''}>${u}</option>`;
                    });

                    unitSelect.innerHTML = unitOptionsHtml;
                };

                const updateClassFilterOptions = () => {
                    const unitSelect = document.getElementById('report-unit-select');
                    const classSelect = document.getElementById('report-class-select');
                    const examSelect = document.getElementById('report-exam-select');
                    if (!classSelect) return;

                    const unitValue = unitSelect ? (unitSelect.value || '').trim().toLowerCase() : '';
                    const previousSelectedClass = classSelect.value;
                    const examIdOrName = examSelect?.value || outsideSelectedExamName || '';

                    const targetExam = allExamsList.find(e => {
                        if (!e) return false;
                        const eId = String(e.id || '').trim();
                        const eName = String(e.name || e.title || e.examName || '').trim().toLowerCase();
                        const targetQuery = String(examIdOrName || '').trim().toLowerCase();
                        const outsideQuery = String(outsideSelectedExamName || '').trim().toLowerCase();

                        return (
                            (eId && (eId === targetQuery || eId === outsideQuery)) ||
                            (eName && (eName === targetQuery || eName === outsideQuery)) ||
                            (window.examNameToIdMap && eId && String(window.examNameToIdMap[outsideSelectedExamName]) === eId)
                        );
                    });

                    const teacherClassSet = new Set();
                    if (isTeacherLoggedIn) {
                        if (currentUser && Array.isArray(currentUser.assigned_classes)) {
                            currentUser.assigned_classes.forEach(ac => {
                                const clsName = String(ac.class_name || ac.lop || ac || '').trim();
                                if (clsName) teacherClassSet.add(clsName);
                            });
                        }
                        if (teacherClassSet.size === 0 && window.usersList && Array.isArray(window.usersList) && currentUser) {
                            const teacherId = currentUser.user_id || currentUser.id;
                            const foundMe = window.usersList.find(u => u.id === teacherId || u.user_id === teacherId || u.username === currentUser.username);
                            if (foundMe && Array.isArray(foundMe.assigned_classes)) {
                                foundMe.assigned_classes.forEach(ac => {
                                    const clsName = String(ac.class_name || ac.lop || ac || '').trim();
                                    if (clsName) teacherClassSet.add(clsName);
                                });
                            }
                        }
                    }

                    const teacherClassSetLower = new Set(Array.from(teacherClassSet).map(s => String(s).trim().toLowerCase()));

                    const targetLopRaw = String(targetExam?.target_lop || targetExam?.targetLop || targetExam?.lop || '').trim();
                    const examConfiguredClasses = targetLopRaw
                        ? targetLopRaw.split(/[,;\n]+/).map(s => s.trim()).filter(Boolean)
                        : [];

                    const finalClassesSet = new Set();

                    if (examConfiguredClasses.length > 0) {
                        examConfiguredClasses.forEach(c => {
                            if (!isTeacherLoggedIn || teacherClassSet.size === 0 || teacherClassSetLower.has(c.toLowerCase())) {
                                finalClassesSet.add(c);
                            }
                        });
                    } else {
                        filteredStudentUsers.forEach(u => {
                            const studentUnit = String(u.donvi || u.address || '').trim().toLowerCase();
                            const studentLop = String(u.lop || '').trim();
                            if (studentLop) {
                                if (!unitValue || studentUnit === unitValue || studentUnit.includes(unitValue) || unitValue.includes(studentUnit)) {
                                    if (!isTeacherLoggedIn || teacherClassSet.size === 0 || teacherClassSetLower.has(studentLop.toLowerCase())) {
                                        finalClassesSet.add(studentLop);
                                    }
                                }
                            }
                        });

                        const targetExamName = String(targetExam?.name || targetExam?.title || targetExam?.examName || outsideSelectedExamName || '').trim().toLowerCase();
                        const targetExamId = String(targetExam?.id || '').trim();

                        (localResults || []).forEach(r => {
                            const rName = String(r.examName || r.exam_name || '').trim().toLowerCase();
                            const rId = String(r.examId || r.exam_id || '').trim();
                            if ((targetExamName && rName === targetExamName) || (targetExamId && rId === targetExamId)) {
                                const c = (r.lop || '').trim();
                                const u = (r.don_vi || r.donvi || r.studentClass || '').trim().toLowerCase();
                                if (c) {
                                    if (!unitValue || u === unitValue || u.includes(unitValue) || unitValue.includes(u)) {
                                        if (!isTeacherLoggedIn || teacherClassSet.size === 0 || teacherClassSetLower.has(c.toLowerCase())) {
                                            finalClassesSet.add(c);
                                        }
                                    }
                                }
                            }
                        });
                    }

                    const sortedClasses = Array.from(finalClassesSet).sort(window.naturalSort);

                    let classOptionsHtml = '<option value="">-- Tất cả lớp --</option>';
                    sortedClasses.forEach(c => {
                        const isSelected = c === previousSelectedClass ? 'selected' : '';
                        classOptionsHtml += `<option value="${c}" ${isSelected}>${c}</option>`;
                    });
                    classSelect.innerHTML = classOptionsHtml;
                };

                const renderReportRows = async (forceFetch = false) => {
                    const examIdOrName = document.getElementById('report-exam-select')?.value || outsideSelectedExamName || '';
                    const unitValue = document.getElementById('report-unit-select')?.value || '';
                    const classValue = document.getElementById('report-class-select')?.value || '';
                    const query = (document.getElementById('report-search')?.value || '').toLowerCase().trim();

                    if (forceFetch) {
                        const statPercentEl = document.getElementById('report-stat-percent');
                        if (statPercentEl) {
                            statPercentEl.innerHTML = `
                                <svg class="animate-spin h-3.5 w-3.5 text-indigo-600 inline-block mr-1" fill="none" viewBox="0 0 24 24">
                                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                </svg>
                                <span>Đang nạp...</span>
                            `;
                        }

                        try {
                            const [resUsers, resResults] = await Promise.all([
                                fetch('/api/users?limit=all', { headers: { 'Authorization': 'Bearer ' + token } }).then(r => r.json()).catch(() => null),
                                fetch('/api/results?limit=5000', { headers: { 'Authorization': 'Bearer ' + token } }).then(r => r.json()).catch(() => null)
                            ]);

                            if (resUsers && Array.isArray(resUsers.data)) {
                                localUsers = resUsers.data;
                                const newStudentUsers = localUsers.filter(u => {
                                    if (!u) return false;
                                    const aud = String(u.target_audience || u.targetAudience || '').toLowerCase().trim();
                                    const role = String(u.role || '').toLowerCase().trim();
                                    if (role === 'admin' || role === 'teacher' || aud === 'admin' || aud === 'teacher' || aud === 'giáo viên') {
                                        return false;
                                    }
                                    if (aud === 'học sinh' || aud === 'student' || aud === 'hoc sinh' || aud.includes('học sinh') || aud.includes('thí sinh')) {
                                        return true;
                                    }
                                    if (role === 'học sinh' || role === 'hocsinh' || role === 'student' || role === 'user') {
                                        return true;
                                    }
                                    return (!aud || aud === 'học sinh');
                                });
                                if (newStudentUsers.length === 0 && localUsers.length > 0) {
                                    newStudentUsers.push(...localUsers.filter(u => {
                                        const r = String(u.role || '').toLowerCase();
                                        const aud = String(u.target_audience || '').toLowerCase();
                                        return r !== 'admin' && r !== 'teacher' && aud !== 'admin' && aud !== 'teacher';
                                    }));
                                }
                                studentUsers.length = 0;
                                studentUsers.push(...newStudentUsers);

                                let newFilteredStudentUsers = [...newStudentUsers];
                                if (isTeacherLoggedIn && currentUser && currentUser.donvi) {
                                    const teacherDonvi = String(currentUser.donvi).trim().toLowerCase();
                                    newFilteredStudentUsers = newStudentUsers.filter(u => 
                                        String(u.donvi || u.address || '').trim().toLowerCase() === teacherDonvi
                                    );
                                }
                                filteredStudentUsers.length = 0;
                                filteredStudentUsers.push(...newFilteredStudentUsers);
                            }

                            if (resResults && Array.isArray(resResults.data)) {
                                localResults = resResults.data;
                            }
                        } catch (e) {
                            console.error('Lỗi tải dữ liệu đối chiếu ngầm:', e);
                        }
                    }

                    const selectedExam = allExamsList.find(e => {
                        if (!e) return false;
                        const eId = String(e.id || '').trim();
                        const eName = String(e.name || e.title || e.examName || '').trim().toLowerCase();
                        const targetQuery = String(examIdOrName || '').trim().toLowerCase();
                        const outsideQuery = String(outsideSelectedExamName || '').trim().toLowerCase();

                        return (
                            (eId && (eId === targetQuery || eId === outsideQuery)) ||
                            (eName && (eName === targetQuery || eName === outsideQuery)) ||
                            (window.examNameToIdMap && eId && String(window.examNameToIdMap[outsideSelectedExamName]) === eId)
                        );
                    });

                    const selectedExamTitle = (selectedExam ? (selectedExam.name || selectedExam.title || selectedExam.examName || selectedExam.id) : (examIdOrName || outsideSelectedExamName || 'De_Thi')) || 'De_Thi';

                    const targetDonviRaw = String(selectedExam?.target_donvi || selectedExam?.targetDonVi || selectedExam?.donvi || selectedExam?.donVi || '').trim();
                    const examConfiguredUnits = targetDonviRaw
                        ? targetDonviRaw.split(/[,;\n]+/).map(s => s.trim().toLowerCase()).filter(Boolean)
                        : [];

                    const targetLopRaw = String(selectedExam?.target_lop || selectedExam?.targetLop || selectedExam?.lop || '').trim();
                    const examConfiguredClasses = targetLopRaw
                        ? targetLopRaw.split(/[,;\n]+/).map(s => s.trim().toLowerCase()).filter(Boolean)
                        : [];

                    const teacherClassSet = new Set();
                    if (isTeacherLoggedIn && currentUser) {
                        if (Array.isArray(currentUser.assigned_classes)) {
                            currentUser.assigned_classes.forEach(ac => {
                                const clsName = String(ac.class_name || ac.lop || ac || '').trim().toLowerCase();
                                if (clsName) teacherClassSet.add(clsName);
                            });
                        }
                        if (teacherClassSet.size === 0 && window.usersList) {
                            const teacherId = currentUser.user_id || currentUser.id;
                            const foundMe = window.usersList.find(u => u.id === teacherId || u.user_id === teacherId || u.username === currentUser.username);
                            if (foundMe && Array.isArray(foundMe.assigned_classes)) {
                                foundMe.assigned_classes.forEach(ac => {
                                    const clsName = String(ac.class_name || ac.lop || ac || '').trim().toLowerCase();
                                    if (clsName) teacherClassSet.add(clsName);
                                });
                            }
                        }
                    }

                    let filteredStudents = filteredStudentUsers.filter(u => {
                        const studentLop = String(u.lop || '').trim().toLowerCase();
                        const studentUnit = String(u.donvi || u.address || '').trim().toLowerCase();

                        if (unitValue) {
                            const uValLower = unitValue.toLowerCase().trim();
                            const matchUnit = studentUnit === uValLower || studentUnit.includes(uValLower) || uValLower.includes(studentUnit);
                            if (!matchUnit) return false;
                        } else if (examConfiguredUnits.length > 0) {
                            const matchAnyTargetUnit = examConfiguredUnits.some(cu => 
                                studentUnit === cu || studentUnit.includes(cu) || cu.includes(studentUnit)
                            );
                            if (!matchAnyTargetUnit) return false;
                        }

                        if (classValue) {
                            if (studentLop !== classValue.toLowerCase().trim()) return false;
                        } else {
                            if (examConfiguredClasses.length > 0) {
                                if (!examConfiguredClasses.includes(studentLop)) return false;
                            }
                            if (isTeacherLoggedIn && teacherClassSet.size > 0) {
                                if (!teacherClassSet.has(studentLop)) return false;
                            }
                        }

                        if (query) {
                            const sName = (u.full_name || '').toLowerCase();
                            const sUsername = (u.username || '').toLowerCase();
                            if (!sName.includes(query) && !sUsername.includes(query)) return false;
                        }

                        return true;
                    });

                    const examResults = localResults.filter(r => {
                        if (!r) return false;
                        const rExamId = String(r.examId || r.exam_id || '').trim();
                        const rExamName = String(r.examName || r.exam_name || '').trim().toLowerCase();
                        const targetId = String(selectedExam?.id || examIdOrName || '').trim();
                        const targetName = String(selectedExamTitle || outsideSelectedExamName || '').trim().toLowerCase();
                        return (targetId && rExamId === targetId) || (targetName && rExamName === targetName);
                    });

                    const formatReportTime = (seconds) => {
                        if (seconds === undefined || seconds === null) return '-';
                        const s = Number(seconds) || 0;
                        const mins = Math.floor(s / 60);
                        const secs = s % 60;
                        return `${mins}p ${secs}s`;
                    };

                    const studentDataList = filteredStudents.map(student => {
                        const studentUid = student.id || student.user_id;
                        const studentUsername = String(student.username || '').toLowerCase().trim();
                        const studentName = String(student.full_name || '').toLowerCase().replace(/\s+/g, ' ').trim();

                        const matchedResults = examResults.filter(r => {
                            if (studentUid && r.userId && String(r.userId) === String(studentUid)) return true;
                            if (studentUid && r.user_id && String(r.user_id) === String(studentUid)) return true;
                            if (studentUsername && r.username && String(r.username).toLowerCase().trim() === studentUsername) return true;
                            const rName = String(r.studentName || r.student_name || r.full_name || '').toLowerCase().replace(/\s+/g, ' ').trim();
                            return rName && rName === studentName;
                        });

                        const attemptsCount = matchedResults.length;
                        const isDone = attemptsCount > 0;
                        
                        let bestAttempt = null;
                        if (isDone) {
                            bestAttempt = matchedResults.reduce((max, attempt) => 
                                (Number(attempt.score) || 0) > (Number(max.score) || 0) ? attempt : max
                            , matchedResults[0]);
                        }

                        const maxScore = isDone && bestAttempt ? (Number(bestAttempt.score) || 0) : 0;
                        const timeTaken = isDone && bestAttempt ? (Number(bestAttempt.time_taken || bestAttempt.timeTaken) || 0) : 0;
                        const doneAt = isDone && bestAttempt ? (bestAttempt.created_at || bestAttempt.createdAt || bestAttempt.timestamp) : null;
                        
                        return {
                            student,
                            attemptsCount,
                            isDone,
                            maxScore,
                            timeTaken,
                            doneAt,
                            matchedResultIds: matchedResults.map(r => r.id || r._id).filter(Boolean)
                        };
                    });

                    const getVietnameseLastName = (fullName) => {
                        const parts = String(fullName || '').trim().split(/\s+/);
                        return parts.length > 0 ? parts[parts.length - 1] : '';
                    };

                    studentDataList.sort((a, b) => {
                        let comparison = 0;
                        if (currentSortCol === 'name') {
                            const nameA = getVietnameseLastName(a.student.full_name);
                            const nameB = getVietnameseLastName(b.student.full_name);
                            comparison = nameA.localeCompare(nameB, 'vi');
                            if (comparison === 0) {
                                comparison = (a.student.full_name || '').localeCompare(b.student.full_name || '', 'vi');
                            }
                        } else if (currentSortCol === 'class') {
                            comparison = window.naturalSort(a.student.lop, b.student.lop);
                        } else if (currentSortCol === 'unit') {
                            comparison = window.naturalSort(a.student.donvi, b.student.donvi);
                        } else if (currentSortCol === 'status') {
                            comparison = (a.isDone === b.isDone) ? 0 : (a.isDone ? 1 : -1);
                        } else if (currentSortCol === 'attempts') {
                            comparison = a.attemptsCount - b.attemptsCount;
                        } else if (currentSortCol === 'score') {
                            comparison = a.maxScore - b.maxScore;
                        } else if (currentSortCol === 'duration') {
                            comparison = a.timeTaken - b.timeTaken;
                        } else if (currentSortCol === 'time') {
                            const timeA = a.doneAt ? new Date(a.doneAt).getTime() : 0;
                            const timeB = b.doneAt ? new Date(b.doneAt).getTime() : 0;
                            comparison = timeA - timeB;
                        }

                        return currentSortDir === 'asc' ? comparison : -comparison;
                    });

                    let doneCount = 0;
                    let undoneCount = 0;

                    const tbody = document.getElementById('report-table-body');
                    if (!tbody) return;
                    tbody.innerHTML = '';

                    if (studentDataList.length === 0) {
                        tbody.innerHTML = `<tr><td colspan="9" class="text-center py-8 text-slate-400 italic">Không có học sinh nào phù hợp bộ lọc.</td></tr>`;
                        document.getElementById('report-stat-total').textContent = '0';
                        document.getElementById('report-stat-done').textContent = '0';
                        document.getElementById('report-stat-undone').textContent = '0';
                        document.getElementById('report-stat-percent').textContent = '0%';
                        return;
                    }

                    studentDataList.forEach((dataItem, index) => {
                        const { student, attemptsCount, isDone, maxScore, timeTaken, doneAt } = dataItem;
                        const formattedDoneAt = doneAt ? window.formatVNTime(doneAt) : '-';

                        if (isDone) doneCount++;
                        else undoneCount++;

                        const tr = document.createElement('tr');
                        tr.className = 'hover:bg-slate-50 transition-colors text-xs sm:text-sm';
                        tr.innerHTML = `
                            <td class="px-2 py-1 text-center text-slate-400 font-medium hidden sm:table-cell">${index + 1}</td>
                            <td class="px-2.5 py-1 font-semibold text-slate-800">
                                <div class="truncate max-w-[120px] sm:max-w-none" title="${student.full_name}">${student.full_name}</div>
                                <div class="text-[10px] text-slate-400 font-normal sm:hidden mt-0.5">
                                    ${student.lop ? `Lớp ${student.lop}` : ''} ${student.donvi ? `• ${student.donvi}` : ''}
                                </div>
                                <div class="text-[10px] text-indigo-500 font-normal sm:hidden mt-0.5">
                                    ${isDone ? `⏱️ ${formatReportTime(timeTaken)}` : ''} ${isDone ? `• 📅 ${formattedDoneAt}` : ''}
                                </div>
                            </td>
                            <td class="px-2 py-1 text-center text-slate-500 hidden sm:table-cell">${student.lop || '-'}</td>
                            <td class="px-2 py-1 text-slate-500 text-left truncate max-w-[120px] hidden md:table-cell" title="${student.donvi || '-'}" >${student.donvi || '-'}</td>
                            <td class="px-2 py-1 text-center">
                                ${isDone 
                                    ? `<span class="inline-flex items-center px-1.5 py-0.5 rounded bg-green-50 text-green-700 border border-green-150 text-[10px] font-bold">✅ Đã làm</span>` 
                                    : `<span class="inline-flex items-center px-1.5 py-0.5 rounded bg-rose-50 text-rose-700 border border-rose-150 text-[10px] font-bold">Chưa</span>`
                                }
                            </td>
                            <td class="px-2 py-1 text-center font-bold text-slate-700">${attemptsCount}</td>
                            <td class="px-2 py-1 text-center font-bold ${isDone ? 'text-amber-600' : 'text-slate-400'}">${isDone ? (Number(maxScore) || 0).toFixed(1) : '-'}</td>
                            <td class="px-2 py-1 text-center text-slate-600 font-medium hidden sm:table-cell">${isDone ? formatReportTime(timeTaken) : '-'}</td>
                            <td class="px-2 py-1 text-center text-slate-500 font-medium hidden md:table-cell whitespace-nowrap">${isDone ? formattedDoneAt : '-'}</td>
                            <td class="px-2 py-1 text-center">
                                ${isDone 
                                    ? `<button onclick="deleteStudentReportResults('${dataItem.matchedResultIds.join(',')}', '${student.full_name.replace(/'/g, "\\'")}', '${selectedExamTitle.replace(/'/g, "\\'")}')" class="px-2 py-1 bg-rose-100 hover:bg-rose-200 text-rose-700 rounded text-[10px] font-bold transition-colors">Xóa KQ</button>`
                                    : '-'
                                }
                            </td>
                        `;
                        tbody.appendChild(tr);
                    });

                    // Redraw sort indicators
                    const cols = ['name', 'class', 'unit', 'status', 'attempts', 'score', 'duration', 'time'];
                    cols.forEach(c => {
                        const el = document.getElementById(`sort-icon-${c}`);
                        if (el) {
                            if (c === currentSortCol) {
                                el.textContent = currentSortDir === 'asc' ? ' ▲' : ' ▼';
                                el.className = 'text-indigo-600 font-bold';
                            } else {
                                el.textContent = ' ↕';
                                el.className = 'text-slate-300';
                            }
                        }
                    });

                    const totalStudents = studentDataList.length;
                    const percent = totalStudents > 0 ? Math.round((doneCount / totalStudents) * 100) : 0;

                    document.getElementById('report-stat-total').textContent = totalStudents;
                    document.getElementById('report-stat-done').textContent = doneCount;
                    document.getElementById('report-stat-undone').textContent = undoneCount;
                    document.getElementById('report-stat-percent').textContent = `${percent}%`;
                };

                // Initialize dropdown options
                updateUnitFilterOptions();
                updateClassFilterOptions();

                document.getElementById('report-exam-select')?.addEventListener('change', () => {
                    updateUnitFilterOptions();
                    updateClassFilterOptions();
                    renderReportRows(true);
                });
                document.getElementById('report-unit-select')?.addEventListener('change', () => {
                    updateClassFilterOptions();
                    renderReportRows(false);
                });
                document.getElementById('report-class-select')?.addEventListener('change', () => renderReportRows(false));
                document.getElementById('report-search')?.addEventListener('input', () => renderReportRows(false));

                document.getElementById('btn-export-report-excel').onclick = async () => {
                    const examIdOrName = document.getElementById('report-exam-select')?.value || outsideSelectedExamName || '';
                    const selectedExam = allExamsList.find(e => String(e.id) === String(examIdOrName) || String(e.name) === String(examIdOrName));
                    const selectedExamTitle = (selectedExam ? (selectedExam.name || selectedExam.title || selectedExam.examName || selectedExam.id) : (examIdOrName || outsideSelectedExamName || 'De_Thi')) || 'De_Thi';
                    const unitValue = document.getElementById('report-unit-select')?.value || '';
                    const classValue = document.getElementById('report-class-select')?.value || '';

                    const targetLopRaw = String(selectedExam?.target_lop || selectedExam?.targetLop || selectedExam?.lop || '').trim();
                    const examConfiguredClasses = targetLopRaw
                        ? targetLopRaw.split(/[,;\n]+/).map(s => s.trim().toLowerCase()).filter(Boolean)
                        : [];

                    const teacherClassSet = new Set();
                    if (isTeacherLoggedIn && currentUser) {
                        if (Array.isArray(currentUser.assigned_classes)) {
                            currentUser.assigned_classes.forEach(ac => {
                                const clsName = String(ac.class_name || ac.lop || ac || '').trim().toLowerCase();
                                if (clsName) teacherClassSet.add(clsName);
                            });
                        }
                    }

                    let filteredStudents = filteredStudentUsers.filter(u => {
                        const studentLop = String(u.lop || '').trim().toLowerCase();
                        const studentUnit = String(u.donvi || u.address || '').trim().toLowerCase();

                        if (unitValue && studentUnit !== unitValue.toLowerCase()) return false;

                        if (classValue) {
                            if (studentLop !== classValue.toLowerCase()) return false;
                        } else {
                            if (examConfiguredClasses.length > 0) {
                                if (!examConfiguredClasses.includes(studentLop)) return false;
                            }
                            if (isTeacherLoggedIn && teacherClassSet.size > 0) {
                                if (!teacherClassSet.has(studentLop)) return false;
                            }
                        }
                        return true;
                    });
                    filteredStudents.sort((a, b) => (a.full_name || '').localeCompare(b.full_name || '', 'vi'));

                    const examResults = localResults.filter(r => {
                        if (!r) return false;
                        const rExamId = String(r.examId || r.exam_id || '').trim();
                        const rExamName = String(r.examName || r.exam_name || '').trim().toLowerCase();
                        const targetId = String(selectedExam?.id || examIdOrName || '').trim();
                        const targetName = String(selectedExamTitle || outsideSelectedExamName || '').trim().toLowerCase();
                        return (targetId && rExamId === targetId) || (targetName && rExamName === targetName);
                    });

                    if (filteredStudents.length === 0) {
                        showToast('Không có dữ liệu báo cáo nào để xuất!', 'warning');
                        return;
                    }

                    try {
                        if (typeof ExcelJS === 'undefined' || typeof saveAs === 'undefined') {
                            await ensureExcelJSReady();
                        }

                        const workbook = new ExcelJS.Workbook();
                        const worksheet = workbook.addWorksheet('Báo Cáo Tiến Độ');

                        worksheet.pageSetup.orientation = 'portrait';
                        worksheet.pageSetup.paperSize = 9; // A4
                        worksheet.pageSetup.margins = { left: 0.3, right: 0.3, top: 0.5, bottom: 0.5, header: 0.0, footer: 0.0 };

                        worksheet.mergeCells('A1:I1');
                        const titleCell = worksheet.getCell('A1');
                        const currentAppTitle = (typeof appSettings !== 'undefined' && appSettings && appSettings.appTitle) ? appSettings.appTitle : 'HỆ THỐNG KIỂM TRA TRỰC TUYẾN';
                        titleCell.value = String(currentAppTitle).toUpperCase();
                        titleCell.font = { name: 'Arial', size: 14, bold: true, color: { argb: 'FFFFFFFF' } };
                        titleCell.alignment = { vertical: 'middle', horizontal: 'center' };
                        titleCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
                        worksheet.getRow(1).height = 30;

                        worksheet.mergeCells('A2:I2');
                        const subtitleCell = worksheet.getCell('A2');
                        subtitleCell.value = 'BÁO CÁO TIẾN ĐỘ & KẾT QUẢ THI TRỰC TUYẾN';
                        subtitleCell.font = { name: 'Arial', size: 12, bold: true };
                        subtitleCell.alignment = { vertical: 'middle', horizontal: 'center' };
                        worksheet.getRow(2).height = 25;

                        worksheet.mergeCells('A3:I3');
                        const infoCell = worksheet.getCell('A3');
                        infoCell.value = `Đề thi: ${selectedExamTitle} | Đơn vị: ${unitValue || 'Tất cả'} | Lớp: ${classValue || 'Tất cả'} | Ngày tạo: ${window.formatVNTime(new Date())}`;
                        infoCell.font = { name: 'Arial', size: 9, italic: true };
                        infoCell.alignment = { vertical: 'middle', horizontal: 'center' };
                        worksheet.getRow(3).height = 20;

                        worksheet.addRow([]);

                        const headerRow = worksheet.addRow([
                            'STT', 'Họ và tên học sinh', 'Lớp học', 'Đơn vị / Trường học', 'Trạng thái', 'Số lần làm bài', 'Điểm số cao nhất', 'Thời gian làm bài', 'Nộp bài vào lúc'
                        ]);
                        headerRow.height = 25;
                        headerRow.eachCell((cell) => {
                            cell.font = { name: 'Arial', size: 10, bold: true, color: { argb: 'FFFFFFFF' } };
                            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF475569' } };
                            cell.alignment = { vertical: 'middle', horizontal: 'center' };
                            cell.border = {
                                top: { style: 'thin' }, left: { style: 'thin' },
                                bottom: { style: 'thin' }, right: { style: 'thin' }
                            };
                        });

                        const formatReportTime = (seconds) => {
                            if (seconds === undefined || seconds === null) return '-';
                            const s = Number(seconds) || 0;
                            const mins = Math.floor(s / 60);
                            const secs = s % 60;
                            return `${mins}p ${secs}s`;
                        };

                        filteredStudents.forEach((student, index) => {
                            const studentUid = student.id || student.user_id;
                            const studentUsername = String(student.username || '').toLowerCase().trim();
                            const studentName = String(student.full_name || '').toLowerCase().replace(/\s+/g, ' ').trim();

                            const matchedResults = examResults.filter(r => {
                                if (studentUid && r.userId && String(r.userId) === String(studentUid)) return true;
                                if (studentUid && r.user_id && String(r.user_id) === String(studentUid)) return true;
                                if (studentUsername && r.username && String(r.username).toLowerCase().trim() === studentUsername) return true;
                                const rName = String(r.studentName || r.student_name || r.full_name || '').toLowerCase().replace(/\s+/g, ' ').trim();
                                return rName && rName === studentName;
                            });

                            const attemptsCount = matchedResults.length;
                            const isDone = attemptsCount > 0;
                            
                            let bestAttempt = null;
                            if (isDone) {
                                bestAttempt = matchedResults.reduce((max, attempt) => 
                                    (Number(attempt.score) || 0) > (Number(max.score) || 0) ? attempt : max
                                , matchedResults[0]);
                            }

                            const maxScore = isDone && bestAttempt ? (Number(bestAttempt.score) || 0) : 0;
                            const timeTaken = isDone && bestAttempt ? (Number(bestAttempt.time_taken || bestAttempt.timeTaken) || 0) : 0;
                            const doneAt = isDone && bestAttempt ? (bestAttempt.created_at || bestAttempt.createdAt || bestAttempt.timestamp) : null;
                            const formattedDoneAt = doneAt ? window.formatVNTime(doneAt) : '-';

                            const rRow = worksheet.addRow([
                                index + 1,
                                student.full_name,
                                student.lop || '-',
                                student.donvi || '-',
                                isDone ? 'Đã làm' : 'Chưa',
                                attemptsCount,
                                isDone ? Number((Number(maxScore) || 0).toFixed(1)) : '-',
                                isDone ? formatReportTime(timeTaken) : '-',
                                isDone ? formattedDoneAt : '-'
                            ]);
                            rRow.height = 20;
                            rRow.eachCell((cell, colIndex) => {
                                cell.font = { name: 'Arial', size: 9 };
                                cell.border = {
                                    top: { style: 'thin', color: { argb: 'FFE2E8F0' } },
                                    left: { style: 'thin', color: { argb: 'FFE2E8F0' } },
                                    bottom: { style: 'thin', color: { argb: 'FFE2E8F0' } },
                                    right: { style: 'thin', color: { argb: 'FFE2E8F0' } }
                                };
                                if (colIndex === 1 || colIndex === 3 || colIndex === 5 || colIndex === 6 || colIndex === 7 || colIndex === 8 || colIndex === 9) {
                                    cell.alignment = { vertical: 'middle', horizontal: 'center' };
                                } else {
                                    cell.alignment = { vertical: 'middle', horizontal: 'left' };
                                }

                                if (colIndex === 5) {
                                    cell.font = { name: 'Arial', size: 9, bold: true, color: { argb: isDone ? 'FF15803D' : 'FFBE123C' } };
                                }
                                if (colIndex === 7 && isDone) {
                                    cell.font = { name: 'Arial', size: 9, bold: true, color: { argb: 'FFD97706' } };
                                }
                            });
                        });

                        worksheet.getColumn(1).width = 6;
                        worksheet.getColumn(2).width = 25;
                        worksheet.getColumn(3).width = 10;
                        worksheet.getColumn(4).width = 25;
                        worksheet.getColumn(5).width = 15;
                        worksheet.getColumn(6).width = 12;
                        worksheet.getColumn(7).width = 14;
                        worksheet.getColumn(8).width = 16;
                        worksheet.getColumn(9).width = 22;

                        const buffer = await workbook.xlsx.writeBuffer();
                        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
                        const safeExamTitle = String(selectedExamTitle || 'De_Thi').replace(/[\\/:*?"<>|]/g, '_').replace(/\s+/g, '_');
                        saveAs(blob, `BaoCao_TienDo_${safeExamTitle}.xlsx`);
                        showToast('✅ Đã xuất báo cáo tiến độ thành công!', 'success');
                    } catch (err) {
                        showToast('❌ Lỗi xuất Excel: ' + (err.message || err), 'error');
                    }
                };

                // Perform initial render
                renderReportRows(true);

            } catch (err) {
                console.error(err);
                showToast('❌ Lỗi nạp dữ liệu: ' + (err.message || err), 'error');
            }
        };

        window.deleteStudentReportResults = async function deleteStudentReportResults(idsString, studentName, examName) {
            if (!idsString) return;
            const ids = idsString.split(',').filter(Boolean);
            if (ids.length === 0) return;

            const confirmed = await new Promise(resolve => {
                showConfirmModal(
                    `Bạn có chắc chắn muốn xóa TOÀN BỘ ${ids.length} kết quả làm bài của học sinh <b class="text-rose-600">${studentName}</b> đối với đề thi <b class="text-indigo-600">${examName}</b> không? Thao tác này không thể hoàn tác.`,
                    () => resolve(true),
                    '⚠️ Xác nhận xóa kết quả',
                    'XÓA KẾT QUẢ',
                    'Hủy bỏ',
                    true
                );
                
                // Gia cố: Nếu người dùng đóng modal secondary mà không bấm nút, ta vẫn resolve false
                const checkClosed = setInterval(() => {
                    if (!document.getElementById('secondary-modal-container') || document.getElementById('secondary-modal-container').classList.contains('hidden')) {
                        clearInterval(checkClosed);
                        resolve(false);
                    }
                }, 500);
            });

            if (!confirmed) return;

            const token = localStorage.getItem('auth_token') || localStorage.getItem('token') || (window.currentUser && window.currentUser.token) || '';
            try {
                const res = await fetch('/api/results', {
                    method: 'DELETE',
                    headers: {
                        'Authorization': 'Bearer ' + token,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ ids })
                });

                const data = await res.json();
                if (data.error) {
                    showToast('❌ Lỗi: ' + data.error, 'error');
                } else {
                    showToast(`✅ Đã xóa thành công kết quả của ${studentName}!`, 'success');
                    // Kích hoạt làm mới dữ liệu thông qua event change của select đề thi
                    const examSelect = document.getElementById('report-exam-select');
                    if (examSelect) {
                        examSelect.dispatchEvent(new Event('change'));
                    }
                }
            } catch (err) {
                showToast('❌ Lỗi khi kết nối server: ' + err.message, 'error');
            }
        };

        window.populateRankingExamFilter = populateRankingExamFilter;

        // ==================== PREVENT ACCIDENTS DURING EXAM ====================
        // Ngăn chặn việc học sinh đang làm bài mà vô tình tải lại trang (F5) hoặc đóng tab
        window.addEventListener('beforeunload', (e) => {
            const examInterface = document.getElementById('exam-interface');
            const examResults = document.getElementById('exam-results');
            
            // Kiểm tra xem giao diện thi có đang hiển thị không (exam-interface không bị hidden) 
            // và giao diện kết quả có đang ẩn không (exam-results bị hidden)
            const isExamVisible = examInterface && !examInterface.classList.contains('hidden');
            const isResultsHidden = examResults && examResults.classList.contains('hidden');
            
            // Kiểm tra trạng thái dữ liệu bài thi (đã bắt đầu làm bài và có câu hỏi)
            const isExamStateActive = typeof currentExam !== 'undefined' && currentExam && currentExam.questions && currentExam.questions.length > 0 && currentExam.startTime;

            if (isExamVisible && isResultsHidden && isExamStateActive) {
                // Tiêu chuẩn hiện đại: e.preventDefault() và gán e.returnValue là đủ để trình duyệt hiện cảnh báo
                // Ghi chú: Nội dung chuỗi tùy chỉnh có thể không hiển thị trên các trình duyệt hiện đại (Chrome, Edge), 
                // họ sử dụng thông báo mặc định của hệ thống để bảo mật.
                e.preventDefault();
                e.returnValue = 'Bạn đang làm bài thi. Nếu bạn tải lại trang hoặc thoát, kết quả làm bài của bạn sẽ bị mất. Bạn có chắc chắn muốn thoát?';
                return e.returnValue;
            }
        });
    
